window.VERITY_ENGINE_FILES = {"__init__.py": "\"\"\"Verity Family Wealth Engine E0.\n\nHousehold wealth outcome decision support. No production authority.\n\"\"\"\n\nfrom engine.constants import ALGORITHM_VERSION, PRODUCTION_AUTHORITY, RELEASE_GATE\n\n__all__ = [\"ALGORITHM_VERSION\", \"PRODUCTION_AUTHORITY\", \"RELEASE_GATE\"]\n", "allocation.py": "\"\"\"Multi-asset simulated allocation.\n\nE0 never trades. It simulates, under a fixed and documented model, an allocation that\nrespects the household's loss budget, and it refuses to build a growth portfolio for a\nfamily that cannot survive one.\n\nKey discipline: the simulated drawdown implied by the model's crash assumptions must fit\ninside ``max_tolerable_loss_pct``. Risk capacity, not return appetite, sets the ceiling.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport random\nfrom statistics import mean, pstdev\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    ASSET_CLASSES,\n    ASSET_CLASS_MODEL,\n    DEFAULT_SEED,\n    OPTION_PROTECTION_COST_RATE,\n    SIMULATION_ITERATIONS,\n)\n\n#: Weights used when the engine refuses to build a growth plan.\nDEFENSIVE_WEIGHTS = {\n    \"cash\": 0.75,\n    \"bond\": 0.25,\n    \"global_index\": 0.0,\n    \"equity\": 0.0,\n    \"gold\": 0.0,\n    \"option_protection\": 0.0,\n}\n\n\ndef _number(value, default=0.0):\n    if isinstance(value, bool) or value is None:\n        return default\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return default\n    if number != number or number in (float(\"inf\"), float(\"-inf\")):\n        return default\n    return number\n\n\ndef _clamp(value, low, high):\n    return max(low, min(high, value))\n\n\ndef _normalise(weights):\n    total = sum(weights.values())\n    if total <= 0:\n        return {name: (1.0 if name == \"cash\" else 0.0) for name in ASSET_CLASSES}\n    normalised = {name: weight / total for name, weight in weights.items()}\n    drift = 1.0 - sum(normalised.values())\n    normalised[\"cash\"] = normalised.get(\"cash\", 0.0) + drift\n    return {name: round(normalised.get(name, 0.0), 10) for name in ASSET_CLASSES}\n\n\ndef _crash_drawdown(weights):\n    drawdown = 0.0\n    for name in ASSET_CLASSES:\n        drawdown += weights.get(name, 0.0) * ASSET_CLASS_MODEL[name][2]\n    return drawdown\n\n\ndef _fit_to_loss_budget(weights, tolerance):\n    \"\"\"Shift risk into bonds until the modelled crash fits the family's loss budget.\"\"\"\n    weights = dict(weights)\n    for _ in range(200):\n        drawdown = _crash_drawdown(weights)\n        if drawdown >= -tolerance - 1e-12:\n            return weights, True\n        for source in (\"equity\", \"global_index\", \"gold\", \"option_protection\"):\n            if weights.get(source, 0.0) >= 0.02:\n                weights[source] -= 0.02\n                weights[\"bond\"] = weights.get(\"bond\", 0.0) + 0.02\n                break\n        else:\n            return weights, False\n    return weights, _crash_drawdown(weights) >= -tolerance - 1e-12\n\n\ndef _insurance_need(profile, total_assets):\n    income = 0.0\n    for member in profile.get(\"members\") or []:\n        if isinstance(member, dict):\n            income += max(0.0, _number(member.get(\"annual_income\"), 0.0))\n    essential = max(0.0, _number(profile.get(\"annual_expenses_essential\"), 0.0))\n\n    life_coverage = 0.0\n    disability_coverage = 0.0\n    for policy in profile.get(\"protection\") or []:\n        if not isinstance(policy, dict):\n            continue\n        kind = policy.get(\"kind\")\n        if kind == \"life\":\n            life_coverage += max(0.0, _number(policy.get(\"coverage\"), 0.0))\n        elif kind == \"disability\":\n            disability_coverage += max(0.0, _number(policy.get(\"coverage\"), 0.0))\n\n    return {\n        \"life\": max(0.0, round(income * 10.0 - life_coverage, 2)),\n        \"disability\": max(0.0, round(income * 0.6 - disability_coverage, 2)),\n        \"health\": round(essential, 2),\n        \"note\": (\n            \"Indicative coverage sizing only. Verity recommends no specific insurer or product; \"\n            \"any actual placement requires a licensed partner.\"\n        ),\n    }\n\n\ndef simulate_allocation(profile, layers, feasibility, seed=DEFAULT_SEED):\n    \"\"\"Simulate a multi-asset allocation for one household. Never trades.\"\"\"\n    profile = profile if isinstance(profile, dict) else {}\n    layers = layers if isinstance(layers, dict) else {}\n    feasibility = feasibility if isinstance(feasibility, dict) else {}\n\n    verdict = feasibility.get(\"verdict\", \"ABSTAIN\")\n    tolerance = _number(profile.get(\"max_tolerable_loss_pct\"), None)\n    total_assets = _number(layers.get(\"total_assets\"), 0.0)\n    fractions = layers.get(\"fractions\") or {}\n    iterations = SIMULATION_ITERATIONS\n\n    executed = verdict in (\"PASS\", \"REVIEW\")\n\n    if not executed or tolerance is None or total_assets <= 0:\n        weights = dict(DEFENSIVE_WEIGHTS)\n        constrained = True\n        constraint_note = (\n            \"Defensive placement only: the engine did not authorise a growth allocation.\"\n            if not executed\n            else \"Defensive placement only: no allocatable assets were recorded.\"\n        )\n    else:\n        survival_frac = _number(fractions.get(\"survival\"), 0.0)\n        near_frac = _number(fractions.get(\"near_term_duty\"), 0.0)\n        protection_frac = _number(fractions.get(\"protection\"), 0.0)\n        growth_frac = _number(fractions.get(\"long_term_growth\"), 0.0)\n        high_frac = _number(fractions.get(\"high_risk_opportunity\"), 0.0)\n\n        # Lower loss tolerance buys more explicit protection.\n        hedge_share = _clamp(0.35 - tolerance, 0.02, 0.30)\n        growth_pool = max(0.0, growth_frac + high_frac)\n        option_weight = hedge_share * growth_pool\n        rest = max(0.0, growth_pool - option_weight)\n\n        # Risk appetite scales equity exposure, never the other way round.\n        risk_appetite = _clamp((tolerance - 0.15) / 0.35, 0.0, 1.0)\n        equity_share = 0.10 + 0.30 * risk_appetite\n        gold_share = 0.15\n        index_share = max(0.0, 1.0 - equity_share - gold_share)\n\n        weights = {\n            \"cash\": survival_frac + 0.30 * near_frac,\n            \"bond\": 0.70 * near_frac + protection_frac,\n            \"global_index\": rest * index_share,\n            \"equity\": rest * equity_share,\n            \"gold\": rest * gold_share,\n            \"option_protection\": option_weight,\n        }\n        weights, constrained = _fit_to_loss_budget(weights, tolerance)\n        constraint_note = (\n            \"Risk exposure was reduced until the modelled crash fitted the family loss budget.\"\n            if constrained\n            else \"Even the defensive placement exceeds the stated loss budget.\"\n        )\n\n    weights = _normalise(weights)\n    drawdown = _crash_drawdown(weights)\n\n    rng = random.Random(seed)\n    portfolio_returns = []\n    for _ in range(iterations):\n        year = 0.0\n        for name in ASSET_CLASSES:\n            mu, sigma, _ = ASSET_CLASS_MODEL[name]\n            weight = weights.get(name, 0.0)\n            if weight:\n                year += weight * rng.gauss(mu, sigma)\n        portfolio_returns.append(year)\n\n    ordered = sorted(portfolio_returns)\n    percentile_index = max(0, min(len(ordered) - 1, int(0.05 * len(ordered))))\n    simulated_return = mean(portfolio_returns)\n    simulated_volatility = pstdev(portfolio_returns)\n    simulated_drawdown = min(0.0, ordered[percentile_index])\n\n    allocation_amounts = {name: round(weights[name] * total_assets, 2) for name in ASSET_CLASSES}\n\n    return {\n        \"allocation\": allocation_amounts,\n        \"allocation_weights\": weights,\n        \"executed\": executed,\n        \"risk_budget_fit\": constrained,\n        \"risk_budget_note\": constraint_note,\n        \"modelled_crash_drawdown\": round(drawdown, 6),\n        \"simulated_annual_return\": round(simulated_return, 6),\n        \"simulated_volatility\": round(simulated_volatility, 6),\n        \"simulated_max_drawdown\": round(simulated_drawdown, 6),\n        \"protection_cost\": round(weights[\"option_protection\"] * total_assets * OPTION_PROTECTION_COST_RATE, 2),\n        \"insurance_need\": _insurance_need(profile, total_assets),\n        \"iterations\": iterations,\n        \"seed\": seed,\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": (\n                \"priority-weighted allocation fitted to the family loss budget, then \"\n                f\"{iterations} seeded Monte Carlo paths over documented asset-class assumptions\"\n            ),\n            \"assumptions\": [\n                \"Simulated returns are scenarios under a fixed model, not forecasts and not real performance.\",\n                \"No transaction, tax or custody cost is modelled beyond the option protection premium rate.\",\n                \"Asset classes are broad categories; no specific security, fund or insurer is selected.\",\n                f\"Loss fit uses fixed crash assumptions per asset class, tolerance {tolerance}.\",\n            ],\n            \"computed_at_utc\": None,\n            \"sources\": [\"docs/INTERFACE_FREEZE_V0_1.md\"],\n        },\n    }\n", "annual_goal.py": "\"\"\"Annual goal progress and the take-profit state machine (T-E0-044).\n\nThe household's long-term money is only what is left *after* the survival floor and the\nchildren's education money have been ring-fenced (``engine/layering.py``). This module\nanswers the two questions that decide whether the family keeps taking risk with it:\n\n1. **How much does this money have to earn this year?**\n   ``年度目标金额 = 长期资金 × 家庭自己记录的目标年化回报``. Verity never assumes and\n   never projects a return: the target side is the family's own recorded number applied to\n   the money that is genuinely available, and the realised side is read only from what the\n   family recorded (``profile.annual_goal.recorded_net_gain``). When the realised side is\n   not recorded the section says so instead of inferring it, because \"证据不足\" is not\n   \"达标\".\n2. **When must new risk stop?** A state machine evaluated in a fixed precedence order,\n   because for a household that depends on one income the order *is* the answer:\n   保护缺口 -> 生存底线 -> 损失预算 -> 止盈状态。\n\nEverything is arithmetic on recorded values. No premium is quoted, no product is\nrecommended, no return is promised, and when the basis (long-term money, or a positive\ntarget return) is missing the module abstains rather than inventing a target.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom engine.constants import (\n    LAYER_HIGH_RISK_SHARE,\n    LAYER_LONG_TERM_SHARE,\n    RIGID_CAPITAL_WINDOW_YEARS,\n    ALGORITHM_VERSION,\n    ANNUAL_GOAL_ACHIEVED_RATIO,\n    ANNUAL_GOAL_DRAWDOWN_ALERT_RATIO,\n    ANNUAL_GOAL_LOCK_PROFIT_RATIO,\n    ANNUAL_GOAL_MILESTONES,\n    ANNUAL_GOAL_MIN_SURVIVAL_DAYS,\n    MATERIALITY,\n)\n\nSTATUS_OK = \"OK\"\nSTATUS_ABSTAIN = \"ABSTAIN\"\n\nSTATE_EVIDENCE_INSUFFICIENT = \"EVIDENCE_INSUFFICIENT\"\nSTATE_PROTECTION_FIRST = \"PROTECTION_FIRST\"\nSTATE_REDUCE_RISK_FIRST = \"REDUCE_RISK_FIRST\"\nSTATE_PROGRESS_NOT_RECORDED = \"PROGRESS_NOT_RECORDED\"\nSTATE_CONTINUE_ON_PLAN = \"CONTINUE_ON_PLAN\"\nSTATE_LOCK_PARTIAL = \"LOCK_PARTIAL\"\nSTATE_STOP_ADDING_RISK = \"STOP_ADDING_RISK\"\n\nSTATE_LABELS_CN = {\n    STATE_EVIDENCE_INSUFFICIENT: \"证据不足（弃权）\",\n    STATE_PROTECTION_FIRST: \"先补保障，暂不新增风险\",\n    STATE_REDUCE_RISK_FIRST: \"先降风险，再谈目标\",\n    STATE_PROGRESS_NOT_RECORDED: \"闸门通过，但本年进度未记录\",\n    STATE_CONTINUE_ON_PLAN: \"按计划继续\",\n    STATE_LOCK_PARTIAL: \"接近目标，锁定部分利润\",\n    STATE_STOP_ADDING_RISK: \"已达目标，停止新增风险\",\n}\n\nPROGRESS_ACHIEVED = \"ACHIEVED\"\nPROGRESS_APPROACHING = \"APPROACHING\"\nPROGRESS_BEHIND = \"BEHIND\"\nPROGRESS_NOT_RECORDED = \"NOT_RECORDED\"\n\nPROGRESS_LABELS_CN = {\n    PROGRESS_ACHIEVED: \"已达成\",\n    PROGRESS_APPROACHING: \"接近达成\",\n    PROGRESS_BEHIND: \"尚未达成\",\n    PROGRESS_NOT_RECORDED: \"未记录\",\n}\n\n#: 用户可见口径句：必须与真实算法逐字一致（T-E0-045 H-04 残留文案修正）。\n#: 算法只隔离「应急金目标 + 窗口内到期的刚性支出 + 一年保障保费」；窗口外的刚性支出\n#: 由长期资金承担，并按到期月份在月度投影中扣除。窗口年限来自唯一来源常量。\nFORMULA_CN = (\n    \"年度目标金额 = 长期资金（隔离应急金目标、\"\n    f\"{RIGID_CAPITAL_WINDOW_YEARS:g} 年内到期的刚性支出与一年保障保费之后，\"\n    f\"剩余资本按 {LAYER_LONG_TERM_SHARE:.0%} / {LAYER_HIGH_RISK_SHARE:.0%} 拆分中的长期增值部分）\"\n    \"× 家庭自己记录的目标年化回报；\"\n    f\"窗口外（超过 {RIGID_CAPITAL_WINDOW_YEARS:g} 年）到期的刚性支出（如多年后的教育金）\"\n    \"由这笔长期资金承担，并在月度投影中按其到期月份扣除\"\n)\n\nREASON_ABSTAIN_BASIS = \"ANNUAL_GOAL_BASIS_UNRECORDED\"\nREASON_ABSTAIN_TARGET = \"ANNUAL_GOAL_TARGET_UNRECORDED\"\n\n\ndef _number(value, default=None):\n    if isinstance(value, bool) or value is None:\n        return default\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return default\n    if number != number or number in (float(\"inf\"), float(\"-inf\")):\n        return default\n    return number\n\n\ndef _money(value):\n    number = _number(value)\n    return None if number is None else round(number, 2)\n\n\ndef _long_term_money(layers):\n    \"\"\"The residual long-term sleeve produced by ``engine/layering.py``.\"\"\"\n    if not isinstance(layers, dict):\n        return None\n    bucket = layers.get(\"layers\")\n    if not isinstance(bucket, dict):\n        bucket = layers\n    return _number(bucket.get(\"long_term_growth\"))\n\n\ndef _rigid_split(layers):\n    \"\"\"单一来源：直接引用 »engine.layering.rigid_outflow_split« 的分类结果（T-E0-045 / H-04）。\"\"\"\n    if not isinstance(layers, dict):\n        return {\"within_window_total\": None, \"beyond_window_total\": None, \"window_years\": None}\n    split = layers.get(\"rigid_split\")\n    if not isinstance(split, dict):\n        return {\"within_window_total\": None, \"beyond_window_total\": None, \"window_years\": None}\n    return split\n\n\ndef _text(value):\n    if value is None or isinstance(value, bool):\n        return None\n    if isinstance(value, (int, float)):\n        return str(int(value))\n    if isinstance(value, str) and value.strip():\n        return value\n    return None\n\n\ndef _abstain(profile, reason_code, reason_cn):\n    return {\n        \"status\": STATUS_ABSTAIN,\n        \"status_reason\": reason_cn,\n        \"reason_codes\": [reason_code],\n        \"currency\": profile.get(\"currency\"),\n        \"state\": STATE_EVIDENCE_INSUFFICIENT,\n        \"state_label_cn\": STATE_LABELS_CN[STATE_EVIDENCE_INSUFFICIENT],\n        \"state_finding_cn\": reason_cn,\n        \"formula_cn\": FORMULA_CN,\n        \"basis\": {},\n        \"milestones\": [],\n        \"progress\": {\"recorded\": False, \"status\": PROGRESS_NOT_RECORDED},\n        \"guardrails\": {},\n        \"lock_profit_condition_cn\": None,\n        \"stop_risk_condition_cn\": None,\n        \"actions\": [],\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": \"annual-goal analysis abstained without sufficient recorded evidence.\",\n            \"assumptions\": [],\n            \"sources\": [],\n            \"computed_at_utc\": None,\n        },\n    }\n\n\ndef analyse_annual_goal(profile, layers=None, safety=None, allocation=None, breadwinner=None):\n    \"\"\"Annual target amount, recorded progress, and the take-profit state machine.\"\"\"\n    if not isinstance(profile, dict):\n        profile = {}\n\n    long_term_money = _long_term_money(layers)\n    if long_term_money is None or long_term_money <= MATERIALITY:\n        return _abstain(\n            profile,\n            REASON_ABSTAIN_BASIS,\n            \"没有记录到可用于长期增值的资金（先隔离应急金目标、\"\n            f\"{RIGID_CAPITAL_WINDOW_YEARS:g} 年内到期的刚性支出与一年保障保费之后仍为正数的部分），\"\n            \"年度目标金额无处可算，按失败关闭处理（弃权）。\",\n        )\n\n    target_return = _number(profile.get(\"target_annual_return\"))\n    if target_return is None or target_return <= MATERIALITY:\n        return _abstain(\n            profile,\n            REASON_ABSTAIN_TARGET,\n            \"没有记录到大于零的目标年化回报，年度目标金额无法计算，按失败关闭处理（弃权）。\",\n        )\n\n    currency = profile.get(\"currency\")\n    target_amount = long_term_money * target_return\n    monthly_target = target_amount / 12.0\n    horizon_years = _number(profile.get(\"investment_horizon_years\"))\n\n    milestones = []\n    for ratio in ANNUAL_GOAL_MILESTONES:\n        milestones.append(\n            {\n                \"ratio\": ratio,\n                \"label_cn\": f\"{ratio * 100:.0f}%\",\n                \"amount\": _money(target_amount * ratio),\n                \"remaining\": _money(max(0.0, target_amount * (1.0 - ratio))),\n            }\n        )\n\n    recorded_block = profile.get(\"annual_goal\")\n    recorded_block = recorded_block if isinstance(recorded_block, dict) else {}\n    recorded_gain = _number(recorded_block.get(\"recorded_net_gain\"))\n    locked_profit = _number(recorded_block.get(\"locked_profit\"))\n    recorded_as_of = _text(recorded_block.get(\"recorded_as_of\")) or _text(recorded_block.get(\"year\"))\n\n    progress_ratio = None\n    remaining_amount = None\n    if recorded_gain is not None:\n        progress_ratio = recorded_gain / target_amount\n        remaining_amount = max(0.0, target_amount - recorded_gain)\n        if progress_ratio >= ANNUAL_GOAL_ACHIEVED_RATIO:\n            progress_status = PROGRESS_ACHIEVED\n        elif progress_ratio >= ANNUAL_GOAL_LOCK_PROFIT_RATIO:\n            progress_status = PROGRESS_APPROACHING\n        else:\n            progress_status = PROGRESS_BEHIND\n    else:\n        progress_status = PROGRESS_NOT_RECORDED\n\n    max_tolerable_loss = _number(profile.get(\"max_tolerable_loss_pct\"))\n    drawdown = None\n    if isinstance(allocation, dict):\n        recorded_drawdown = _number(allocation.get(\"simulated_max_drawdown\"))\n        if recorded_drawdown is not None:\n            drawdown = abs(recorded_drawdown)\n    drawdown_within_budget = None\n    if drawdown is not None and max_tolerable_loss is not None:\n        drawdown_within_budget = drawdown <= max_tolerable_loss + MATERIALITY\n    drawdown_alert = None\n    if max_tolerable_loss is not None:\n        drawdown_alert = max_tolerable_loss * ANNUAL_GOAL_DRAWDOWN_ALERT_RATIO\n\n    safety_days = None\n    cash_gap = None\n    if isinstance(safety, dict):\n        safety_days = _number(safety.get(\"safety_days\"))\n        cash_gap = _number(safety.get(\"cash_gap\"))\n    survival_ok = None if safety_days is None else safety_days >= ANNUAL_GOAL_MIN_SURVIVAL_DAYS\n\n    protection_gap = None\n    gap_status = None\n    if isinstance(breadwinner, dict):\n        gap_block = breadwinner.get(\"protection_gap\")\n        if isinstance(gap_block, dict):\n            protection_gap = _number(gap_block.get(\"gap_after_insurance\"))\n            gap_status = gap_block.get(\"status\")\n    protection_covered = None if protection_gap is None else protection_gap <= MATERIALITY\n\n    actions = []\n    state = STATE_CONTINUE_ON_PLAN\n\n    if protection_covered is False:\n        state = STATE_PROTECTION_FIRST\n        actions.append(\n            {\n                \"priority\": \"P0\",\n                \"action_cn\": f\"先把顶梁柱保护缺口补上（缺口 {protection_gap:,.0f}），再谈本年收益目标\",\n                \"rationale\": (\n                    \"顶梁柱一旦出事，这笔长期资金会被迫用于刚性支出，目标再漂亮也守不住；\"\n                    \"保障没补齐之前，新增风险等于把家庭生存续期押在市场上。\"\n                ),\n                \"amount\": _money(protection_gap),\n            }\n        )\n    elif survival_ok is False:\n        state = STATE_REDUCE_RISK_FIRST\n        actions.append(\n            {\n                \"priority\": \"P0\",\n                \"action_cn\": (\n                    f\"先把生存底线补到 {ANNUAL_GOAL_MIN_SURVIVAL_DAYS:.0f} 天以上\"\n                    f\"（当前 {safety_days:,.0f} 天），再谈本年目标\"\n                ),\n                \"rationale\": \"生存底线不足时，任何波动都可能迫使家庭在最差的时点卖出长期资金。\",\n                \"amount\": _money(cash_gap),\n            }\n        )\n    elif drawdown_within_budget is False:\n        state = STATE_REDUCE_RISK_FIRST\n        actions.append(\n            {\n                \"priority\": \"P0\",\n                \"action_cn\": (\n                    f\"把组合最大回撤压回可承受损失以内（模拟回撤 {drawdown * 100:,.1f}% > 记录的可承受损失 \"\n                    f\"{max_tolerable_loss * 100:,.1f}%）\"\n                ),\n                \"rationale\": (\n                    \"回撤超过家庭自己写下的损失预算时，最容易发生的不是亏钱，而是在最低点放弃计划。\"\n                ),\n                \"amount\": None,\n            }\n        )\n    elif progress_status == PROGRESS_NOT_RECORDED:\n        state = STATE_PROGRESS_NOT_RECORDED\n        actions.append(\n            {\n                \"priority\": \"P1\",\n                \"action_cn\": \"记录本年已实现净收益（本机记录即可），年度进度才能判断\",\n                \"rationale\": \"证据不足不等于达标：没有记录已实现收益时，Verity 不会替你假设赚了多少。\",\n                \"amount\": _money(target_amount),\n            }\n        )\n    elif progress_status == PROGRESS_ACHIEVED:\n        state = STATE_STOP_ADDING_RISK\n        actions.append(\n            {\n                \"priority\": \"P0\",\n                \"action_cn\": \"本年目标已达成：停止新增风险，不再加仓、不再提高敞口\",\n                \"rationale\": (\n                    \"达标之后继续承担风险，只增加下行，不增加已经拿到的结果；\"\n                    \"把长期资金再平衡回目标权重即可。\"\n                ),\n                \"amount\": _money(recorded_gain - target_amount),\n            }\n        )\n        actions.append(\n            {\n                \"priority\": \"P1\",\n                \"action_cn\": (\n                    \"把超过目标的部分优先转入应急金目标与 \"\n                    f\"{RIGID_CAPITAL_WINDOW_YEARS:g} 年内到期的刚性资金\"\n                ),\n                \"rationale\": (\n                    \"先加固生存与教育这两件不能失败的事，再考虑继续增值；\"\n                    \"这也是 Verity 的资金分层顺序。\"\n                ),\n                \"amount\": _money(max(0.0, recorded_gain - target_amount)),\n            }\n        )\n    elif progress_status == PROGRESS_APPROACHING:\n        state = STATE_LOCK_PARTIAL\n        lock_amount = None\n        if max_tolerable_loss is not None:\n            lock_amount = recorded_gain * max_tolerable_loss\n        actions.append(\n            {\n                \"priority\": \"P0\",\n                \"action_cn\": \"锁定部分利润，把已经拿到的收益从风险里拿出来\",\n                \"rationale\": (\n                    \"按家庭记录的损失预算，若组合用满 \"\n                    + (f\"{max_tolerable_loss * 100:,.1f}%\" if max_tolerable_loss is not None else \"已记录的损失预算\")\n                    + \" 的回撤，这部分收益会被原样回吐；先落袋它，剩下的敞口才与家庭写下的承受力一致。\"\n                ),\n                \"amount\": _money(lock_amount),\n            }\n        )\n    else:\n        state = STATE_CONTINUE_ON_PLAN\n        actions.append(\n            {\n                \"priority\": \"P1\",\n                \"action_cn\": \"按原计划继续，并按季度记录已实现收益与损失\",\n                \"rationale\": \"进度落后时先看记录是否完整，而不是先把风险加上去。\",\n                \"amount\": _money(remaining_amount),\n            }\n        )\n\n    if state == STATE_STOP_ADDING_RISK and drawdown_alert is not None and drawdown is not None:\n        if drawdown > drawdown_alert + MATERIALITY:\n            actions.append(\n                {\n                    \"priority\": \"P1\",\n                    \"action_cn\": (\n                        f\"把仍然暴露的最大回撤压到 {drawdown_alert * 100:,.1f}% 以内\"\n                        f\"（当前模拟回撤 {drawdown * 100:,.1f}%）\"\n                    ),\n                    \"rationale\": \"达标之后，剩余敞口的唯一作用就是制造回撤。\",\n                    \"amount\": None,\n                }\n            )\n\n    state_label = STATE_LABELS_CN[state]\n    lock_condition = (\n        f\"已记录本年净收益 ≥ 年度目标金额 × {ANNUAL_GOAL_LOCK_PROFIT_RATIO:.0%}\"\n        f\"（即 ≥ {target_amount * ANNUAL_GOAL_LOCK_PROFIT_RATIO:,.0f}）时，进入「锁定部分利润」。\"\n    )\n    stop_condition = (\n        f\"已记录本年净收益 ≥ 年度目标金额（即 ≥ {target_amount:,.0f}）时，进入「停止新增风险」：\"\n        \"不再加仓、不再提高敞口，只做回到目标权重的再平衡。\"\n    )\n\n    if progress_ratio is None:\n        progress_cn = (\n            f\"本年已实现净收益未记录，进度无法判断（年度目标金额 {target_amount:,.0f}）。\"\n        )\n    else:\n        progress_cn = (\n            f\"本年已记录净收益 {recorded_gain:,.0f}，占年度目标 \"\n            f\"{progress_ratio * 100:,.1f}%，{PROGRESS_LABELS_CN[progress_status]}，\"\n            f\"距离目标还差 {remaining_amount:,.0f}。\"\n        )\n\n    status_reason = (\n        f\"长期资金（先隔离应急金目标、{RIGID_CAPITAL_WINDOW_YEARS:g} 年内到期的刚性支出与一年保障保费\"\n        f\"之后）{long_term_money:,.0f}，按家庭记录的目标年化回报 \"\n        f\"{target_return * 100:,.2f}% 计算，本年目标金额 {target_amount:,.0f}。{progress_cn}\"\n        f\"当前状态：{state_label}。\"\n    )\n\n    return {\n        \"status\": STATUS_OK,\n        \"status_reason\": status_reason,\n        \"reason_codes\": [],\n        \"currency\": currency,\n        \"state\": state,\n        \"state_label_cn\": state_label,\n        \"state_finding_cn\": status_reason,\n        \"formula_cn\": FORMULA_CN,\n        \"basis\": {\n            \"long_term_growth\": _money(long_term_money),\n            \"rigid_within_window\": _money(_rigid_split(layers)[\"within_window_total\"]),\n            \"rigid_beyond_window\": _money(_rigid_split(layers)[\"beyond_window_total\"]),\n            \"rigid_capital_window_years\": _rigid_split(layers)[\"window_years\"],\n            \"target_annual_return\": target_return,\n            \"target_amount\": _money(target_amount),\n            \"monthly_target\": _money(monthly_target),\n            \"horizon_years\": horizon_years,\n            \"ring_fence_note_cn\": (\n                \"长期资金 = （家庭总资产 − 应急金目标 − 窗口内刚性支出（\"\n                f\"{_rigid_split(layers)['window_years']} 年内到期）− 一年保障保费）\"\n                f\"× {LAYER_LONG_TERM_SHARE:.0%}（其余 {LAYER_HIGH_RISK_SHARE:.0%} 是高风险机会袖套）；\"\n                \"它不是家庭总资产，也没有把教育等刚性资金全部隔离 —— 只有窗口内到期的部分被隔离。\"\n                \"窗口外到期的刚性支出（如多年后的教育金）不占用这笔现金隔离池，而是由长期资金承担，\"\n                \"并按到期月份在月度投影中扣除。\"\n            ),\n        },\n        \"milestones\": milestones,\n        \"progress\": {\n            \"recorded\": recorded_gain is not None,\n            \"status\": progress_status,\n            \"status_label_cn\": PROGRESS_LABELS_CN[progress_status],\n            \"recorded_net_gain\": _money(recorded_gain),\n            \"locked_profit\": _money(locked_profit),\n            \"recorded_as_of\": recorded_as_of,\n            \"progress_ratio\": None if progress_ratio is None else round(progress_ratio, 4),\n            \"remaining_amount\": _money(remaining_amount),\n            \"target_amount\": _money(target_amount),\n            \"note_cn\": (\n                \"已实现净收益只按家庭自己记录的数字读取；Verity 不推算、不假设任何实际收益。\"\n            ),\n        },\n        \"guardrails\": {\n            \"max_tolerable_loss_pct\": max_tolerable_loss,\n            \"simulated_max_drawdown\": None if drawdown is None else round(drawdown, 6),\n            \"drawdown_within_budget\": drawdown_within_budget,\n            \"drawdown_alert_pct\": drawdown_alert,\n            \"safety_days\": None if safety_days is None else round(safety_days, 2),\n            \"min_survival_days\": ANNUAL_GOAL_MIN_SURVIVAL_DAYS,\n            \"survival_ok\": survival_ok,\n            \"cash_gap\": _money(cash_gap),\n            \"protection_gap\": _money(protection_gap),\n            \"protection_gap_status\": gap_status,\n            \"protection_covered\": protection_covered,\n        },\n        \"lock_profit_condition_cn\": lock_condition,\n        \"stop_risk_condition_cn\": stop_condition,\n        \"actions\": actions,\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": (\n                \"annual target = residual long-term money (after survival floor and ring-fenced \"\n                \"rigid outflows) x the household's own recorded target return; the take-profit \"\n                \"state machine is evaluated in a fixed precedence order: protection gap, survival \"\n                \"floor, recorded loss budget, then recorded progress.\"\n            ),\n            \"assumptions\": [\n                \"The annual target is applied to the residual long-term sleeve, never to gross assets.\",\n                f\"Realised progress is read only from the recorded value; no return is projected.\",\n                f\"Partial profit-taking starts at {ANNUAL_GOAL_LOCK_PROFIT_RATIO:.0%} of the annual target.\",\n                f\"New risk stops at {ANNUAL_GOAL_ACHIEVED_RATIO:.0%} of the annual target.\",\n                f\"A survival floor below {ANNUAL_GOAL_MIN_SURVIVAL_DAYS:.0f} days is repaired first.\",\n                \"A run-rate drawdown above the recorded loss budget is repaired before the goal is pursued.\",\n            ],\n            \"sources\": [\n                \"engine.layering:layers.long_term_growth\",\n                \"engine.safety:safety_days\",\n                \"engine.allocation:simulated_max_drawdown\",\n                \"engine.breadwinner:protection_gap.gap_after_insurance\",\n            ],\n            \"computed_at_utc\": None,\n        },\n    }\n", "breadwinner.py": "\"\"\"Breadwinner identification and the household protection gap.\n\nThe mission of the product starts here: *if the person the family depends on dies,\nis disabled, or loses their income for a long time, does basic family life hold, and\ndoes the children's education continue?*\n\nThis module answers exactly three questions, in this order:\n\n1. **Who carries this household?** Members are ranked by recorded income; a member\n   carrying at least ``BREADWINNER_SHARE_FLOOR`` of gross income is a breadwinner.\n   Above ``BREADWINNER_CONCENTRATION_SHARE`` the household has a single point of failure.\n2. **How big is the hole?** The need is survival floor + recorded rigid future\n   outflows (education) + one year of mandatory debt service. It is measured twice:\n   against what the family already holds, and against what the family would hold\n   after the payout that this specific event actually triggers.\n3. **What happens in each event?** Death, disability/critical illness and long-term\n   job loss are simulated one by one, with the education money ring-fenced before any\n   other spending, so education continuity is a computed result and not a promise.\n\nEverything is arithmetic on recorded values. Nothing is inferred about a real person,\nno premium is quoted, and no product is recommended: when income or the essential\nspending baseline is missing, the whole module abstains.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    BREADWINNER_CONCENTRATION_SHARE,\n    BREADWINNER_EVENT_PAYOUT_KINDS,\n    BREADWINNER_EVENT_RETENTION,\n    BREADWINNER_EVENTS,\n    BREADWINNER_SHARE_FLOOR,\n    DAYS_PER_MONTH,\n    DEFAULT_SURVIVAL_TARGET_DAYS,\n    EDUCATION_MARKERS,\n    EVENT_DEATH,\n    EVENT_DISABILITY,\n    EVENT_JOB_LOSS,\n    MATERIALITY,\n    PROTECTION_GAP_COVERED_RATIO,\n    PROTECTION_GAP_CRITICAL_MONTHS,\n    PROTECTION_GAP_PARTIAL_RATIO,\n)\nfrom engine.layering import (\n    RIGID_WITHIN_WINDOW,\n    classify_rigid_outflow,\n    rigid_outflow_split,\n)\n\nSTATUS_OK = \"OK\"\nSTATUS_ABSTAIN = \"ABSTAIN\"\n\nSCENARIO_SURVIVES = \"SURVIVES\"\nSCENARIO_STRESSED = \"STRESSED\"\nSCENARIO_COLLAPSES = \"COLLAPSES\"\n\nGAP_COVERED = \"COVERED\"\nGAP_PARTIAL = \"PARTIAL\"\nGAP_OPEN = \"OPEN\"\n\nEDUCATION_PROTECTED = \"PROTECTED\"\nEDUCATION_AT_RISK = \"AT_RISK\"\nEDUCATION_UNFUNDED = \"UNFUNDED\"\nEDUCATION_NOT_RECORDED = \"NOT_RECORDED\"\n\nEVENT_LABELS_CN = {\n    EVENT_DEATH: \"顶梁柱身故\",\n    EVENT_DISABILITY: \"顶梁柱失能或重疾\",\n    EVENT_JOB_LOSS: \"顶梁柱长期失业（12 个月收入中断）\",\n}\n\nEVENT_NOTES_CN = {\n    EVENT_DEATH: \"收入一次性中断；寿险保额按记录计入可动用资源。\",\n    EVENT_DISABILITY: \"按记录保留该成员 40% 收入；失能、健康与重疾保额按记录计入。\",\n    EVENT_JOB_LOSS: \"长期失业按零替代收入建模；记录中的保障对失业不赔付，因此不计入任何赔付。\",\n}\n\nREASON_ABSTAIN_INCOME = \"BREADWINNER_INCOME_UNRECORDED\"\nREASON_ABSTAIN_BASELINE = \"BREADWINNER_EXPENSE_BASELINE_UNRECORDED\"\n\n\ndef _number(value, default=None):\n    if isinstance(value, bool) or value is None:\n        return default\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return default\n    if number != number or number in (float(\"inf\"), float(\"-inf\")):\n        return default\n    return number\n\n\ndef _money(value):\n    number = _number(value)\n    return None if number is None else round(number, 2)\n\n\ndef _members(profile):\n    return [m for m in (profile.get(\"members\") or []) if isinstance(m, dict)]\n\n\ndef _liquid_assets(profile):\n    total = 0.0\n    for asset in profile.get(\"assets\") or []:\n        if not isinstance(asset, dict):\n            continue\n        value = _number(asset.get(\"value\"), 0.0)\n        if value <= 0:\n            continue\n        if asset.get(\"kind\") == \"cash\" or asset.get(\"liquidity\") in (\"immediate\", \"near\"):\n            total += value\n    return total\n\n\ndef _coverage_by_kind(profile):\n    totals = {}\n    for policy in profile.get(\"protection\") or []:\n        if not isinstance(policy, dict):\n            continue\n        kind = policy.get(\"kind\")\n        if not kind:\n            continue\n        totals[kind] = totals.get(kind, 0.0) + max(0.0, _number(policy.get(\"coverage\"), 0.0))\n    return totals\n\n\ndef _event_payout(profile, event):\n    \"\"\"Only the protection kinds that this event would actually trigger pay out.\"\"\"\n    totals = _coverage_by_kind(profile)\n    return sum(totals.get(kind, 0.0) for kind in BREADWINNER_EVENT_PAYOUT_KINDS.get(event, ()))\n\n\ndef _mandatory_debt_service(profile):\n    total = 0.0\n    for liability in profile.get(\"liabilities\") or []:\n        if isinstance(liability, dict):\n            total += max(0.0, _number(liability.get(\"mandatory_payment\"), 0.0))\n    return total\n\n\ndef _outflow_is_education(outflow):\n    label = str(outflow.get(\"label\") or \"\")\n    kind = str(outflow.get(\"kind\") or \"\")\n    haystack = (label + \" \" + kind).lower()\n    return any(marker.lower() in haystack for marker in EDUCATION_MARKERS)\n\n\ndef _rigid_outflows(profile):\n    education = []\n    other = []\n    for outflow in profile.get(\"future_rigid_outflows\") or []:\n        if not isinstance(outflow, dict):\n            continue\n        amount = max(0.0, _number(outflow.get(\"amount\"), 0.0))\n        if amount <= MATERIALITY:\n            continue\n        years = _number(outflow.get(\"years_until_due\"), None)\n        # 单一来源分类（T-E0-045 / H-04）：与分层、年度目标共用同一个窗口函数，\n        # 不允许本模块自建年限阈值。\n        bucket = classify_rigid_outflow(outflow)\n        item = {\n            \"outflow_id\": outflow.get(\"outflow_id\"),\n            \"label\": outflow.get(\"label\") or outflow.get(\"outflow_id\") or \"未命名刚性支出\",\n            \"amount\": _money(amount),\n            \"years_until_due\": None if years is None else round(years, 2),\n            \"capital_bucket\": bucket,\n            \"near_term\": bucket == RIGID_WITHIN_WINDOW,\n        }\n        (education if _outflow_is_education(outflow) else other).append(item)\n    return education, other\n\n\ndef _abstain(profile, reason_code, reason_cn):\n    return {\n        \"status\": STATUS_ABSTAIN,\n        \"status_reason\": reason_cn,\n        \"reason_codes\": [reason_code],\n        \"currency\": profile.get(\"currency\"),\n        \"breadwinners\": [],\n        \"primary_breadwinner_id\": None,\n        \"gross_income\": None,\n        \"top_income_share\": None,\n        \"concentration\": \"UNKNOWN\",\n        \"concentration_flag\": False,\n        \"needs\": {},\n        \"education\": {\n            \"status\": EDUCATION_NOT_RECORDED,\n            \"need\": None,\n            \"items\": [],\n            \"funded_events\": [],\n            \"unfunded_events\": [],\n            \"finding_cn\": reason_cn,\n        },\n        \"protection_gap\": {\n            \"status\": STATUS_ABSTAIN,\n            \"need_total\": None,\n            \"liquid_assets\": None,\n            \"gap_before_insurance\": None,\n            \"gap_after_insurance\": None,\n            \"coverage_ratio\": None,\n            \"covered_months\": None,\n            \"target_months\": None,\n            \"gap_months\": None,\n            \"worst_event\": None,\n        },\n        \"scenarios\": [],\n        \"actions\": [],\n        \"insurance_reference\": {},\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": \"breadwinner and protection-gap analysis abstained without sufficient household evidence.\",\n            \"assumptions\": [],\n            \"sources\": [],\n            \"computed_at_utc\": None,\n        },\n    }\n\n\ndef identify_breadwinners(profile):\n    \"\"\"Rank members by recorded income and label who carries the household.\n\n    Returns ``(breadwinners, gross_income, top_share)`` where ``breadwinners`` is the\n    full ranking (every member, with ``is_breadwinner`` set), so the console can show\n    who contributes what instead of hiding the rest of the household.\n    \"\"\"\n    members = _members(profile)\n    incomes = []\n    for index, member in enumerate(members):\n        income = _number(member.get(\"annual_income\"))\n        incomes.append((index, member, max(0.0, income) if income is not None else None))\n\n    gross_income = sum(value for _, _, value in incomes if value is not None)\n    ranking = []\n    for index, member, value in incomes:\n        share = None\n        if value is not None and gross_income > MATERIALITY:\n            share = value / gross_income\n        ranking.append(\n            {\n                \"member_id\": member.get(\"member_id\") or f\"member_{index + 1}\",\n                \"role\": member.get(\"role\"),\n                \"age\": _number(member.get(\"age\")),\n                \"annual_income\": None if value is None else _money(value),\n                \"income_share\": None if share is None else round(share, 4),\n                \"is_breadwinner\": bool(share is not None and share >= BREADWINNER_SHARE_FLOOR),\n                \"income_stability\": member.get(\"income_stability\"),\n                \"dependents\": _number(member.get(\"dependents\")),\n            }\n        )\n    ranking.sort(key=lambda row: (row[\"annual_income\"] or 0.0), reverse=True)\n    top_share = ranking[0][\"income_share\"] if ranking else None\n    return ranking, gross_income, top_share\n\n\ndef analyse_breadwinner(profile, safety=None, insurance=None):\n    \"\"\"Identify the breadwinner, size the protection gap and simulate three events.\"\"\"\n    if not isinstance(profile, dict):\n        profile = {}\n\n    ranking, gross_income, top_share = identify_breadwinners(profile)\n    breadwinners = [row for row in ranking if row[\"is_breadwinner\"]]\n    if not breadwinners or gross_income <= MATERIALITY:\n        return _abstain(\n            profile,\n            REASON_ABSTAIN_INCOME,\n            \"没有记录到任何家庭成员的收入，无法识别顶梁柱，保护缺口按失败关闭处理（弃权）。\",\n        )\n\n    essential = max(0.0, _number(profile.get(\"annual_expenses_essential\"), 0.0))\n    if essential <= MATERIALITY:\n        return _abstain(\n            profile,\n            REASON_ABSTAIN_BASELINE,\n            \"没有记录家庭刚性生活支出基线，无法计算应急金目标与保护缺口，按失败关闭处理（弃权）。\",\n        )\n\n    target_days = _number(profile.get(\"survival_target_days\"), DEFAULT_SURVIVAL_TARGET_DAYS)\n    if target_days is None or target_days <= 0:\n        target_days = DEFAULT_SURVIVAL_TARGET_DAYS\n    target_months = target_days / DAYS_PER_MONTH\n\n    survival_floor_value = essential / 365.0 * target_days\n    if isinstance(safety, dict):\n        recorded_floor = _number(safety.get(\"survival_floor_value\"))\n        if recorded_floor is not None:\n            survival_floor_value = recorded_floor\n\n    rigid_split = rigid_outflow_split(profile)\n    education_items, other_items = _rigid_outflows(profile)\n    education_need = sum(item[\"amount\"] for item in education_items)\n    other_rigid_need = sum(item[\"amount\"] for item in other_items)\n    rigid_total = education_need + other_rigid_need\n    debt_service = _mandatory_debt_service(profile)\n    need_total = survival_floor_value + rigid_total + debt_service\n\n    monthly_essential = essential / 12.0\n    monthly_burn = monthly_essential + debt_service / 12.0\n    liquid_assets = _liquid_assets(profile)\n\n    primary = ranking[0]\n    concentration = \"SHARED\"\n    if top_share is None:\n        concentration = \"UNKNOWN\"\n    elif top_share >= BREADWINNER_CONCENTRATION_SHARE:\n        concentration = \"SINGLE_POINT_OF_FAILURE\"\n    elif len(breadwinners) > 1:\n        concentration = \"SHARED\"\n\n    concentration_flag = top_share is not None and top_share >= BREADWINNER_CONCENTRATION_SHARE\n\n    scenarios = []\n    for event in BREADWINNER_EVENTS:\n        retention = BREADWINNER_EVENT_RETENTION.get(event, 0.0)\n        # Every adverse event is applied to the members the household actually depends on:\n        # the household is the unit that has to survive, not an individual projection.\n        lost_income = sum(row[\"annual_income\"] or 0.0 for row in breadwinners)\n        retained_income = lost_income * retention\n        remaining_income = max(0.0, gross_income - lost_income + retained_income)\n\n        payout = _event_payout(profile, event)\n        resources_before = liquid_assets\n        resources_after = liquid_assets + payout\n        gap_before = max(0.0, need_total - resources_before)\n        gap_after = max(0.0, need_total - resources_after)\n        coverage_ratio = 1.0 if need_total <= MATERIALITY else min(1.0, resources_after / need_total)\n\n        ring_fenced = min(resources_after, education_need) if education_need > MATERIALITY else 0.0\n        survivable = max(0.0, resources_after - ring_fenced)\n        if monthly_burn > MATERIALITY:\n            covered_months = survivable / monthly_burn\n        else:\n            covered_months = None\n            survivable = 0.0\n\n        if covered_months is None:\n            survival_months = None\n        else:\n            residual_income = remaining_income / 12.0 - monthly_burn\n            if residual_income >= 0:\n                # The remaining income alone carries the household: the buffer is not consumed.\n                survival_months = None\n            else:\n                survival_months = covered_months\n\n        education_funded = resources_after + MATERIALITY >= education_need + survival_floor_value\n\n        if gap_after <= MATERIALITY:\n            status = SCENARIO_SURVIVES\n        elif coverage_ratio >= PROTECTION_GAP_PARTIAL_RATIO:\n            status = SCENARIO_STRESSED\n        else:\n            status = SCENARIO_COLLAPSES\n\n        if survival_months is None:\n            months_cn = \"剩余收入可覆盖刚性支出，不消耗缓冲\"\n        else:\n            months_cn = f\"可支撑约 {survival_months:,.1f} 个月（目标 {target_months:,.1f} 个月）\"\n\n        if status == SCENARIO_SURVIVES:\n            finding = f\"记录中的资源足以覆盖该情景：缺口为 0，{months_cn}。\"\n        elif status == SCENARIO_STRESSED:\n            finding = (\n                f\"该情景下仍有缺口 {gap_after:,.0f}，覆盖率 {coverage_ratio:.1%}；{months_cn}，\"\n                \"家庭会被压到生存底线附近。\"\n            )\n        else:\n            finding = (\n                f\"该情景会击穿生存底线：缺口 {gap_after:,.0f}，覆盖率仅 {coverage_ratio:.1%}；{months_cn}。\"\n            )\n        if education_need > MATERIALITY and not education_funded:\n            finding += \"子女教育资金在该情景下无法同时隔离，教育连续性不成立。\"\n\n        scenarios.append(\n            {\n                \"event\": event,\n                \"label_cn\": EVENT_LABELS_CN.get(event, event),\n                \"note_cn\": EVENT_NOTES_CN.get(event, \"\"),\n                \"income_retention_share\": round(retention, 4),\n                \"lost_income_annual\": _money(lost_income),\n                \"retained_income_annual\": _money(retained_income),\n                \"remaining_income_annual\": _money(remaining_income),\n                \"payout_recorded\": _money(payout),\n                \"resources_before_insurance\": _money(resources_before),\n                \"resources_after_insurance\": _money(resources_after),\n                \"need_total\": _money(need_total),\n                \"gap_before_insurance\": _money(gap_before),\n                \"gap_after_insurance\": _money(gap_after),\n                \"coverage_ratio\": round(coverage_ratio, 4),\n                \"ring_fenced_education\": _money(ring_fenced),\n                \"education_funded\": education_funded,\n                \"covered_months\": None if covered_months is None else round(covered_months, 2),\n                \"survival_months\": None if survival_months is None else round(survival_months, 2),\n                \"target_months\": round(target_months, 2),\n                \"status\": status,\n                \"finding_cn\": finding,\n            }\n        )\n\n    worst = max(scenarios, key=lambda row: row[\"gap_after_insurance\"])\n    gap_status = GAP_COVERED if worst[\"gap_after_insurance\"] <= MATERIALITY else (\n        GAP_PARTIAL if worst[\"coverage_ratio\"] >= PROTECTION_GAP_PARTIAL_RATIO else GAP_OPEN\n    )\n    primary_gap = next((row for row in scenarios if row[\"event\"] == EVENT_DEATH), worst)\n\n    funded_events = [row[\"event\"] for row in scenarios if row[\"education_funded\"]]\n    unfunded_events = [row[\"event\"] for row in scenarios if not row[\"education_funded\"]]\n    if education_need <= MATERIALITY:\n        education_status = EDUCATION_NOT_RECORDED\n        education_finding = (\n            \"家庭档案里没有记录子女教育等刚性未来支出，教育连续性无法被证明；\"\n            \"这不是「教育无忧」，而是「证据不足」。请补录教育金金额与到期年限。\"\n        )\n    elif not unfunded_events:\n        education_status = EDUCATION_PROTECTED\n        education_finding = (\n            f\"子女教育资金 {education_need:,.0f} 在三种意外情景下都能先于其他支出被隔离，教育连续性成立。\"\n        )\n    elif funded_events:\n        education_status = EDUCATION_AT_RISK\n        education_finding = (\n            f\"子女教育资金 {education_need:,.0f} 只在部分情景下能隔离（\"\n            + \"、\".join(EVENT_LABELS_CN.get(e, e) for e in funded_events)\n            + \"），其余情景会挤占教育资金。\"\n        )\n    else:\n        education_status = EDUCATION_UNFUNDED\n        education_finding = (\n            f\"子女教育资金 {education_need:,.0f} 在三种意外情景下都无法被隔离，教育连续性不成立。\"\n        )\n\n    actions = []\n    if primary_gap[\"gap_after_insurance\"] > MATERIALITY:\n        actions.append(\n            {\n                \"priority\": \"P0\",\n                \"action_cn\": (\n                    f\"把顶梁柱身故口径的保护缺口 {primary_gap['gap_after_insurance']:,.0f} 补上：\"\n                    \"优先用现金缓冲与记录中的保障额度补位，缺口未被证明补上之前不得增加任何风险敞口。\"\n                ),\n                \"rationale\": \"顶梁柱身故是唯一会让家庭收入瞬间归零、且无法靠劳动恢复的情景。\",\n                \"cost_estimate\": _money(primary_gap[\"gap_after_insurance\"]),\n            }\n        )\n    if education_status in (EDUCATION_AT_RISK, EDUCATION_UNFUNDED, EDUCATION_NOT_RECORDED):\n        actions.append(\n            {\n                \"priority\": \"P0\" if education_status == EDUCATION_UNFUNDED else \"P1\",\n                \"action_cn\": (\n                    \"先隔离子女教育资金\"\n                    + (f\" {education_need:,.0f}\" if education_need > MATERIALITY else \"\")\n                    + \"：在生存资金之外单独记账并锁定到期年限，不与长期增长资金混同。\"\n                ),\n                \"rationale\": \"教育连续性只有在教育资金被单独隔离后才成立，混同账户等于没有隔离。\",\n                \"cost_estimate\": _money(education_need) if education_need > MATERIALITY else None,\n            }\n        )\n    if concentration_flag:\n        actions.append(\n            {\n                \"priority\": \"P1\",\n                \"action_cn\": (\n                    f\"降低单一收入依赖：最高收入成员承担了 {top_share:.1%} 的家庭收入，\"\n                    \"应考虑提高第二收入来源的稳定性与可持续性。\"\n                ),\n                \"rationale\": \"单一收入点一旦中断，家庭损失的是全部收入，而不是一部分。\",\n                \"cost_estimate\": None,\n            }\n        )\n    if worst[\"event\"] == EVENT_JOB_LOSS and worst[\"gap_after_insurance\"] > MATERIALITY:\n        actions.append(\n            {\n                \"priority\": \"P1\",\n                \"action_cn\": (\n                    f\"为长期失业单独准备 {worst['gap_after_insurance']:,.0f} 的现金缓冲：\"\n                    \"记录中的保障对失业不赔付，这条路只能靠现金与可变现资产。\"\n                ),\n                \"rationale\": \"失业不是保险事故，任何把失业寄望于保险赔付的方案都是错的。\",\n                \"cost_estimate\": _money(worst[\"gap_after_insurance\"]),\n            }\n        )\n\n    status = STATUS_OK\n    status_reason = (\n        f\"已识别 {len(breadwinners)} 位顶梁柱，最坏情景为「{worst['label_cn']}」，\"\n        f\"缺口 {worst['gap_after_insurance']:,.0f}。\"\n    )\n\n    return {\n        \"status\": status,\n        \"status_reason\": status_reason,\n        \"reason_codes\": [],\n        \"currency\": profile.get(\"currency\"),\n        \"breadwinners\": ranking,\n        \"primary_breadwinner_id\": primary[\"member_id\"],\n        \"gross_income\": _money(gross_income),\n        \"top_income_share\": None if top_share is None else round(top_share, 4),\n        \"concentration\": concentration,\n        \"concentration_flag\": concentration_flag,\n        \"needs\": {\n            \"survival_floor_value\": _money(survival_floor_value),\n            \"rigid_within_window\": _money(rigid_split[\"within_window_total\"]),\n            \"rigid_beyond_window\": _money(rigid_split[\"beyond_window_total\"]),\n            \"rigid_capital_window_years\": rigid_split[\"window_years\"],\n            \"education_need\": _money(education_need),\n            \"other_rigid_need\": _money(other_rigid_need),\n            \"rigid_outflows_total\": _money(rigid_total),\n            \"debt_service_annual\": _money(debt_service),\n            \"need_total\": _money(need_total),\n            \"monthly_burn\": _money(monthly_burn),\n            \"target_days\": round(target_days, 2),\n            \"target_months\": round(target_months, 2),\n            \"liquid_assets\": _money(liquid_assets),\n        },\n        \"education\": {\n            \"status\": education_status,\n            \"need\": _money(education_need) if education_need > MATERIALITY else None,\n            \"items\": education_items,\n            \"other_rigid_items\": other_items,\n            \"funded_events\": funded_events,\n            \"unfunded_events\": unfunded_events,\n            \"finding_cn\": education_finding,\n        },\n        \"protection_gap\": {\n            \"status\": gap_status,\n            \"need_total\": _money(need_total),\n            \"liquid_assets\": _money(liquid_assets),\n            \"gap_before_insurance\": _money(primary_gap[\"gap_before_insurance\"]),\n            \"gap_after_insurance\": _money(primary_gap[\"gap_after_insurance\"]),\n            \"coverage_ratio\": primary_gap[\"coverage_ratio\"],\n            \"covered_months\": primary_gap[\"covered_months\"],\n            \"target_months\": round(target_months, 2),\n            \"gap_months\": None\n            if primary_gap[\"covered_months\"] is None\n            else round(max(0.0, target_months - primary_gap[\"covered_months\"]), 2),\n            \"worst_event\": worst[\"event\"],\n            \"worst_event_label_cn\": worst[\"label_cn\"],\n            \"worst_gap_after_insurance\": worst[\"gap_after_insurance\"],\n            \"critical_months\": PROTECTION_GAP_CRITICAL_MONTHS,\n            \"formula_cn\": (\n                \"保护缺口 = 家庭应急金目标 + 已记录刚性未来支出 + 12 个月强制还款 − 可动用流动资产 − 该情景可确认赔付\"\n            ),\n        },\n        \"scenarios\": scenarios,\n        \"actions\": actions,\n        \"insurance_reference\": {\n            \"plan_module\": \"insurance\",\n            \"status\": (insurance or {}).get(\"status\") if isinstance(insurance, dict) else None,\n            \"coverage_score\": (insurance or {}).get(\"coverage_score\") if isinstance(insurance, dict) else None,\n            \"note_cn\": (\n                \"保险是六域解决方案中的一个模块：本节只使用记录中的保额做缺口计算，\"\n                \"不推荐任何保险公司、产品或机构，也不承诺任何赔付。\"\n            ),\n        },\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": (\n                \"breadwinner = member carrying at least \"\n                f\"{BREADWINNER_SHARE_FLOOR:.0%} of recorded gross income; protection gap = \"\n                \"survival floor + recorded rigid future outflows + one year of mandatory debt \"\n                \"service, measured before and after the payout that each event actually triggers.\"\n            ),\n            \"assumptions\": [\n                f\"A member carrying {BREADWINNER_SHARE_FLOOR:.0%} or more of gross income is a breadwinner.\",\n                f\"One member carrying {BREADWINNER_CONCENTRATION_SHARE:.0%} or more is a single point of failure.\",\n                \"Rigid future outflows are counted at face value; E0 applies no discounting.\",\n                \"Retention after disability is 40% of the affected member's recorded income.\",\n                \"Long-term job loss is modelled with no replacement wage and no insurance payout.\",\n                \"Education money is ring-fenced before any other spending, so education continuity is computed.\",\n            ],\n            \"sources\": [\n                \"engine.safety:liquid_asset_definition\",\n                \"engine.layering:rigid_outflow_split\",\n                \"engine.layering:classify_rigid_outflow\",\n                \"engine.insurance:CAPABILITY_POLICY_KINDS\",\n            ],\n            \"computed_at_utc\": None,\n        },\n    }\n", "constants.py": "\"\"\"Frozen constants for Verity Family Wealth Engine E0.\n\nNothing in this module may be made configurable at runtime in E0: the safety\nposture is compiled in and asserted by CI.\n\"\"\"\n\n# --- safety posture (must never be relaxed without Founder approval) ---\nPRODUCTION_AUTHORITY = \"OFF\"\nRELEASE_GATE = \"DENY\"\n\n# --- versioning ---\nALGORITHM_VERSION = \"e0.4.0\"\n\n# --- evidence vocabulary ---\nEVIDENCE_STATUS_VERIFIED = \"VERIFIED\"\nEVIDENCE_STATUS_NOT_VERIFIED = \"NOT_VERIFIED\"\n\n# --- feasibility thresholds (contract §3) ---\nREFUSE_MAX_LOSS_FLOOR = 0.15          # max_tolerable_loss_pct below this -> REFUSE\nREFUSE_MIN_SURVIVAL_DAYS = 90         # safety_days below this -> REFUSE\nHIGH_TARGET_RETURN = 0.12             # target above this is \"ambitious\"\nHIGH_TARGET_MAX_LOSS_REQUIRED = 0.25  # ambitious target needs at least this loss budget\nREVIEW_SURVIVAL_DAYS = 180            # safety_days below this -> REVIEW\nREVIEW_DEBT_PRESSURE = 0.35           # debt pressure above this -> REVIEW\n\n# --- household defaults ---\nDEFAULT_SURVIVAL_TARGET_DAYS = 180\n\n# --- benchmark (fixed, documented, not optimised) ---\nBENCHMARK_60_40_RETURN = 0.051\n\n# --- layering policy ---\nLAYER_LONG_TERM_SHARE = 0.80          # of residual assets after survival/duty/protection\nLAYER_HIGH_RISK_SHARE = 0.20\nLAYER_NEAR_TERM_DUTY_YEARS = 5        # rigid outflows due within this window are \"near term\"\nUNDERINVESTED_GROWTH_FRACTION = 0.20  # growth below this fraction is \"under-invested\"\nREBALANCE_DRIFT_THRESHOLD = 0.05      # 5 percentage points\n\n# --- simulation model (documented scenarios, not forecasts) ---\nSIMULATION_ITERATIONS = 2000\nDEFAULT_SEED = 20260914\nOPTION_PROTECTION_COST_RATE = 0.025\n\n# --- asset class assumptions: (expected annual return, annual volatility, crash drawdown) ---\nASSET_CLASS_MODEL = {\n    \"cash\": (0.020, 0.005, 0.000),\n    \"bond\": (0.032, 0.055, -0.150),\n    \"global_index\": (0.062, 0.160, -0.450),\n    \"equity\": (0.070, 0.220, -0.600),\n    \"gold\": (0.035, 0.150, -0.200),\n    \"option_protection\": (-0.025, 0.090, 0.350),\n}\n\nASSET_CLASSES = (\"cash\", \"bond\", \"global_index\", \"equity\", \"gold\", \"option_protection\")\n\n# --- untouchable / liquidity vocabulary ---\nLIQUIDITY_IMMEDIATE = \"immediate\"\nLIQUIDITY_NEAR = \"near\"\nLIQUIDITY_CANNOT_TOUCH = \"cannot_touch\"\nLIQUID_LIQUIDITIES = (LIQUIDITY_IMMEDIATE, LIQUIDITY_NEAR)\n\n# --- income interruption model ---\n# A three-month total income stop is assumed, of which half is absorbed by partner\n# earnings, severance or benefits. Only the retained-net share consumes the buffer.\nINCOME_LOSS_MONTHS = 3.0\nINCOME_RETENTION_SHARE = 0.5\nDAYS_PER_MONTH = 30.44\n\n# --- inflation spiral scenario (T-E0-033) ---\n# Inflation does not stop one line item: essential costs escalate while a rate hike\n# reprices recorded debt. Both are extra *outflows* the buffer must absorb, and both\n# are documented constants rather than fitted parameters.\nINFLATION_SPIRAL_ESSENTIAL_ESCALATION = 0.15  # extra essential cost over the 12-month horizon\nINFLATION_SPIRAL_RATE_HIKE = 0.015            # +150bp applied to recorded debt balances\n\n# --- income concentration scenario (T-E0-033) ---\n# The household's largest income stream stops for a full year while the remaining\n# streams keep paying. A concentrated household loses more of its capacity at once.\nINCOME_CONCENTRATION_MONTHS = 12.0\n\n# --- default medical shock assumption ---\nMEDICAL_SHOCK_MULTIPLE_OF_ESSENTIAL = 1.5\nMEDICAL_SHOCK_MINIMUM = 50000.0\n\n# --- integrated protection plan ---\nPLAN_ACTION_LIMIT = 8\nUNTOUCHABLE_CONCENTRATION_LIMIT = 0.60  # share of total assets that cannot be reached in a crisis\n\n# --- breadwinner identification & protection gap (T-E0-043) ---\n# Income share above which a member carries the household: 40% of gross income is\n# enough that losing this one income stream changes what the family can survive.\nBREADWINNER_SHARE_FLOOR = 0.40\n# One member above this share means a single point of failure, not a shared load.\nBREADWINNER_CONCENTRATION_SHARE = 0.60\n# Markers that classify a recorded future rigid outflow as an education commitment.\nEDUCATION_MARKERS = (\"教育\", \"学费\", \"留学\", \"education\", \"tuition\")\n# Two clearly-labelled gaps: \"before insurance\" spends only what the family already\n# holds, \"after insurance\" also spends the payout that this event would actually trigger.\nPROTECTION_GAP_COVERED_RATIO = 0.95\nPROTECTION_GAP_PARTIAL_RATIO = 0.50\nPROTECTION_GAP_CRITICAL_MONTHS = 6.0\n\n#: Breadwinner adverse events. Retention is the share of the *lost member's* income that\n#: keeps arriving after the event; it is a documented assumption, not a fitted parameter.\nEVENT_DEATH = \"breadwinner_death\"\nEVENT_DISABILITY = \"breadwinner_disability\"\nEVENT_JOB_LOSS = \"breadwinner_long_term_job_loss\"\nBREADWINNER_EVENTS = (EVENT_DEATH, EVENT_DISABILITY, EVENT_JOB_LOSS)\nBREADWINNER_EVENT_RETENTION = {\n    EVENT_DEATH: 0.0,        # the income stream stops outright\n    EVENT_DISABILITY: 0.40,  # rehabilitation / reduced capacity keeps part of it\n    EVENT_JOB_LOSS: 0.0,     # a long-term loss is modelled with no replacement wage\n}\n#: Which recorded protection kinds actually pay out in each event. Job loss pays nothing:\n#: no insurance in the recorded model responds to unemployment, and Verity will not pretend.\nBREADWINNER_EVENT_PAYOUT_KINDS = {\n    EVENT_DEATH: (\"life\",),\n    EVENT_DISABILITY: (\"disability\", \"health\", \"critical_illness\"),\n    EVENT_JOB_LOSS: (),\n}\nBREADWINNER_SHORTFALL_EVENT_MONTHS = 12.0\n\n# --- annual goal progress & take-profit state machine (T-E0-044) ---\n# The long-term money is only *what is left* after the survival floor and the\n# children's education money have been ring-fenced, so the annual target is applied\n# to that residual and not to the household's gross assets.\n#: Progress ratios the console shows as a scale, and the ratio at which partial\n#: profit-taking starts: three quarters of the year's target is enough that a\n#: further drawdown would eat a result that is already in hand.\nANNUAL_GOAL_MILESTONES = (0.25, 0.50, 0.75, 1.00)\nANNUAL_GOAL_LOCK_PROFIT_RATIO = 0.75\n#: At or above this ratio the year's goal is met: new risk stops being additive.\nANNUAL_GOAL_ACHIEVED_RATIO = 1.00\n#: After locking profit, this much of the recorded loss budget may still be exposed.\nANNUAL_GOAL_DRAWDOWN_ALERT_RATIO = 0.50\n#: The survival floor gates the take-profit question at the same level that the\n#: frozen feasibility contract uses to refuse a plan outright (90 days).\nANNUAL_GOAL_MIN_SURVIVAL_DAYS = REFUSE_MIN_SURVIVAL_DAYS\n\n# --- extreme leverage guard ---\nMAX_LEVERAGE_MULTIPLE = 10.0\nMATERIALITY = 1e-9\n\n# --- plausibility guard (T-E0-008 F-04) ---\n# E0 is a household wealth product. An amount at or above one trillion major\n# currency units, a horizon beyond 200 years, or a recorded age beyond 130 is not\n# a household fact: it is an input that would let an adversarial profile buy a\n# confident PASS with numbers the engine can neither explain nor stand behind.\n# Such inputs are treated as contradictory evidence, exactly like a missing one.\nMAX_PLAUSIBLE_AMOUNT = 1e12\nMAX_PLAUSIBLE_HORIZON_YEARS = 200\nMAX_PLAUSIBLE_SURVIVAL_DAYS = 3650\nMIN_PLAUSIBLE_AGE = 0\nMAX_PLAUSIBLE_AGE = 130\n\n# --- single-source rulers (T-E0-045: H-04 / H-05) ---\n# 全引擎只允许引用这里的定义，禁止在模块内自建阈值：\n#   * RIGID_CAPITAL_WINDOW_YEARS —— 刚性资金窗口。到期年限在窗口内的刚性支出\n#     必须立刻隔离（layering.near_term_duty 口径），不进长期资金基数；\n#     窗口外的刚性支出是长期刚性责任：由长期资金承担，但必须在到期月份进入\n#     月度投影，并按同一分类在保障缺口与年度目标里如实标注。\n#   * SURVIVAL_BREACH_DAYS —— 击穿判定。可动用现金能覆盖的生存天数低于这个\n#     生存底线即视为「击穿」，与 feasibility 的 REFUSE 门槛同一条线。\nRIGID_CAPITAL_WINDOW_YEARS = LAYER_NEAR_TERM_DUTY_YEARS\nSURVIVAL_BREACH_DAYS = REFUSE_MIN_SURVIVAL_DAYS\n", "engine.py": "\"\"\"Verity Family Wealth Engine E0 — pipeline entry point.\n\nPipeline:\n    validate -> layer -> safety -> feasibility -> allocation -> stress -> today\n    -> evidence -> audit record\n\nGuarantees:\n  * never raises on bad input; instead refuses via ABSTAIN (fail-closed)\n  * fully deterministic for a given profile and run_id\n  * every output carries evidence and an append-only audit record\n\"\"\"\n\nfrom __future__ import annotations\n\nimport uuid\n\nfrom engine.allocation import simulate_allocation\nfrom engine.annual_goal import FORMULA_CN, analyse_annual_goal\nfrom engine.constants import ALGORITHM_VERSION\nfrom engine.evidence import build_audit_record, digest, make_evidence\nfrom engine.feasibility import assess_feasibility\nfrom engine.household import validate_profile\nfrom engine.insurance import audit_insurance\nfrom engine.jsonstrict import NON_FINITE_REASON_CODE, sanitize_non_finite\nfrom engine.layering import layer_funds\nfrom engine.breadwinner import analyse_breadwinner\nfrom engine.protection import build_protection_plan\nfrom engine.risk_ranking import build_risk_ranking\nfrom engine.safety import compute_safety\nfrom engine.stress import SCENARIO_SET_VERSION, run_stress_tests\nfrom engine.today import build_today\nfrom engine.timeline import compute_stress_timeline\nfrom engine.trend import compute_monthly_trend\n\nDEFAULT_SOURCES = [\n    \"synthetic_household_profile\",\n    \"engine_spec:docs/INTERFACE_FREEZE_V0_1.md\",\n    \"algorithm:verity-family-wealth-engine-e0\",\n]\n\nASSUMPTIONS = [\n    \"Synthetic data only; no real client records are processed in E0.\",\n    \"Rates are decimal fractions and money is in major currency units.\",\n    \"Costs, taxes and transaction frictions are simplified placeholders in E0.\",\n    \"Simulated returns are scenarios, not forecasts, and are not real performance.\",\n    \"No specific security, fund, insurer or product is recommended by the engine.\",\n    \"Amounts are read in the household's reporting currency; a per-item currency marks \"\n    \"foreign-currency exposure and is never converted.\",\n]\n\n_EMPTY_LAYERS = {\n    \"survival\": 0.0,\n    \"near_term_duty\": 0.0,\n    \"protection\": 0.0,\n    \"long_term_growth\": 0.0,\n    \"high_risk_opportunity\": 0.0,\n}\n\n\ndef _new_run_id() -> str:\n    return \"run_\" + uuid.uuid4().hex[:16]\n\n\ndef _refusal_payload(run_id, reason_codes, reasons, profile):\n    \"\"\"Fail-closed result used whenever the pipeline cannot produce a real answer.\"\"\"\n    layers = dict(_EMPTY_LAYERS)\n    # T-E0-045 / M-03：拒绝路径没有算出任何读数，就必须如实写「未计算」，\n    # 不能再用编造的 0.0 冒充测量值（读者会把 0 天当成真实生存天数）。\n    safety = {\n        \"safety_days\": None,\n        \"cash_gap\": None,\n        \"debt_pressure_ratio\": None,\n        \"untouchable_assets\": None,\n        \"survival_floor_value\": None,\n        \"major_risks\": [],\n        \"availability\": \"NOT_AVAILABLE\",\n        \"evidence\": {},\n    }\n    feasibility = {\n        \"verdict\": \"ABSTAIN\",\n        \"verdict_meaning\": (\n            \"Evidence is insufficient or incoherent; Verity refuses to judge.\"\n        ),\n        \"reason_codes\": list(reason_codes),\n        \"reasons\": list(reasons),\n        \"required_return_for_goal\": None,\n        \"max_tolerable_loss_pct\": None,\n        \"achievable_return_proxy\": None,\n        \"evidence\": {},\n    }\n    allocation = {\n        \"allocation\": {},\n        \"allocation_weights\": {},\n        \"executed\": False,\n        \"simulated_annual_return\": None,\n        \"simulated_volatility\": None,\n        \"simulated_max_drawdown\": None,\n        \"protection_cost\": None,\n        \"insurance_need\": {},\n        \"iterations\": 0,\n        \"seed\": None,\n        \"evidence\": {},\n    }\n    insurance = {\n        \"status\": \"ABSTAIN\",\n        \"status_reason\": \"Engine refused to judge; insurance audit follows the same gate.\",\n        \"capabilities\": {},\n        \"capability_order\": [\"life\", \"disability\", \"health\", \"liability\"],\n        \"coverage_score\": None,\n        \"premium_total\": None,\n        \"premium_to_income\": None,\n        \"premium_burden_status\": None,\n        \"warnings\": [],\n        \"disclaimer\": (\n            \"Verity recommends no insurer, no policy and no product. Any actual placement \"\n            \"requires a licensed partner and remains outside E0.\"\n        ),\n        \"evidence\": {},\n    }\n    stress = {\n        \"scenarios\": [],\n        \"scenario_count\": 0,\n        \"scenario_set_version\": SCENARIO_SET_VERSION,\n        \"worst_scenario_id\": None,\n        \"survival_breach\": False,\n        \"evidence\": {},\n    }\n    protection = {\n        \"status\": \"ABSTAIN\",\n        \"status_reason\": \"Engine refused to judge; the protection plan follows the same gate.\",\n        \"domains\": {},\n        \"domain_order\": [\"cash\", \"insurance\", \"assets\", \"debt\", \"legal\", \"social\"],\n        \"priority_actions\": [],\n        \"notice\": (\n            \"Integrated protection plan abstained because the engine refused to judge; \"\n            \"evidence is insufficient and Verity never assumes what the family has not recorded.\"\n        ),\n        \"evidence\": {},\n    }\n    breadwinner = {\n        \"status\": \"ABSTAIN\",\n        \"status_reason\": \"Engine refused to judge; breadwinner analysis follows the same gate.\",\n        \"reason_codes\": list(reason_codes),\n        \"breadwinners\": [],\n        \"primary_breadwinner_id\": None,\n        \"gross_income\": None,\n        \"top_income_share\": None,\n        \"concentration\": \"UNKNOWN\",\n        \"concentration_flag\": False,\n        \"needs\": {},\n        \"education\": {\n            \"status\": \"NOT_RECORDED\",\n            \"need\": None,\n            \"items\": [],\n            \"funded_events\": [],\n            \"unfunded_events\": [],\n            \"finding_cn\": \"引擎已弃权，教育连续性不做判断。\",\n        },\n        \"protection_gap\": {\"status\": \"ABSTAIN\"},\n        \"scenarios\": [],\n        \"actions\": [],\n        \"insurance_reference\": {},\n        \"evidence\": {},\n    }\n    annual_goal = {\n        \"status\": \"ABSTAIN\",\n        \"status_reason\": \"Engine refused to judge; the annual goal follows the same gate.\",\n        \"reason_codes\": list(reason_codes),\n        \"state\": \"EVIDENCE_INSUFFICIENT\",\n        \"state_label_cn\": \"证据不足（弃权）\",\n        \"state_finding_cn\": \"引擎已弃权，年度目标与止盈状态不做判断。\",\n        \"formula_cn\": (\n            FORMULA_CN  # 单一来源：拒绝路径引用同一个口径句，避免文案再次分叉\n        ),\n        \"basis\": {},\n        \"milestones\": [],\n        \"progress\": {\"recorded\": False, \"status\": \"NOT_RECORDED\"},\n        \"guardrails\": {},\n        \"lock_profit_condition_cn\": None,\n        \"stop_risk_condition_cn\": None,\n        \"actions\": [],\n        \"evidence\": {},\n    }\n    trend = {\n        \"status\": \"ABSTAIN\",\n        \"status_reason\": \"Engine refused to judge; the monthly trend follows the same gate.\",\n        \"reason_codes\": list(reason_codes),\n        \"horizon_months\": 0,\n        \"return_assumption\": \"none\",\n        \"assumptions\": [],\n        \"monthly\": [],\n        \"summary\": {},\n        \"evidence\": {},\n    }\n    timeline = {\n        \"status\": \"ABSTAIN\",\n        \"status_reason\": \"Engine refused to judge; the danger timeline follows the same gate.\",\n        \"reason_codes\": list(reason_codes),\n        \"horizon_months\": 0,\n        \"return_assumption\": \"none\",\n        \"scenario_set_version\": SCENARIO_SET_VERSION,\n        \"rows\": [],\n        \"summary\": {},\n        \"evidence\": {},\n    }\n    risk_ranking = {\n        \"status\": \"ABSTAIN\",\n        \"status_reason\": \"Engine refused to judge; the risk ranking follows the same gate.\",\n        \"overall_risk_level\": \"ABSTAIN\",\n        \"risk_count\": 0,\n        \"active_count\": 0,\n        \"top_risk_id\": None,\n        \"ranked_risks\": [],\n        \"ranking_method\": \"Risk ranking abstained without sufficient household evidence.\",\n        \"notice\": (\n            \"Risk ranking refused to judge: evidence is insufficient \"\n            \"and Verity never assumes what the family has not recorded.\"\n        ),\n        \"evidence\": {},\n    }\n    today = {\n        \"wealth_value\": None,\n        \"wealth_change_pct\": None,\n        \"safety_days\": None,\n        \"goal_probability\": None,\n        \"benchmark_60_40_return\": None,\n        \"relative_to_benchmark\": None,\n        \"drift\": None,\n        \"growth_fraction\": None,\n        \"action\": \"ABSTAIN\",\n        \"action_meaning\": \"No action is issued because Verity cannot stand behind a recommendation.\",\n        \"action_reason\": \"Engine refused to judge: \" + \"; \".join(reason_codes),\n        \"action_is_final\": False,\n        \"evidence\": {},\n    }\n    payload = {\n        \"profile_id\": profile.get(\"profile_id\") if isinstance(profile, dict) else None,\n        \"run_id\": run_id,\n        \"algorithm_version\": ALGORITHM_VERSION,\n        \"verdict\": \"ABSTAIN\",\n        \"layers\": layers,\n        \"safety\": safety,\n        \"feasibility\": feasibility,\n        \"allocation\": allocation,\n        \"stress\": stress,\n        \"today\": today,\n        \"insurance\": insurance,\n        \"protection\": protection,\n        \"breadwinner\": breadwinner,\n        \"annual_goal\": annual_goal,\n        \"risk_ranking\": risk_ranking,\n        \"trend\": trend,\n        \"timeline\": timeline,\n    }\n    # 单一来源：拒绝载荷的每一个区块都显式标记「未计算 / 未验证」，并让 _finalise\n    # 不再把它升级成 VERIFIED（M-03）。\n    for section in (\n        \"layers\", \"safety\", \"feasibility\", \"allocation\", \"stress\", \"today\", \"insurance\",\n        \"protection\", \"breadwinner\", \"annual_goal\", \"risk_ranking\", \"trend\", \"timeline\",\n    ):\n        block = payload.get(section)\n        if isinstance(block, dict):\n            block[\"evidence\"] = {\n                \"refusal\": True,\n                \"availability\": \"NOT_AVAILABLE\",\n                \"evidence_status\": \"NOT_VERIFIED\",\n                \"limits\": [\n                    \"Refusal payload: this section holds no computed value for this run; \"\n                    \"null means not computed, never zero.\",\n                ],\n            }\n            block.setdefault(\"availability\", \"NOT_AVAILABLE\")\n    payload[\"today\"][\"availability\"] = \"NOT_AVAILABLE\"\n    return payload\n\n\ndef run_engine(profile, *, run_id=None):\n    \"\"\"Run the full E0 pipeline for one household profile.\"\"\"\n    run_id = run_id or _new_run_id()\n    if not isinstance(profile, dict):\n        profile = {}\n\n    try:\n        validation = validate_profile(profile)\n    except Exception as exc:  # noqa: BLE001 - fail closed, never propagate\n        result = _refusal_payload(\n            run_id,\n            [\"PROFILE_VALIDATION_ERROR\"],\n            [f\"Profile validation raised: {type(exc).__name__}: {exc}\"],\n            profile,\n        )\n        return _finalise(result, profile, run_id)\n\n    if validation.get(\"missing_required\"):\n        result = _refusal_payload(\n            run_id,\n            [\"MISSING_REQUIRED_INPUT\"],\n            [\"Required inputs absent: \" + \", \".join(validation[\"missing_required\"])],\n            profile,\n        )\n        return _finalise(result, profile, run_id)\n\n    if validation.get(\"data_issues\"):\n        # T-E0-008 H-02（独立对抗性审查发现）：只让「结论」弃权是不够的。\n        # 一份自相矛盾的档案过去仍然会算出分层、压力情景、风险排序与年度目标，\n        # 并把它们当成可读的结果发出去 —— 用户看到的是「弃权」标题下的一堆确定数字。\n        # 输入不可信（类型错误 / 非有限数 / 可信度越界 / 币种含混）时唯一诚实的输出是整份结果弃权。\n        # 注意区分「输入不可信」与「财务状态极端」（例如杠杆超过 10 倍）：后者是真实但艰难的\n        # 家庭处境，引擎照常给出数字、只在判定层弃权 —— 否则最需要答案的家庭反而什么都拿不到。\n        result = _refusal_payload(\n            run_id,\n            [\"INCONSISTENT_INPUT\"],\n            [\"The profile is internally contradictory: \" + \"; \".join(validation[\"data_issues\"])],\n            profile,\n        )\n        return _finalise(result, profile, run_id)\n\n    try:\n        layers = layer_funds(profile)\n        safety = compute_safety(profile)\n        feasibility = assess_feasibility(profile, safety, layers)\n        allocation = simulate_allocation(profile, layers, feasibility)\n        stress = run_stress_tests(profile, allocation, safety)\n        today = build_today(profile, safety, feasibility, allocation, stress)\n        insurance = audit_insurance(profile, safety, allocation)\n        protection = build_protection_plan(\n            profile,\n            safety=safety,\n            insurance=insurance,\n            layers=layers,\n            allocation=allocation,\n        )\n        trend = compute_monthly_trend(profile)\n        timeline = compute_stress_timeline(profile, safety, allocation)\n        breadwinner = analyse_breadwinner(profile, safety=safety, insurance=insurance)\n        annual_goal = analyse_annual_goal(\n            profile,\n            layers=layers,\n            safety=safety,\n            allocation=allocation,\n            breadwinner=breadwinner,\n        )\n        risk_ranking = build_risk_ranking(\n            profile,\n            safety=safety,\n            stress=stress,\n            insurance=insurance,\n            protection=protection,\n            layers=layers,\n            allocation=allocation,\n        )\n    except Exception as exc:  # noqa: BLE001 - a crash is an ABSTAIN, not an error\n        result = _refusal_payload(\n            run_id,\n            [\"ENGINE_INTERNAL_ERROR\"],\n            [f\"Pipeline halted safely: {type(exc).__name__}: {exc}\"],\n            profile,\n        )\n        return _finalise(result, profile, run_id)\n\n    result = {\n        \"profile_id\": profile.get(\"profile_id\"),\n        \"run_id\": run_id,\n        \"algorithm_version\": ALGORITHM_VERSION,\n        \"verdict\": feasibility.get(\"verdict\", \"ABSTAIN\"),\n        \"layers\": layers,\n        \"safety\": safety,\n        \"feasibility\": feasibility,\n        \"allocation\": allocation,\n        \"stress\": stress,\n        \"today\": today,\n        \"insurance\": insurance,\n        \"protection\": protection,\n        \"breadwinner\": breadwinner,\n        \"annual_goal\": annual_goal,\n        \"risk_ranking\": risk_ranking,\n        \"trend\": trend,\n        \"timeline\": timeline,\n    }\n    return _finalise(result, profile, run_id)\n\n\ndef _fail_closed_on_non_finite(result, paths):\n    \"\"\"Turn \"a number overflowed\" into an honest ABSTAIN (T-E0-008 F-01).\n\n    Non-finite values cannot be carried across the JSON boundary (browsers reject\n    ``Infinity`` / ``NaN``), so they are suppressed before serialisation and the\n    whole run fails closed: Verity will not label a household PASS on the strength\n    of a number it had to blank out.\n    \"\"\"\n    detail = (\n        \"Non-finite value suppressed at \"\n        + \", \".join(sorted(paths)[:10])\n        + (\" (+%d more)\" % (len(paths) - 10) if len(paths) > 10 else \"\")\n    )\n    result[\"verdict\"] = \"ABSTAIN\"\n    feasibility = result.get(\"feasibility\")\n    if isinstance(feasibility, dict):\n        codes = feasibility.setdefault(\"reason_codes\", [])\n        if NON_FINITE_REASON_CODE not in codes:\n            codes.append(NON_FINITE_REASON_CODE)\n        reasons = feasibility.setdefault(\"reasons\", [])\n        reasons.append(detail)\n        feasibility[\"verdict\"] = \"ABSTAIN\"\n        feasibility[\"verdict_meaning\"] = (\n            \"Evidence is insufficient or incoherent; Verity refuses to judge.\"\n        )\n    result[\"non_finite_suppressed\"] = {\n        \"count\": len(paths),\n        \"paths\": sorted(paths)[:50],\n        \"reason_code\": NON_FINITE_REASON_CODE,\n        \"note\": (\n            \"Engine input produced values too large to represent; they were replaced by null \"\n            \"and the run abstained instead of publishing a number it cannot stand behind.\"\n        ),\n    }\n\n\ndef _finalise(result, profile, run_id):\n    \"\"\"Attach top-level evidence + audit record and stamp child evidence blocks.\"\"\"\n    result, non_finite_paths = sanitize_non_finite(result)\n    if non_finite_paths:\n        _fail_closed_on_non_finite(result, non_finite_paths)\n    inputs_digest = digest(profile)\n    sources = list(DEFAULT_SOURCES)\n    if result.get(\"verdict\") != \"ABSTAIN\":\n        sources.append(\"synthetic_cohort:data/synthetic/households.json\")\n\n    computed_at = None\n    for section in (\"layers\", \"safety\", \"feasibility\", \"allocation\", \"stress\", \"today\", \"insurance\", \"protection\", \"breadwinner\", \"annual_goal\", \"risk_ranking\", \"trend\", \"timeline\"):\n        block = result.get(section)\n        if isinstance(block, dict) and isinstance(block.get(\"evidence\"), dict):\n            child = block[\"evidence\"]\n            if computed_at is not None:\n                child[\"computed_at_utc\"] = computed_at\n            refusal = child.get(\"refusal\") is True\n            child[\"evidence_status\"] = (\n                \"NOT_VERIFIED\"\n                if refusal\n                else (\"VERIFIED\" if (sources and run_id) else \"NOT_VERIFIED\")\n            )\n            if refusal:\n                child[\"availability\"] = \"NOT_AVAILABLE\"\n                limits = child.setdefault(\"limits\", [])\n                note = (\n                    \"Refusal payload: the values in this section are placeholders (null), \"\n                    \"not measurements; this run abstained.\"\n                )\n                if note not in limits:\n                    limits.append(note)\n            child[\"run_id\"] = run_id\n            child[\"algorithm_version\"] = ALGORITHM_VERSION\n            if child.get(\"sources\"):\n                child[\"sources\"] = list(child[\"sources\"]) + [\n                    s for s in DEFAULT_SOURCES if s not in child[\"sources\"]\n                ]\n            else:\n                child[\"sources\"] = list(sources)\n            if not child.get(\"assumptions\"):\n                child[\"assumptions\"] = list(ASSUMPTIONS)\n\n    evidence = make_evidence(\n        {k: v for k, v in result.items() if k not in (\"evidence\", \"audit\")},\n        sources=sources,\n        run_id=run_id,\n        assumptions=ASSUMPTIONS,\n        inputs_digest=inputs_digest,\n    )\n\n    if computed_at is None:\n        computed_at = evidence[\"computed_at_utc\"]\n    for section in (\"layers\", \"safety\", \"feasibility\", \"allocation\", \"stress\", \"today\", \"insurance\", \"protection\", \"risk_ranking\", \"trend\", \"timeline\", \"annual_goal\"):\n        block = result.get(section)\n        if isinstance(block, dict) and isinstance(block.get(\"evidence\"), dict):\n            block[\"evidence\"][\"computed_at_utc\"] = computed_at\n            block[\"evidence\"][\"record_hash\"] = digest(block[\"evidence\"])\n\n    risk_notice = (\n        \"Decision support only. Not investment, legal, tax or insurance advice. \"\n        \"No production authority; release gate is DENY.\"\n    )\n    audit = build_audit_record(\n        {k: v for k, v in result.items() if k != \"audit\"},\n        run_id=run_id,\n        sequence=0,\n    )\n\n    result[\"evidence\"] = evidence\n    result[\"audit\"] = audit\n    result[\"risk_notice\"] = risk_notice\n    return result\n", "envelope.py": "\"\"\"TaskEnvelope / ResultEnvelope contracts.\n\nThese two envelopes are the unit of work in the Verity engineering loop:\n\n    goal -> TaskEnvelope -> work -> ResultEnvelope -> PASS ? next task : repair\n\nA ResultEnvelope may only claim PASS when it carries artifacts, a test summary and\nevidence. Otherwise it is forced to NOT_VERIFIED. Release stays DENY regardless.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    PRODUCTION_AUTHORITY,\n    RELEASE_GATE,\n)\nfrom engine.evidence import digest, make_evidence\n\nTASK_STATUSES = (\"PASS\", \"FAIL\", \"BLOCKED\", \"NOT_VERIFIED\")\n\n_REQUIRED_TASK_FIELDS = (\n    \"task_id\",\n    \"title\",\n    \"objective\",\n    \"acceptance_criteria\",\n    \"safety_class\",\n    \"owner_role\",\n)\n\n_SAFETY_CLASSES = (\n    \"SAFE_INTERNAL\",\n    \"RESTRICTED_RESEARCH\",\n    \"FOUNDER_TAKEOVER\",\n)\n\n\ndef make_task_envelope(\n    *,\n    task_id,\n    title,\n    objective,\n    acceptance_criteria,\n    safety_class=\"SAFE_INTERNAL\",\n    owner_role=\"ENGINEERING\",\n    inputs=None,\n    dependencies=None,\n    expected_artifacts=None,\n    branch=None,\n    attempts=0,\n    blocker=None,\n):\n    \"\"\"Validate and normalise a task envelope (schema: schemas/task_envelope_v1.json).\"\"\"\n    missing = []\n    if not task_id:\n        missing.append(\"task_id\")\n    if not title:\n        missing.append(\"title\")\n    if not objective:\n        missing.append(\"objective\")\n    if not acceptance_criteria:\n        missing.append(\"acceptance_criteria\")\n    if not owner_role:\n        missing.append(\"owner_role\")\n    if not branch:\n        missing.append(\"branch\")\n    if safety_class not in _SAFETY_CLASSES:\n        missing.append(\"safety_class(valid)\")\n\n    max_attempts = 3\n    envelope = {\n        \"schema_version\": \"task_envelope/v1\",\n        \"task_id\": task_id,\n        \"title\": title,\n        \"objective\": objective,\n        \"acceptance_criteria\": list(acceptance_criteria or []),\n        \"safety_class\": safety_class,\n        \"owner_role\": owner_role,\n        \"inputs\": list(inputs or []),\n        \"dependencies\": list(dependencies or []),\n        \"expected_artifacts\": list(expected_artifacts or []),\n        \"branch\": branch,\n        \"attempts\": int(attempts or 0),\n        \"max_attempts\": max_attempts,\n        \"blocker\": blocker,\n        \"production_authority\": PRODUCTION_AUTHORITY,\n        \"release_gate\": RELEASE_GATE,\n        \"well_formed\": not missing,\n        \"missing_fields\": missing,\n    }\n    envelope[\"envelope_digest\"] = digest(envelope)\n    return envelope\n\n\ndef make_result_envelope(task_env, *, result, evidence=None, tests=None, artifacts=None, blockers=None, next_task=None):\n    \"\"\"Build a result envelope. PASS requires artifacts + tests + verified evidence.\"\"\"\n    tests = dict(tests or {})\n    artifacts = list(artifacts or [])\n    blockers = list(blockers or [])\n\n    claimed_pass = bool(result) and bool(artifacts) and bool(tests) and bool(evidence)\n    tests_ok = bool(tests.get(\"total\")) and tests.get(\"failed\", 0) == 0\n    evidence_ok = bool(evidence) and evidence.get(\"evidence_status\") == \"VERIFIED\"\n\n    if not task_env.get(\"well_formed\", False):\n        status, reason = \"BLOCKED\", \"task_envelope is not well formed: \" + \",\".join(task_env.get(\"missing_fields\", []))\n    elif blockers and not artifacts:\n        status, reason = \"BLOCKED\", \"blocked with no artifacts produced\"\n    elif not evidence:\n        status, reason = \"NOT_VERIFIED\", \"result carries no evidence block\"\n    elif not evidence_ok:\n        status, reason = \"NOT_VERIFIED\", \"evidence is not verifiable (missing source or run_id)\"\n    elif not tests_ok:\n        status, reason = \"FAIL\", \"tests did not pass or no tests were recorded\"\n    elif claimed_pass:\n        status, reason = \"PASS\", \"artifacts, passing tests and verifiable evidence present\"\n    else:\n        status, reason = \"NOT_VERIFIED\", \"insufficient artifacts for a PASS claim\"\n\n    envelope = {\n        \"schema_version\": \"result_envelope/v1\",\n        \"task_id\": task_env.get(\"task_id\"),\n        \"status\": status,\n        \"status_reason\": reason,\n        \"artifacts\": artifacts,\n        \"tests\": tests,\n        \"evidence\": evidence,\n        \"blockers\": blockers,\n        \"next_task\": next_task,\n        \"algorithm_version\": ALGORITHM_VERSION,\n        \"production_authority\": PRODUCTION_AUTHORITY,\n        \"release_gate\": RELEASE_GATE,\n        \"failure_history_preserved\": True,\n    }\n    envelope[\"envelope_digest\"] = digest({k: v for k, v in envelope.items() if k != \"envelope_digest\"})\n    return envelope\n\n\ndef should_escalate_to_founder(attempts, max_attempts=3):\n    \"\"\"Autonomous repair may run at most ``max_attempts`` times before escalation.\"\"\"\n    return int(attempts) >= int(max_attempts)\n", "evidence.py": "\"\"\"Evidence and tamper-evident audit primitives for Verity Family Wealth Engine E0.\n\nEvery engine output must be traceable to inputs, sources, algorithm version and a run\nidentifier. Anything that cannot be traced is explicitly tagged NOT_VERIFIED.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nfrom datetime import datetime, timezone\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    EVIDENCE_STATUS_NOT_VERIFIED,\n    EVIDENCE_STATUS_VERIFIED,\n)\n\nGENESIS_HASH = \"0\" * 64\n\n#: S-27-08：审计链边界的单一权威披露。链自洽（哈希串联可复核）只证明\n#: 「记录之间没有被静默改写」，不等于外部不可篡改：总账此前仅存于进程内存，\n#: 无签名、无外部见证/锚点，具备本机写权限者理论上可重写链尾并保持自洽。\n#: 对外提供审计接口（partner 协议）之前，必须对根哈希做外部锚定（服务端\n#: 签名或写入宿主不可变存储/外部见证），本常量随之更新。\nAUDIT_CHAIN_NOTICE = (\n    \"Audit chain self-consistency (recomputed hash linkage) is not external immutability: \"\n    \"the ledger is in-memory only, has no external anchor, and a party with local \"\n    \"write access could rewrite the tail while keeping the chain self-consistent.\"\n)\n\n\ndef _canonical(payload) -> str:\n    \"\"\"Stable JSON encoding used for all digests. Key order must never matter.\"\"\"\n    return json.dumps(payload, sort_keys=True, separators=(\",\", \":\"), default=str)\n\n\ndef digest(payload) -> str:\n    \"\"\"SHA-256 of the canonical form of ``payload``.\"\"\"\n    return hashlib.sha256(_canonical(payload).encode(\"utf-8\")).hexdigest()\n\n\ndef utc_now_iso() -> str:\n    return datetime.now(timezone.utc).replace(microsecond=0).isoformat()\n\n\ndef make_evidence(\n    payload,\n    *,\n    sources,\n    run_id,\n    assumptions=None,\n    algorithm_version=ALGORITHM_VERSION,\n    inputs_digest=None,\n    supports=None,\n    computed_at_utc=None,\n):\n    \"\"\"Build an evidence block.\n\n    Evidence is only marked VERIFIED when it carries both a non-empty ``sources``\n    list and a ``run_id``. Everything else fails closed to NOT_VERIFIED.\n    \"\"\"\n    sources = [s for s in (sources or []) if s]\n    assumptions = list(assumptions or [])\n    supports = list(supports or [])\n\n    if inputs_digest is None:\n        inputs_digest = digest(payload)\n\n    traceable = bool(sources) and bool(run_id)\n\n    evidence = {\n        \"evidence_status\": EVIDENCE_STATUS_VERIFIED if traceable else EVIDENCE_STATUS_NOT_VERIFIED,\n        \"sources\": sources,\n        \"algorithm_version\": algorithm_version,\n        \"run_id\": run_id or None,\n        \"assumptions\": assumptions,\n        \"supports\": supports,\n        \"inputs_digest\": inputs_digest,\n        \"output_digest\": digest(payload),\n        \"computed_at_utc\": computed_at_utc or utc_now_iso(),\n        \"record_hash\": None,\n        \"limits\": [\n            \"Synthetic data only; no real client data is used anywhere in E0.\",\n            \"Simulation output is not a forecast and is not real performance.\",\n            \"No specific security, fund, insurer or product is recommended.\",\n        ],\n    }\n    if not traceable:\n        evidence[\"limits\"].append(\n            \"Missing source or run_id; this result is not independently verifiable.\"\n        )\n    evidence[\"record_hash\"] = digest({k: v for k, v in evidence.items() if k != \"record_hash\"})\n    return evidence\n\n\ndef build_audit_record(result, *, run_id, prev_hash=GENESIS_HASH, sequence=0):\n    \"\"\"Create one append-only audit record chained to ``prev_hash``.\n\n    The hash chain makes later mutation or deletion detectable: recomputing the\n    chain from the genesis hash will diverge at the tampered record.\n    \"\"\"\n    record = {\n        \"sequence\": sequence,\n        \"run_id\": run_id,\n        \"recorded_at_utc\": utc_now_iso(),\n        \"algorithm_version\": ALGORITHM_VERSION,\n        \"risk_notice\": (\n            \"Decision support only. Not investment, legal, tax or insurance advice. \"\n            \"Verity holds no production authority in E0.\"\n        ),\n        \"payload_digest\": digest(result),\n    }\n    body = {k: v for k, v in record.items()}\n    body[\"prev_hash\"] = prev_hash\n    record[\"prev_hash\"] = prev_hash\n    record[\"record_hash\"] = digest(body)\n    return record\n\n\ndef verify_audit_chain(records):\n    \"\"\"Recompute a hash chain. Returns (ok, first_bad_sequence_or_None).\"\"\"\n    prev = GENESIS_HASH\n    for expected_seq, record in enumerate(records):\n        if record.get(\"sequence\") != expected_seq:\n            return False, expected_seq\n        if record.get(\"prev_hash\") != prev:\n            return False, expected_seq\n        body = {k: v for k, v in record.items() if k != \"record_hash\"}\n        if digest(body) != record.get(\"record_hash\"):\n            return False, expected_seq\n        prev = record.get(\"record_hash\")\n    return True, None\n", "feasibility.py": "\"\"\"Return-goal feasibility.\n\nThe engine is allowed to say four things and only four things:\n\n    PASS     the goal fits inside the household's survivable risk budget\n    REVIEW   the goal may fit, but evidence is thin or the buffer is narrow\n    REFUSE   the goal structurally conflicts with the household survival floor\n    ABSTAIN  evidence is insufficient, so the engine refuses to judge (fail-closed)\n\nRule order matters. Insufficient evidence and incoherent evidence are resolved BEFORE\nany judgement is expressed, because a confident answer built on missing data is exactly\nthe failure mode Verity exists to prevent.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    HIGH_TARGET_MAX_LOSS_REQUIRED,\n    HIGH_TARGET_RETURN,\n    REFUSE_MAX_LOSS_FLOOR,\n    REFUSE_MIN_SURVIVAL_DAYS,\n    REVIEW_DEBT_PRESSURE,\n    REVIEW_SURVIVAL_DAYS,\n)\nfrom engine.household import validate_profile\n\nVERDICTS = (\"PASS\", \"REVIEW\", \"REFUSE\", \"ABSTAIN\")\n\nVERDICT_MEANING = {\n    \"PASS\": \"The goal fits inside the household's survivable risk budget; simulation may proceed.\",\n    \"REVIEW\": \"The goal may fit, but the buffer is narrow or evidence needs human review.\",\n    \"REFUSE\": \"The goal structurally conflicts with what this household can survive.\",\n    \"ABSTAIN\": \"Evidence is insufficient or incoherent; Verity refuses to judge.\",\n}\n\n\ndef _number(value, default=None):\n    if isinstance(value, bool) or value is None:\n        return default\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return default\n    if number != number or number in (float(\"inf\"), float(\"-inf\")):\n        return default\n    return number\n\n\ndef _result(verdict, reason_codes, reasons, *, target, tolerance, achievable, evidence_note=None):\n    evidence = {\n        \"algorithm_version\": ALGORITHM_VERSION,\n        \"method\": \"ordered rule evaluation over survival capacity and risk budget\",\n        \"assumptions\": [\n            f\"Loss tolerance below {REFUSE_MAX_LOSS_FLOOR:.0%} cannot fund a durable growth plan.\",\n            f\"Survival below {REFUSE_MIN_SURVIVAL_DAYS} days is treated as an uninsurable position.\",\n            f\"Targets above {HIGH_TARGET_RETURN:.0%} require at least {HIGH_TARGET_MAX_LOSS_REQUIRED:.0%} loss capacity.\",\n            f\"Survival below {REVIEW_SURVIVAL_DAYS} days or debt pressure above {REVIEW_DEBT_PRESSURE:.0%} forces REVIEW.\",\n            \"ABSTAIN is returned whenever required evidence is missing or incoherent.\",\n        ],\n        \"computed_at_utc\": None,\n        \"sources\": [\"docs/INTERFACE_FREEZE_V0_1.md\"],\n    }\n    if evidence_note:\n        evidence[\"assumptions\"].append(evidence_note)\n    return {\n        \"verdict\": verdict,\n        \"verdict_meaning\": VERDICT_MEANING[verdict],\n        \"reason_codes\": list(reason_codes),\n        \"reasons\": list(reasons),\n        \"required_return_for_goal\": target,\n        \"max_tolerable_loss_pct\": tolerance,\n        \"achievable_return_proxy\": achievable,\n        \"evidence\": evidence,\n    }\n\n\n#: A deliberately conservative reference portfolio return used only to describe the\n#: gap between what the family wants and what a diversified plan plausibly delivers.\nACHIEVABLE_RETURN_PROXY = 0.055\n\n\ndef assess_feasibility(profile, safety, layers):\n    \"\"\"Judge whether the family's stated return goal is realistic.\"\"\"\n    if not isinstance(profile, dict):\n        profile = {}\n    safety = safety if isinstance(safety, dict) else {}\n    layers = layers if isinstance(layers, dict) else {}\n\n    target = _number(profile.get(\"target_annual_return\"), None)\n    tolerance = _number(profile.get(\"max_tolerable_loss_pct\"), None)\n\n    # --- rule 1: missing evidence -> ABSTAIN ---\n    try:\n        validation = validate_profile(profile)\n    except Exception as exc:  # noqa: BLE001\n        return _result(\n            \"ABSTAIN\",\n            [\"PROFILE_VALIDATION_ERROR\"],\n            [f\"Profile validation failed: {type(exc).__name__}: {exc}\"],\n            target=target,\n            tolerance=tolerance,\n            achievable=ACHIEVABLE_RETURN_PROXY,\n        )\n\n    if validation.get(\"missing_required\"):\n        return _result(\n            \"ABSTAIN\",\n            [\"MISSING_REQUIRED_INPUT\"],\n            [\n                \"Verity cannot judge a goal without these inputs: \"\n                + \", \".join(validation[\"missing_required\"])\n            ],\n            target=target,\n            tolerance=tolerance,\n            achievable=ACHIEVABLE_RETURN_PROXY,\n        )\n\n    # --- rule 2: incoherent evidence -> ABSTAIN ---\n    if validation.get(\"inconsistent\"):\n        return _result(\n            \"ABSTAIN\",\n            [\"INCONSISTENT_INPUT\"],\n            [\"The profile is internally contradictory: \" + \"; \".join(validation[\"inconsistent\"])],\n            target=target,\n            tolerance=tolerance,\n            achievable=ACHIEVABLE_RETURN_PROXY,\n        )\n\n    if target is None or tolerance is None:\n        return _result(\n            \"ABSTAIN\",\n            [\"MISSING_REQUIRED_INPUT\"],\n            [\"Target return or loss tolerance could not be read as a number.\"],\n            target=target,\n            tolerance=tolerance,\n            achievable=ACHIEVABLE_RETURN_PROXY,\n        )\n\n    safety_days = _number(safety.get(\"safety_days\"), 0.0) or 0.0\n    debt_pressure = safety.get(\"debt_pressure_ratio\", 0.0)\n    reason_codes = []\n    reasons = []\n\n    # --- rule 3: survivability floor ---\n    if tolerance < REFUSE_MAX_LOSS_FLOOR:\n        reason_codes.append(\"LOSS_TOLERANCE_BELOW_FLOOR\")\n        reasons.append(\n            f\"Maximum tolerable loss {tolerance:.1%} is below the {REFUSE_MAX_LOSS_FLOOR:.0%} \"\n            \"floor needed to hold any growth asset through a normal cycle.\"\n        )\n    if safety_days < REFUSE_MIN_SURVIVAL_DAYS:\n        reason_codes.append(\"SURVIVAL_DAYS_BELOW_FLOOR\")\n        reasons.append(\n            f\"Safety days {safety_days:.1f} are below the {REFUSE_MIN_SURVIVAL_DAYS}-day floor; \"\n            \"the household survival floor is not protected.\"\n        )\n    if reason_codes:\n        return _result(\n            \"REFUSE\", reason_codes, reasons,\n            target=target, tolerance=tolerance, achievable=ACHIEVABLE_RETURN_PROXY,\n        )\n\n    # --- rule 4: an ambitious target needs a real risk budget ---\n    if target > HIGH_TARGET_RETURN and tolerance < HIGH_TARGET_MAX_LOSS_REQUIRED:\n        return _result(\n            \"REFUSE\",\n            [\"GOAL_EXCEEDS_RISK_BUDGET\"],\n            [\n                f\"A target of {target:.1%} requires accepting a loss budget of at least \"\n                f\"{HIGH_TARGET_MAX_LOSS_REQUIRED:.0%}; the family's stated tolerance is {tolerance:.1%}.\"\n            ],\n            target=target, tolerance=tolerance, achievable=ACHIEVABLE_RETURN_PROXY,\n        )\n\n    # --- rule 5: thin buffer or heavy debt -> REVIEW, not a green light ---\n    review_codes = []\n    review_reasons = []\n    if safety_days < REVIEW_SURVIVAL_DAYS:\n        review_codes.append(\"SURVIVAL_BUFFER_THIN\")\n        review_reasons.append(\n            f\"Safety days {safety_days:.1f} are below the {REVIEW_SURVIVAL_DAYS}-day review threshold.\"\n        )\n    if debt_pressure is None:\n        review_codes.append(\"DEBT_PRESSURE_UNDETERMINABLE\")\n        review_reasons.append(\n            \"Debt service exists but no household income is recorded, so debt pressure cannot be verified.\"\n        )\n    elif debt_pressure > REVIEW_DEBT_PRESSURE:\n        review_codes.append(\"DEBT_PRESSURE_HIGH\")\n        review_reasons.append(\n            f\"Debt service consumes {debt_pressure:.1%} of gross income, above the \"\n            f\"{REVIEW_DEBT_PRESSURE:.0%} review threshold.\"\n        )\n    if layers.get(\"funding_status\") == \"DEFICIT\":\n        review_codes.append(\"SURVIVAL_LAYER_UNFUNDED\")\n        review_reasons.append(\"Recorded assets do not fully fund the survival and duty layers.\")\n    if review_codes:\n        return _result(\n            \"REVIEW\", review_codes, review_reasons,\n            target=target, tolerance=tolerance, achievable=ACHIEVABLE_RETURN_PROXY,\n        )\n\n    # --- rule 6: goal fits inside a survivable budget ---\n    return _result(\n        \"PASS\",\n        [\"GOAL_WITHIN_RISK_BUDGET\"],\n        [\n            f\"Safety days {safety_days:.1f} clear the {REVIEW_SURVIVAL_DAYS}-day threshold and \"\n            f\"the {target:.1%} target sits inside a {tolerance:.1%} loss budget.\"\n        ],\n        target=target, tolerance=tolerance, achievable=ACHIEVABLE_RETURN_PROXY,\n    )\n", "household.py": "\"\"\"Household profile validation.\n\nThe engine must never crash on a bad profile: it labels the profile instead, and\ndownstream modules refuse to judge (ABSTAIN) when required evidence is absent.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    MAX_LEVERAGE_MULTIPLE,\n    MAX_PLAUSIBLE_AGE,\n    MAX_PLAUSIBLE_AMOUNT,\n    MAX_PLAUSIBLE_HORIZON_YEARS,\n    MAX_PLAUSIBLE_SURVIVAL_DAYS,\n    MIN_PLAUSIBLE_AGE,\n)\n\n#: Keys that must be present for the engine to be allowed to produce a verdict.\nREQUIRED_KEYS = (\n    \"members\",\n    \"annual_expenses_essential\",\n    \"assets\",\n    \"investment_horizon_years\",\n    \"target_annual_return\",\n    \"max_tolerable_loss_pct\",\n)\n\nASSET_KINDS = (\n    \"cash\",\n    \"bond\",\n    \"global_index\",\n    \"equity\",\n    \"gold\",\n    \"option_protection\",\n    \"insurance_linked\",\n    \"illiquid\",\n)\nLIABILITY_KINDS = (\"mortgage\", \"consumer\", \"margin\", \"student\", \"other\")\nPROTECTION_KINDS = (\"life\", \"disability\", \"health\", \"property\", \"liability\")\nLIQUIDITIES = (\"immediate\", \"near\", \"cannot_touch\")\n\n\n#: Validation messages that the Chinese console renders (T-E0-008 F-03). Kept as\n#: module constants so the i18n contract and the source-scanning test stay in sync.\n_CURRENCY_CODE_INVALID = \"currency must be a three-letter code, for example CNY\"\n_CURRENCY_CODE_INVALID_ITEM = \"{group_name}[{index}].currency must be a three-letter code\"\n_CURRENCY_FOREIGN = (\n    \"recorded currency {code} ({where}) marks a foreign-currency exposure against reporting \"\n    \"currency {base}; E0 performs no FX conversion and reads the recorded amount in {base} \"\n    \"major units\"\n)\n_CURRENCY_MULTI = (\n    \"recorded items use several currencies ({codes}); \"\n    \"E0 has no FX model and will not add amounts across currencies\"\n)\n\n#: Plausibility messages (T-E0-008 F-04). Also kept as constants for the i18n contract.\n_AMOUNT_IMPLAUSIBLE = (\n    \"{label} is at or above the E0 plausibility ceiling; \"\n    \"the engine will not judge a household on a number it cannot stand behind\"\n)\n_AGE_IMPLAUSIBLE = \"members[{index}].age must be between 0 and 130 years\"\n_SURVIVAL_DAYS_INVALID = (\n    \"survival_target_days must be a positive number of days no greater than {limit}\"\n)\n_HORIZON_IMPLAUSIBLE = (\n    \"investment_horizon_years above {limit} is outside the E0 contract\"\n)\n\n\ndef _amount_issue(label, value):\n    \"\"\"Return a message when an amount is too large to be a household fact.\"\"\"\n    if value is None:\n        return None\n    if abs(value) >= MAX_PLAUSIBLE_AMOUNT:\n        return _AMOUNT_IMPLAUSIBLE.format(label=label)\n    return None\n\n\ndef _is_currency_code(value):\n    \"\"\"True for a three-letter ISO-style currency code such as CNY or USD.\"\"\"\n    return isinstance(value, str) and len(value.strip()) == 3 and value.strip().isalpha()\n\n\ndef _number(value):\n    \"\"\"Return ``value`` as float, or None when it is not a usable finite number.\"\"\"\n    if isinstance(value, bool) or value is None:\n        return None\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return None\n    if number != number or number in (float(\"inf\"), float(\"-inf\")):\n        return None\n    return number\n\n\ndef _sum_values(items, key=\"value\"):\n    total = 0.0\n    for item in items:\n        number = _number(item.get(key))\n        if number:\n            total += number\n    return total\n\n\ndef _evidence():\n    return {\n        \"algorithm_version\": ALGORITHM_VERSION,\n        \"method\": \"structural validation of the household profile against the frozen E0 contract\",\n        \"assumptions\": [\n            \"A profile is usable only when every required key is present.\",\n            \"Contradictory values are treated as missing evidence, not as a judgement.\",\n        ],\n        \"computed_at_utc\": None,\n        \"sources\": [\"docs/INTERFACE_FREEZE_V0_1.md\"],\n    }\n\n\ndef validate_profile(profile):\n    \"\"\"Validate a household profile.\n\n    Returns ``{\"valid\", \"missing_required\", \"inconsistent\", \"warnings\", \"evidence\"}``.\n    \"\"\"\n    missing = []\n    inconsistent = []\n    #: 「输入不可信」类问题（类型错误、非有限数、可信度越界、币种含混）：整份结果必须弃权。\n    #: 与「财务状态极端」（例如杠杆超过 10 倍）区分开 —— 后者是真实但艰难的家庭处境，\n    #: 引擎照常给出数字，只在判定层弃权；否则最需要答案的家庭反而什么也拿不到。\n    data_issues = []\n    warnings = []\n\n    def flag_data_issue(message):\n        data_issues.append(message)\n        inconsistent.append(message)\n\n    if not isinstance(profile, dict):\n        return {\n            \"valid\": False,\n            \"missing_required\": list(REQUIRED_KEYS),\n            \"inconsistent\": [\"profile is not an object\"],\n            \"data_issues\": [\"profile is not an object\"],\n            \"warnings\": [],\n            \"evidence\": _evidence(),\n        }\n\n    for key in REQUIRED_KEYS:\n        if key not in profile or profile.get(key) is None:\n            missing.append(key)\n\n    # --- members ---\n    members = profile.get(\"members\")\n    if members is not None:\n        if not isinstance(members, list) or not members:\n            inconsistent.append(\"members must be a non-empty list\")\n        else:\n            for index, member in enumerate(members):\n                if not isinstance(member, dict):\n                    inconsistent.append(f\"members[{index}] must be an object\")\n                    continue\n                income = _number(member.get(\"annual_income\"))\n                if income is None:\n                    inconsistent.append(f\"members[{index}].annual_income must be numeric\")\n                elif income < 0:\n                    flag_data_issue(f\"members[{index}].annual_income must not be negative\")\n                else:\n                    issue = _amount_issue(f\"members[{index}].annual_income\", income)\n                    if issue:\n                        flag_data_issue(issue)\n                age = _number(member.get(\"age\"))\n                if age is not None and (age < MIN_PLAUSIBLE_AGE or age > MAX_PLAUSIBLE_AGE):\n                    flag_data_issue(_AGE_IMPLAUSIBLE.format(index=index))\n                stability = member.get(\"income_stability\")\n                if stability is not None and stability not in (\"high\", \"medium\", \"low\"):\n                    warnings.append(\n                        f\"members[{index}].income_stability '{stability}' is unknown; treated as medium\"\n                    )\n\n    # --- expenses ---\n    essential = _number(profile.get(\"annual_expenses_essential\"))\n    if \"annual_expenses_essential\" not in missing:\n        if essential is None:\n            inconsistent.append(\"annual_expenses_essential must be numeric\")\n        elif essential <= 0:\n            inconsistent.append(\"annual_expenses_essential must be greater than zero\")\n        else:\n            issue = _amount_issue(\"annual_expenses_essential\", essential)\n            if issue:\n                flag_data_issue(issue)\n\n    discretionary = profile.get(\"annual_expenses_discretionary\")\n    if discretionary is not None:\n        discretionary_number = _number(discretionary)\n        if discretionary_number is None:\n            inconsistent.append(\"annual_expenses_discretionary must be numeric\")\n        elif discretionary_number < 0:\n            inconsistent.append(\"annual_expenses_discretionary must not be negative\")\n        else:\n            issue = _amount_issue(\"annual_expenses_discretionary\", discretionary_number)\n            if issue:\n                flag_data_issue(issue)\n\n    # --- assets ---\n    assets = profile.get(\"assets\")\n    total_assets = 0.0\n    if assets is not None:\n        if not isinstance(assets, list):\n            inconsistent.append(\"assets must be a list\")\n        else:\n            if not assets:\n                warnings.append(\"assets list is empty; the family holds no recorded assets\")\n            for index, asset in enumerate(assets):\n                if not isinstance(asset, dict):\n                    inconsistent.append(f\"assets[{index}] must be an object\")\n                    continue\n                value = _number(asset.get(\"value\"))\n                if value is None:\n                    inconsistent.append(f\"assets[{index}].value must be numeric\")\n                elif value < 0:\n                    inconsistent.append(f\"assets[{index}].value must not be negative\")\n                else:\n                    total_assets += value\n                    issue = _amount_issue(f\"assets[{index}].value\", value)\n                    if issue:\n                        flag_data_issue(issue)\n                kind = asset.get(\"kind\")\n                if kind is not None and kind not in ASSET_KINDS:\n                    warnings.append(f\"assets[{index}].kind '{kind}' is outside the E0 vocabulary\")\n                liquidity = asset.get(\"liquidity\")\n                if liquidity is not None and liquidity not in LIQUIDITIES:\n                    warnings.append(\n                        f\"assets[{index}].liquidity '{liquidity}' is outside the E0 vocabulary\"\n                    )\n\n    # --- liabilities ---\n    liabilities = profile.get(\"liabilities\") or []\n    total_liabilities = 0.0\n    if not isinstance(liabilities, list):\n        inconsistent.append(\"liabilities must be a list\")\n        liabilities = []\n    for index, liability in enumerate(liabilities):\n        if not isinstance(liability, dict):\n            inconsistent.append(f\"liabilities[{index}] must be an object\")\n            continue\n        balance = _number(liability.get(\"balance\"))\n        if balance is None:\n            inconsistent.append(f\"liabilities[{index}].balance must be numeric\")\n        elif balance < 0:\n            inconsistent.append(f\"liabilities[{index}].balance must not be negative\")\n        else:\n            total_liabilities += balance\n            issue = _amount_issue(f\"liabilities[{index}].balance\", balance)\n            if issue:\n                flag_data_issue(issue)\n        payment = liability.get(\"mandatory_payment\")\n        if payment is not None and _number(payment) is None:\n            inconsistent.append(f\"liabilities[{index}].mandatory_payment must be numeric\")\n        else:\n            issue = _amount_issue(f\"liabilities[{index}].mandatory_payment\", _number(payment))\n            if issue:\n                flag_data_issue(issue)\n        kind = liability.get(\"kind\")\n        if kind is not None and kind not in LIABILITY_KINDS:\n            warnings.append(f\"liabilities[{index}].kind '{kind}' is outside the E0 vocabulary\")\n\n    # --- protection ---\n    protection = profile.get(\"protection\") or []\n    if not isinstance(protection, list):\n        inconsistent.append(\"protection must be a list\")\n        protection = []\n    for index, policy in enumerate(protection):\n        if not isinstance(policy, dict):\n            inconsistent.append(f\"protection[{index}] must be an object\")\n            continue\n        coverage = policy.get(\"coverage\")\n        if coverage is not None and (_number(coverage) is None or _number(coverage) < 0):\n            inconsistent.append(f\"protection[{index}].coverage must be a non-negative number\")\n        else:\n            issue = _amount_issue(f\"protection[{index}].coverage\", _number(coverage))\n            if issue:\n                flag_data_issue(issue)\n        premium = policy.get(\"annual_premium\")\n        if premium is not None and (_number(premium) is None or _number(premium) < 0):\n            inconsistent.append(f\"protection[{index}].annual_premium must be a non-negative number\")\n        else:\n            issue = _amount_issue(f\"protection[{index}].annual_premium\", _number(premium))\n            if issue:\n                flag_data_issue(issue)\n\n    # --- rigid future outflows ---\n    outflows = profile.get(\"future_rigid_outflows\") or []\n    if not isinstance(outflows, list):\n        inconsistent.append(\"future_rigid_outflows must be a list\")\n        outflows = []\n    for index, outflow in enumerate(outflows):\n        if not isinstance(outflow, dict):\n            inconsistent.append(f\"future_rigid_outflows[{index}] must be an object\")\n            continue\n        amount = _number(outflow.get(\"amount\"))\n        if amount is None or amount < 0:\n            inconsistent.append(f\"future_rigid_outflows[{index}].amount must be non-negative\")\n        else:\n            issue = _amount_issue(f\"future_rigid_outflows[{index}].amount\", amount)\n            if issue:\n                flag_data_issue(issue)\n        years = _number(outflow.get(\"years_until_due\"))\n        if years is None or years < 0:\n            inconsistent.append(f\"future_rigid_outflows[{index}].years_until_due must be non-negative\")\n\n    # --- horizon ---\n    horizon = _number(profile.get(\"investment_horizon_years\"))\n    if \"investment_horizon_years\" not in missing:\n        if horizon is None:\n            inconsistent.append(\"investment_horizon_years must be numeric\")\n        elif horizon <= 0:\n            inconsistent.append(\"investment_horizon_years must be greater than zero\")\n        elif horizon > MAX_PLAUSIBLE_HORIZON_YEARS:\n            flag_data_issue(_HORIZON_IMPLAUSIBLE.format(limit=int(MAX_PLAUSIBLE_HORIZON_YEARS))\n            )\n        elif horizon > 60:\n            warnings.append(\"investment_horizon_years above 60 is unusual; treated as stated\")\n\n    # --- target return ---\n    target = _number(profile.get(\"target_annual_return\"))\n    if \"target_annual_return\" not in missing:\n        if target is None:\n            inconsistent.append(\"target_annual_return must be numeric\")\n        elif target < 0:\n            inconsistent.append(\"target_annual_return must not be negative\")\n        elif target > 1.0:\n            inconsistent.append(\"target_annual_return above 100% per year is not a credible input\")\n\n    # --- loss tolerance ---\n    tolerance = _number(profile.get(\"max_tolerable_loss_pct\"))\n    if \"max_tolerable_loss_pct\" not in missing:\n        if tolerance is None:\n            inconsistent.append(\"max_tolerable_loss_pct must be numeric\")\n        elif tolerance < 0 or tolerance > 1.0:\n            inconsistent.append(\"max_tolerable_loss_pct must be a fraction between 0 and 1\")\n\n    # --- survival target days (T-E0-008 M-02) ---\n    # 过去 NaN / 0 / 负数会被静默换成默认 180 天，用户看不到任何提示：\n    # 一份「生存底线 0 天」的档案会算出 180 天的结论。现在它必须被明确拒绝。\n    target_days = profile.get(\"survival_target_days\")\n    if target_days is not None:\n        days = _number(target_days)\n        if days is None or days <= 0 or days > MAX_PLAUSIBLE_SURVIVAL_DAYS:\n            flag_data_issue(_SURVIVAL_DAYS_INVALID.format(limit=int(MAX_PLAUSIBLE_SURVIVAL_DAYS)))\n\n    # --- recorded annual goal figures (T-E0-008 F-04) ---\n    annual_goal = profile.get(\"annual_goal\")\n    if isinstance(annual_goal, dict):\n        for key in (\"recorded_net_gain\", \"locked_profit\"):\n            issue = _amount_issue(f\"annual_goal.{key}\", _number(annual_goal.get(key)))\n            if issue:\n                flag_data_issue(issue)\n\n    # --- currency coherence (T-E0-008 F-03) ---\n    # E0 holds no FX model. Adding amounts recorded in different currencies at a\n    # 1:1 rate would produce a number the family never has, so a mismatch is\n    # treated as contradictory evidence and the whole run abstains.\n    household_currency = profile.get(\"currency\")\n    if household_currency is not None:\n        if not _is_currency_code(household_currency):\n            flag_data_issue(_CURRENCY_CODE_INVALID)\n            household_currency = None\n    recorded_currencies = {}\n    for group_name, group in (\n        (\"assets\", assets),\n        (\"liabilities\", liabilities),\n        (\"protection\", protection),\n        (\"future_rigid_outflows\", outflows),\n    ):\n        if not isinstance(group, list):\n            continue\n        for index, item in enumerate(group):\n            if not isinstance(item, dict):\n                continue\n            recorded = item.get(\"currency\")\n            if recorded is None:\n                continue\n            if not _is_currency_code(recorded):\n                flag_data_issue(_CURRENCY_CODE_INVALID_ITEM.format(group_name=group_name, index=index)\n                )\n                continue\n            recorded_currencies.setdefault(str(recorded).strip().upper(), []).append(\n                f\"{group_name}[{index}]\"\n            )\n    if household_currency is not None:\n        base = str(household_currency).strip().upper()\n        for code in sorted(recorded_currencies):\n            if code != base:\n                # 外币计价是受支持的输入（它驱动汇率压力情景），不是矛盾证据。\n                # 契约规定金额以记账币种的主单位读入，E0 不做汇率换算 —— 这一点\n                # 必须让用户看得见，所以留一条警告，而不是悄悄按 1:1 混进去。\n                warnings.append(\n                    _CURRENCY_FOREIGN.format(\n                        code=code,\n                        where=\", \".join(recorded_currencies[code][:3]),\n                        base=base,\n                    )\n                )\n    elif len(recorded_currencies) > 1:\n        # 连记账币种都没记录，却出现了多种币种 —— 这时「金额是什么单位」无从确定，\n        # 属于真正的矛盾证据，必须失败关闭。\n        flag_data_issue(_CURRENCY_MULTI.format(codes=\", \".join(sorted(recorded_currencies)))\n        )\n\n    # --- leverage sanity ---\n    if total_liabilities > 0 and total_liabilities > max(total_assets, 0.0) * MAX_LEVERAGE_MULTIPLE:\n        inconsistent.append(\n            \"total liabilities exceed total assets by more than \"\n            f\"{MAX_LEVERAGE_MULTIPLE:.0f}x; the profile is not internally coherent\"\n        )\n\n    valid = not missing and not inconsistent\n    return {\n        \"valid\": valid,\n        \"missing_required\": missing,\n        \"inconsistent\": inconsistent,\n        \"data_issues\": data_issues,\n        \"warnings\": warnings,\n        \"total_assets\": total_assets,\n        \"total_liabilities\": total_liabilities,\n        \"evidence\": _evidence(),\n    }\n", "insurance.py": "\"\"\"Insurance audit module.\n\nInsurance is one module of the family wealth plan, never the product centre.\nThis module audits policies the family already records (or leaves empty) against\ndocumented, method-level needs:\n\n    life        -> income replacement (10x household gross income)\n    disability  -> income continuation (6 months x monthly gross income)\n    health      -> a major uninsured medical event (essential expenses x multiple)\n    liability   -> documented liability exposure (outstanding balances)\n\nIt reports coverage gaps, the premium burden and an overall coverage score. It\nnever names an insurer, never names a policy, and never recommends a product.\nWhen evidence is insufficient the whole audit fails closed to ABSTAIN.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    MEDICAL_SHOCK_MINIMUM,\n    MEDICAL_SHOCK_MULTIPLE_OF_ESSENTIAL,\n)\n\n#: Audit capabilities in display order, with policy kinds that count as coverage.\nCAPABILITY_ORDER = (\"life\", \"disability\", \"health\", \"liability\")\nCAPABILITY_POLICY_KINDS = {\n    \"life\": (\"life\",),\n    \"disability\": (\"disability\",),\n    \"health\": (\"health\",),\n    \"liability\": (\"liability\",),\n}\nCAPABILITY_LABELS = {\n    \"life\": \"寿险/身故保障\",\n    \"disability\": \"失能/收入保障\",\n    \"health\": \"医疗/健康保障\",\n    \"liability\": \"责任保障\",\n}\n\nLIFE_MULTIPLE_OF_INCOME = 10.0\nDISABILITY_COVERAGE_YEARS = 0.5  # six months of gross income\nPREMIUM_BURDEN_LOW = 0.05\nPREMIUM_BURDEN_MEDIUM = 0.10\n\n\ndef _number(value):\n    try:\n        if value is None:\n            return None\n        number = float(value)\n        if number != number or number in (float(\"inf\"), float(\"-inf\")):\n            return None\n        return number\n    except (TypeError, ValueError):\n        return None\n\n\ndef _income(profile):\n    total = 0.0\n    for member in profile.get(\"members\") or []:\n        if isinstance(member, dict):\n            total += max(0.0, _number(member.get(\"annual_income\")) or 0.0)\n    return total\n\n\ndef _essential_expenses(profile):\n    return max(0.0, _number(profile.get(\"annual_expenses_essential\")) or 0.0)\n\n\ndef _medical_need(essential):\n    return max(MEDICAL_SHOCK_MINIMUM, essential * MEDICAL_SHOCK_MULTIPLE_OF_ESSENTIAL)\n\n\ndef _liability_exposure(profile):\n    total = 0.0\n    for item in profile.get(\"liabilities\") or []:\n        if isinstance(item, dict):\n            total += max(0.0, _number(item.get(\"balance\")) or 0.0)\n    return total\n\n\ndef _coverage_totals(profile):\n    by_kind = {kind: 0.0 for kind in CAPABILITY_ORDER}\n    premium_total = 0.0\n    unknown = 0\n    for policy in profile.get(\"protection\") or []:\n        if not isinstance(policy, dict):\n            unknown += 1\n            continue\n        kind = policy.get(\"kind\")\n        coverage = max(0.0, _number(policy.get(\"coverage\")) or 0.0)\n        try:\n            by_kind[kind] += coverage\n        except KeyError:\n            unknown += 1\n        premium_total += max(0.0, _number(policy.get(\"annual_premium\")) or 0.0)\n    return by_kind, round(premium_total, 2), unknown\n\n\ndef _abstain(reason):\n    return {\n        \"status\": \"ABSTAIN\",\n        \"status_reason\": reason,\n        \"capabilities\": {},\n        \"capability_order\": list(CAPABILITY_ORDER),\n        \"coverage_score\": None,\n        \"premium_total\": None,\n        \"premium_to_income\": None,\n        \"premium_burden_status\": None,\n        \"warnings\": [reason],\n        \"disclaimer\": (\n            \"Verity recommends no insurer, no policy and no product. Any actual placement \"\n            \"requires a licensed partner and remains outside E0.\"\n        ),\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": \"Insurance audit abstained without sufficient household evidence.\",\n            \"assumptions\": [],\n            \"sources\": [],\n            \"computed_at_utc\": None,\n        },\n    }\n\n\ndef audit_insurance(profile, safety=None, allocation=None):\n    \"\"\"Audit recorded protection policies against documented family needs.\n\n    Fail-closed: never raises, never returns a confident answer without input.\n    ``safety`` and ``allocation`` are accepted for interface stability but the\n    audit derives its needs from the profile itself.\n    \"\"\"\n    profile = profile if isinstance(profile, dict) else {}\n    evidence = {\n        \"algorithm_version\": ALGORITHM_VERSION,\n        \"method\": (\n            \"Coverage audit of the family's recorded protection policies against \"\n            \"documented needs: 10x gross income (life), 6 months of gross income \"\n            \"(disability), a major medical event, and outstanding liability exposure. \"\n            \"No insurer, policy or product is named or recommended.\"\n        ),\n        \"assumptions\": [\n            \"Life need sizes to 10x household gross income; disability to 0.5x annual income.\",\n            \"Health need sizes to a major medical event based on essential spending.\",\n            \"Liability need equals the outstanding balance of recorded liabilities.\",\n            \"Premiums are a burden indicator only; they are not advice on affordability.\",\n        ],\n        \"sources\": [\"docs/INTERFACE_FREEZE_V0_1.md\"],\n        \"computed_at_utc\": None,\n    }\n    try:\n        income = _income(profile)\n        essential = _essential_expenses(profile)\n        by_kind, premium_total, unknown = _coverage_totals(profile)\n    except Exception:  # noqa: BLE001 - fail closed, never raise\n        return _abstain(\"Insurance audit could not interpret the household profile.\")\n\n    if not isinstance(profile.get(\"members\"), list) or not profile.get(\"members\"):\n        return _abstain(\"No household members recorded; insurance need cannot be sized.\")\n    if income <= 0 and essential <= 0:\n        return _abstain(\"No income or essential expenses recorded; insurance need cannot be sized.\")\n\n    needs = {\n        \"life\": round(income * LIFE_MULTIPLE_OF_INCOME, 2),\n        \"disability\": round(income * DISABILITY_COVERAGE_YEARS, 2),\n        \"health\": round(_medical_need(essential), 2),\n        \"liability\": round(_liability_exposure(profile), 2),\n    }\n\n    capabilities = {}\n    warnings = []\n    ratios = []\n    for capability in CAPABILITY_ORDER:\n        need = needs[capability]\n        coverage = round(by_kind[capability], 2)\n        gap = round(max(0.0, need - coverage), 2)\n        if need > 0:\n            ratio = min(1.0, coverage / need)\n        else:\n            ratio = 1.0 if coverage == 0 else min(1.0, coverage)\n        ratios.append(ratio)\n        if gap > 0:\n            status = \"PARTIAL\" if coverage > 0 else \"GAP\"\n            warnings.append(\n                f\"{CAPABILITY_LABELS[capability]} coverage gap of {gap:,.0f} \"\n                f\"(need {need:,.0f}, recorded {coverage:,.0f}).\"\n            )\n        else:\n            status = \"COVERED\" if need > 0 else \"NOT_APPLICABLE\"\n        capabilities[capability] = {\n            \"label_cn\": CAPABILITY_LABELS[capability],\n            \"need\": need,\n            \"coverage\": coverage,\n            \"gap\": gap,\n            \"status\": status,\n            \"coverage_ratio\": round(ratio, 4),\n        }\n\n    if unknown:\n        warnings.append(f\"{unknown} protection policy record(s) used an unknown kind and were excluded.\")\n\n    score = round(100.0 * sum(ratios) / max(1, len(ratios)), 1)\n    premium_ratio = round(premium_total / income, 6) if income > 0 else None\n    burden_status = None\n    if premium_ratio is not None:\n        if premium_ratio < PREMIUM_BURDEN_LOW:\n            burden_status = \"LOW\"\n        elif premium_ratio < PREMIUM_BURDEN_MEDIUM:\n            burden_status = \"MEDIUM\"\n        else:\n            burden_status = \"HIGH\"\n        if burden_status == \"HIGH\":\n            warnings.append(\n                f\"Premium burden of {premium_ratio:.1%} of gross income is HIGH relative to \"\n                \"the documented 5–10% reference band.\"\n            )\n    elif premium_total > 0:\n        warnings.append(\"Premium burden could not be sized because gross income is zero.\")\n\n    warnings.append(\n        \"Coverage gaps describe recorded protection only; Verity recommends no insurer \"\n        \"and no product. Any actual placement requires a licensed partner.\"\n    )\n\n    overall = \"OK\" if all(cap[\"status\"] in (\"COVERED\", \"NOT_APPLICABLE\") for cap in capabilities.values()) else \"GAPS\"\n\n    return {\n        \"status\": overall,\n        \"status_reason\": (\n            \"Recorded protection covers all documented needs.\"\n            if overall == \"OK\"\n            else \"Recorded protection has gaps against documented needs; gaps are listed per capability.\"\n        ),\n        \"capabilities\": capabilities,\n        \"capability_order\": list(CAPABILITY_ORDER),\n        \"coverage_score\": score,\n        \"premium_total\": premium_total,\n        \"premium_to_income\": premium_ratio,\n        \"premium_burden_status\": burden_status,\n        \"warnings\": warnings,\n        \"disclaimer\": (\n            \"Verity recommends no insurer, no policy and no product. This audit checks \"\n            \"what the family already records; coverage sizing is a documented reference, \"\n            \"not a policy quotation.\"\n        ),\n        \"evidence\": evidence,\n    }\n", "jsonstrict.py": "\"\"\"Strict-JSON safety net for engine output (T-E0-008 对抗性审查发现 F-01).\n\nPython happily serialises ``float('inf')`` / ``float('nan')`` as the bare tokens\n``Infinity`` / ``NaN``. Browsers do not: ``JSON.parse`` rejects those tokens, so a\nresult that \"looks fine\" inside Python becomes an unreadable payload in the user's\nconsole. An adversarial input (for example an asset value of 1e308, which overflows\nwhen layered) used to reach exactly that state: the engine correctly refused to\njudge, but the refusal itself could not be delivered.\n\nThe rule implemented here is the same rule the engine uses everywhere else: a number\nVerity cannot represent is a number Verity will not stand behind. Non-finite values\nare replaced by ``None`` and the caller fails closed (ABSTAIN) instead of shipping a\npayload that silently means something else in another language.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport math\n\n#: Reason code appended to the feasibility block whenever a value had to be suppressed.\nNON_FINITE_REASON_CODE = \"NON_FINITE_VALUE_SUPPRESSED\"\n\n\ndef is_non_finite_number(value) -> bool:\n    \"\"\"True only for real ``float`` values that are NaN or +/- infinity.\"\"\"\n    return isinstance(value, float) and not math.isfinite(value)\n\n\ndef sanitize_non_finite(value):\n    \"\"\"Return ``(cleaned, paths)``.\n\n    ``cleaned`` is a copy of ``value`` with every non-finite float replaced by\n    ``None``; ``paths`` lists the dotted locations that were suppressed so the\n    caller can record them as evidence instead of hiding the change.\n    \"\"\"\n    found: list[str] = []\n\n    def walk(node, path):\n        if is_non_finite_number(node):\n            found.append(path or \"$\")\n            return None\n        if isinstance(node, dict):\n            return {key: walk(item, f\"{path}.{key}\" if path else str(key)) for key, item in node.items()}\n        if isinstance(node, (list, tuple)):\n            return [walk(item, f\"{path}[{index}]\") for index, item in enumerate(node)]\n        return node\n\n    cleaned = walk(value, \"\")\n    return cleaned, found\n", "layering.py": "\"\"\"Family money layering.\n\nMoney is assigned in strict priority order. Survival is funded first and may never be\ncrowded out by a growth ambition:\n\n    survival -> near_term_duty -> protection -> long_term_growth -> high_risk_opportunity\n\nWhatever is left after the first three needs is split between long-term growth and a\nsmall high-risk opportunity sleeve.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    DEFAULT_SURVIVAL_TARGET_DAYS,\n    LAYER_HIGH_RISK_SHARE,\n    LAYER_LONG_TERM_SHARE,\n    RIGID_CAPITAL_WINDOW_YEARS,\n    SURVIVAL_BREACH_DAYS,\n)\n\nLAYER_NAMES = (\n    \"survival\",\n    \"near_term_duty\",\n    \"protection\",\n    \"long_term_growth\",\n    \"high_risk_opportunity\",\n)\n\n_DEFENSIVE_ORDER = (\"survival\", \"near_term_duty\", \"protection\")\n\n#: 单一来源：刚性支出的两种归属（T-E0-045 / H-04）。窗口内 = 必须立刻隔离；\n#: 窗口外 = 长期刚性责任，由长期资金承担，但必须在到期月份进入月度投影。\nRIGID_WITHIN_WINDOW = \"within_window\"\nRIGID_BEYOND_WINDOW = \"beyond_window\"\n\n\ndef _number(value, default=0.0):\n    if isinstance(value, bool) or value is None:\n        return default\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return default\n    if number != number or number in (float(\"inf\"), float(\"-inf\")):\n        return default\n    return number\n\n\ndef _total_assets(profile):\n    total = 0.0\n    for asset in profile.get(\"assets\") or []:\n        if isinstance(asset, dict):\n            value = _number(asset.get(\"value\"), 0.0)\n            if value > 0:\n                total += value\n    return total\n\n\ndef _survival_need(profile):\n    target_days = _number(profile.get(\"survival_target_days\"), DEFAULT_SURVIVAL_TARGET_DAYS)\n    if target_days <= 0:\n        target_days = DEFAULT_SURVIVAL_TARGET_DAYS\n    essential = _number(profile.get(\"annual_expenses_essential\"), 0.0)\n    return essential / 365.0 * target_days\n\n\ndef classify_rigid_outflow(outflow):\n    \"\"\"单一来源：一笔已记录刚性支出属于窗口内必须隔离，还是窗口外长期刚性责任。\n\n    到期年限缺失时只能按「未证明是近端」处理（beyond_window），绝不用 5 年或 0\n    去静默顶替 —— 这条规则同时被分层、保障缺口与年度目标引用，不允许各写一套。\n    \"\"\"\n    if not isinstance(outflow, dict):\n        return None\n    amount = _number(outflow.get(\"amount\"), 0.0)\n    if amount <= 0:\n        return None\n    years = _number(outflow.get(\"years_until_due\"), None)\n    if years is None:\n        return RIGID_BEYOND_WINDOW\n    return RIGID_WITHIN_WINDOW if years <= RIGID_CAPITAL_WINDOW_YEARS else RIGID_BEYOND_WINDOW\n\n\ndef rigid_outflow_split(profile):\n    \"\"\"全部已记录刚性支出的唯一分类出口（T-E0-045 / H-04 / H-06）。\n\n    返回窗口内（必须立刻隔离）与窗口外（长期刚性责任，由长期资金承担，但必须在\n    到期月份进入月度投影）两组，以及分组金额、窗口年限与无法排期的条目。\n    \"\"\"\n    if not isinstance(profile, dict):\n        profile = {}\n    within = []\n    beyond = []\n    unscheduled = []\n    for outflow in profile.get(\"future_rigid_outflows\") or []:\n        bucket = classify_rigid_outflow(outflow)\n        if bucket is None:\n            continue\n        years = _number(outflow.get(\"years_until_due\"), None)\n        item = {\n            \"outflow_id\": outflow.get(\"outflow_id\"),\n            \"label\": outflow.get(\"label\") or outflow.get(\"outflow_id\"),\n            \"amount\": _number(outflow.get(\"amount\"), 0.0),\n            \"years_until_due\": None if years is None else round(years, 2),\n            \"bucket\": bucket,\n        }\n        (within if bucket == RIGID_WITHIN_WINDOW else beyond).append(item)\n        if years is None:\n            unscheduled.append(item)\n    return {\n        \"within_window\": within,\n        \"beyond_window\": beyond,\n        \"within_window_total\": sum(item[\"amount\"] for item in within),\n        \"beyond_window_total\": sum(item[\"amount\"] for item in beyond),\n        \"window_years\": RIGID_CAPITAL_WINDOW_YEARS,\n        \"unscheduled\": unscheduled,\n    }\n\n\ndef rigid_outflow_schedule(profile, horizon_months):\n    \"\"\"刚性支出的唯一排期出口：到期月份 + 金额（H-06）。\n\n    两个月度投影模块（trend / timeline）只能引用这一处排期，禁止各自再读一次\n    ``future_rigid_outflows``。到期年限缺失的条目不能猜月份，只记入 unscheduled。\n    \"\"\"\n    months = int(_number(horizon_months, 0) or 0)\n    schedule = []\n    for bucket in (\"within_window\", \"beyond_window\"):\n        for item in rigid_outflow_split(profile)[bucket]:\n            years = item[\"years_until_due\"]\n            if years is None:\n                continue\n            month = int(round(years * 12))\n            if month < 1:\n                month = 1\n            if months and month > months:\n                continue\n            schedule.append({\"month\": month, **item})\n    schedule.sort(key=lambda row: (row[\"month\"], row[\"outflow_id\"] or \"\"))\n    return schedule\n\n\ndef rigid_outflow_due_by_month(profile, horizon_months):\n    \"\"\"Convenience map ``{month: amount}`` built from the single schedule.\"\"\"\n    due = {}\n    for item in rigid_outflow_schedule(profile, horizon_months):\n        due[item[\"month\"]] = round(due.get(item[\"month\"], 0.0) + item[\"amount\"], 2)\n    return due\n\n\ndef near_term_rigid_need(profile):\n    \"\"\"Window-only rigid need — the single ruler the layering policy isolates today.\"\"\"\n    return rigid_outflow_split(profile)[\"within_window_total\"]\n\n\ndef survival_buffer_days(cash, annual_essential):\n    \"\"\"单一来源：可动用现金覆盖必要支出的天数 —— **不含任何未来收入**。\n\n    这是 ``engine.safety.safety_days`` 的定义本身（``liquid / (essential / 365)``）。\n    击穿判定只允许比较这个量；把「继续到账的收入」算进可支撑天数的量\n    （``trend.monthly[].runway_days``）只用于展示，绝不能拿来和生存底线比较。\n    \"\"\"\n    cash_value = _number(cash, 0.0)\n    essential = _number(annual_essential, 0.0)\n    daily = essential / 365.0\n    if daily <= 0:\n        return None\n    return max(0.0, cash_value) / daily\n\n\ndef is_survival_breach(buffer_days):\n    \"\"\"单一来源击穿判定（T-E0-045 / H-05）。\n\n    只接受 ``survival_buffer_days`` 算出的「不含未来收入」的现金覆盖天数：\n    低于 ``SURVIVAL_BREACH_DAYS`` 即视为击穿。天数无法计算时返回 ``None``\n    （不判定击穿，也不输出「安全」的确定结论）。含收入的 runway 不适用于本判定。\n    \"\"\"\n    days = _number(buffer_days, None)\n    if days is None:\n        return None\n    return days < SURVIVAL_BREACH_DAYS\n\n\ndef is_survival_breach_on_income_runway(runway_days):\n    \"\"\"仅供审计对照：含未来收入的 runway 与生存底线的比较结果。\n\n    这不是击穿判定（income 会抬高天数，掩盖真实的现金缺口），历史结果里若出现\n    ``BREACH_MEASURED_ON_INCOME_RUNWAY`` 即表示用错了量。\n    \"\"\"\n    days = _number(runway_days, None)\n    if days is None:\n        return None\n    return days < SURVIVAL_BREACH_DAYS\n\n    \"\"\"单一来源击穿判定（T-E0-045 / H-05）。\n\n    可动用现金能覆盖的生存天数低于 ``SURVIVAL_BREACH_DAYS`` 即视为击穿。\n    天数未记录（无法计算）时不判定为击穿，但也绝不返回「安全」的确定结论 ——\n    调用方必须把它当作证据缺口单独呈现。\n    \"\"\"\n    days = _number(runway_days, None)\n    if days is None:\n        return None\n    return days < SURVIVAL_BREACH_DAYS\n\n\ndef _near_term_duty_need(profile):\n    \"\"\"Rigid outflows inside the near-term window plus one year of mandatory debt service.\"\"\"\n    need = near_term_rigid_need(profile)\n    for liability in profile.get(\"liabilities\") or []:\n        if isinstance(liability, dict):\n            need += _number(liability.get(\"mandatory_payment\"), 0.0)\n    return need\n\n\ndef _protection_need(profile):\n    \"\"\"One year of premiums already in force is reserved before growth is funded.\"\"\"\n    need = 0.0\n    for policy in profile.get(\"protection\") or []:\n        if isinstance(policy, dict):\n            need += _number(policy.get(\"annual_premium\"), 0.0)\n    return need\n\n\ndef layer_funds(profile):\n    \"\"\"Split family money into the five E0 layers.\"\"\"\n    if not isinstance(profile, dict):\n        profile = {}\n\n    total_assets = _total_assets(profile)\n    needs = {\n        \"survival\": _survival_need(profile),\n        \"near_term_duty\": _near_term_duty_need(profile),\n        \"protection\": _protection_need(profile),\n    }\n\n    amounts = {name: 0.0 for name in LAYER_NAMES}\n    remaining = total_assets\n\n    for name in _DEFENSIVE_ORDER:\n        if remaining <= 0:\n            break\n        take = min(needs[name], remaining)\n        amounts[name] = take\n        remaining -= take\n\n    if remaining > 0:\n        amounts[\"long_term_growth\"] = remaining * LAYER_LONG_TERM_SHARE\n        amounts[\"high_risk_opportunity\"] = remaining * LAYER_HIGH_RISK_SHARE\n\n    leftover = total_assets - sum(amounts.values())\n    if abs(leftover) > 1e-9:\n        amounts[\"long_term_growth\"] += leftover\n\n    fractions = {}\n    for name in LAYER_NAMES:\n        fractions[name] = (amounts[name] / total_assets) if total_assets > 0 else 0.0\n\n    shortfall = {\n        name: max(0.0, needs[name] - amounts[name]) for name in _DEFENSIVE_ORDER\n    }\n    funded = all(shortfall[name] <= 1e-9 for name in _DEFENSIVE_ORDER)\n    deficit = sum(shortfall.values())\n    growth_fraction = fractions[\"long_term_growth\"] + fractions[\"high_risk_opportunity\"]\n\n    if total_assets <= 0:\n        funding_status = \"NO_ASSETS\"\n    elif not funded:\n        funding_status = \"DEFICIT\"\n    elif growth_fraction <= 0:\n        funding_status = \"SURVIVAL_ONLY\"\n    else:\n        funding_status = \"FUNDED\"\n\n    warnings = []\n    if funding_status == \"DEFICIT\":\n        warnings.append(\n            \"Recorded assets do not cover survival, near-term duty and protection needs.\"\n        )\n    if growth_fraction <= 0 and total_assets > 0:\n        warnings.append(\"No residual capital is available for long-term growth.\")\n\n    rigid_split = rigid_outflow_split(profile)\n\n    return {\n        \"layers\": amounts,\n        \"fractions\": fractions,\n        \"needs\": needs,\n        \"rigid_split\": rigid_split,\n        \"shortfall\": shortfall,\n        \"total_assets\": total_assets,\n        \"deficit\": deficit,\n        \"fully_funded\": funded,\n        \"funding_status\": funding_status,\n        \"growth_fraction\": growth_fraction,\n        \"warnings\": warnings,\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": (\n                \"priority-ordered allocation: survival, then near-term rigid duty, then \"\n                \"protection, then residual split between long-term growth and a high-risk sleeve\"\n            ),\n            \"assumptions\": [\n                f\"Survival is funded for the stated survival target (default {DEFAULT_SURVIVAL_TARGET_DAYS} days).\",\n                (\n                    f\"Rigid outflows due within {RIGID_CAPITAL_WINDOW_YEARS} years are \"\n                    \"isolated today; later rigid obligations are long-horizon duties \"\n                    \"funded by long-term capital and deducted in the month they fall due.\"\n                ),\n                \"One year of in-force protection premiums is reserved before growth.\",\n                f\"Residual capital is split {LAYER_LONG_TERM_SHARE:.0%} growth / {LAYER_HIGH_RISK_SHARE:.0%} high risk.\",\n            ],\n            \"computed_at_utc\": None,\n            \"sources\": [\"docs/INTERFACE_FREEZE_V0_1.md\"],\n        },\n    }\n", "protection.py": "\"\"\"Integrated protection plan module (综合保护方案).\n\nThe plan spans six domains of household protection:\n\n    cash      — a survivable cash buffer (from the safety engine)\n    insurance — recorded protection against documented needs (insurance audit)\n    assets    — asset structure, untouchable concentration, drawdown vs loss budget\n    debt      — mandatory debt-service pressure\n    legal     — wills, beneficiary designations, guardianship, powers of attorney\n    social    — social insurance, medical insurance, public pension, employment support\n\nFor every domain the plan reports what the family actually records, what is\nmissing, and what to do first — it never names an insurer, a policy, a product,\na lawyer or an advisor. Missing records produce ``NOT_RECORDED`` (evidence is\nnot assumed), never a default judgement. Fail-closed: the plan never raises and\nwhen inputs cannot be interpreted it reports ``ABSTAIN`` instead.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    DEFAULT_SURVIVAL_TARGET_DAYS,\n    PLAN_ACTION_LIMIT,\n    REFUSE_MIN_SURVIVAL_DAYS,\n    REVIEW_DEBT_PRESSURE,\n    REVIEW_SURVIVAL_DAYS,\n    UNDERINVESTED_GROWTH_FRACTION,\n    UNTOUCHABLE_CONCENTRATION_LIMIT,\n)\n\n#: Display order for the six domains of the integrated plan.\nDOMAIN_ORDER = (\"cash\", \"insurance\", \"assets\", \"debt\", \"legal\", \"social\")\nDOMAIN_LABELS = {\n    \"cash\": \"现金缓冲\",\n    \"insurance\": \"保险保障\",\n    \"assets\": \"资产结构\",\n    \"debt\": \"债务压力\",\n    \"legal\": \"法律安排\",\n    \"social\": \"社会保障\",\n}\n\nPRIORITY_ORDER = (\"P0\", \"P1\", \"P2\")\nPRIORITY_CN = {\"P0\": \"紧急\", \"P1\": \"重要\", \"P2\": \"按计划\"}\n\nLEGAL_KINDS = (\n    (\"will\", \"遗嘱\"),\n    (\"beneficiary_designation\", \"受益人指定\"),\n    (\"guardianship\", \"子女监护安排\"),\n    (\"power_of_attorney\", \"授权委托/持久授权书\"),\n)\n\nSOCIAL_KINDS = (\n    (\"social_insurance\", \"基本社会保险缴费\"),\n    (\"medical_insurance\", \"基本/补充医疗保险\"),\n    (\"public_pension\", \"基本养老金记录\"),\n    (\"employment_support\", \"失业与就业援助\"),\n)\n\n\ndef _number(value):\n    if isinstance(value, bool) or value is None:\n        return None\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return None\n    if number != number or number in (float(\"inf\"), float(\"-inf\")):\n        return None\n    return number\n\n\ndef _money(value):\n    number = _number(value)\n    return None if number is None else round(number, 2)\n\n\ndef _domain(domain, status, finding, actions=None, detail=None):\n    return {\n        \"domain\": domain,\n        \"label_cn\": DOMAIN_LABELS.get(domain, domain),\n        \"status\": status,\n        \"finding\": finding,\n        \"detail\": detail or {},\n        \"actions\": list(actions or []),\n    }\n\n\ndef _action(priority, domain, action_cn, rationale, cost_estimate=None):\n    return {\n        \"priority\": priority,\n        \"domain\": domain,\n        \"domain_label\": DOMAIN_LABELS.get(domain, domain),\n        \"action_cn\": action_cn,\n        \"rationale\": rationale,\n        \"cost_estimate\": _money(cost_estimate),\n    }\n\n\ndef _abstain(reason):\n    return {\n        \"status\": \"ABSTAIN\",\n        \"status_reason\": reason,\n        \"domains\": {},\n        \"domain_order\": list(DOMAIN_ORDER),\n        \"priority_actions\": [],\n        \"notice\": (\n            \"Integrated protection plan abstained: evidence is insufficient. \"\n            \"Verity never assumes what the family has not recorded.\"\n        ),\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": \"Integrated protection plan abstained without sufficient household evidence.\",\n            \"assumptions\": [],\n            \"sources\": [],\n            \"computed_at_utc\": None,\n        },\n    }\n\n\n# ---------------------------------------------------------------------- domains\ndef _build_cash(safety):\n    days = _number(safety.get(\"safety_days\")) if isinstance(safety, dict) else None\n    cash_gap = _number(safety.get(\"cash_gap\")) if isinstance(safety, dict) else None\n    floor = _money(safety.get(\"survival_floor_value\")) if isinstance(safety, dict) else None\n    target = _number(safety.get(\"survival_target_days\")) or DEFAULT_SURVIVAL_TARGET_DAYS\n    detail = {\n        \"safety_days\": days,\n        \"cash_gap\": cash_gap,\n        \"survival_floor_value\": floor,\n        \"survival_target_days\": target,\n    }\n    if days is None or cash_gap is None:\n        return _domain(\"cash\", \"ABSTAIN\", \"现金缓冲证据不足，无法评估。\", detail=detail)\n    if cash_gap > 0:\n        return _domain(\n            \"cash\", \"GAP\",\n            f\"存在现金缺口 {_money(cash_gap):,.0f}；应急金目标未完全覆盖。\",\n            [_action(\"P0\", \"cash\", \"补足应急金目标现金缺口\", \"现金缺口意味着家庭在收入中断时难以维持应急金目标，必须先于任何投资计划弥补。\", cash_gap)],\n            detail,\n        )\n    if days < REFUSE_MIN_SURVIVAL_DAYS:\n        return _domain(\n            \"cash\", \"GAP\",\n            f\"安全天数仅 {days:,.0f} 天，低于 {REFUSE_MIN_SURVIVAL_DAYS:,.0f} 天生存底线。\",\n            [_action(\"P0\", \"cash\", \"立即补充流动资产至应急金目标\", \"安全天数低于硬底线，任何风险冲击都可能击穿家庭。\", floor)],\n            detail,\n        )\n    if days < REVIEW_SURVIVAL_DAYS:\n        return _domain(\n            \"cash\", \"GAP\",\n            f\"安全天数 {days:,.0f} 天，低于复核阈值 {REVIEW_SURVIVAL_DAYS:,.0f} 天；建议先加厚缓冲。\",\n            [_action(\"P1\", \"cash\", \"加厚现金缓冲至目标天数\", \"安全天数在复核区间内，先提高缓冲再谈长期配置。\")],\n            detail,\n        )\n    return _domain(\n        \"cash\", \"SECURED\",\n        f\"安全天数 {days:,.0f} 天，现金缺口为零，应急金目标已覆盖。\",\n        detail=detail,\n    )\n\n\ndef _build_insurance(insurance):\n    if not isinstance(insurance, dict) or not insurance:\n        return _domain(\"insurance\", \"ABSTAIN\", \"保险审计未返回结果，保障状态无法评估。\")\n    status = insurance.get(\"status\")\n    caps = insurance.get(\"capabilities\") or {}\n    order = insurance.get(\"capability_order\") or []\n    actions = []\n    for capability in order:\n        cap = caps.get(capability) or {}\n        gap = _number(cap.get(\"gap\")) or 0.0\n        label = cap.get(\"label_cn\") or capability\n        if gap > 0:\n            priority = \"P0\" if capability in (\"life\", \"disability\") else \"P1\"\n            actions.append(\n                _action(\n                    priority, \"insurance\",\n                    f\"补齐{label}缺口\",\n                    f\"被记录保障低于测算需求（缺口 {_money(gap):,.0f}）。覆盖缺口清单见保险审计。\",\n                    gap,\n                )\n            )\n    burden = insurance.get(\"premium_burden_status\")\n    if burden == \"HIGH\":\n        actions.append(\n            _action(\n                \"P1\", \"insurance\",\n                \"评估保费负担占收入比例\",\n                \"保费负担相对收入处于高区间，需要与保障缺口一起平衡，避免以负担换覆盖。\",\n            )\n        )\n    if status == \"ABSTAIN\":\n        return _domain(\n            \"insurance\", \"ABSTAIN\",\n            \"保险审计证据不足，主动弃权（不假设任何保障状态）。\",\n            detail={\"status\": status, \"coverage_score\": insurance.get(\"coverage_score\")},\n        )\n    domain_status = \"GAP\" if status == \"GAPS\" else \"SECURED\" if status == \"OK\" else \"REVIEW\"\n    finding = (\n        \"被记录的保障覆盖全部测算需求。\"\n        if status == \"OK\"\n        else \"被记录的保障存在缺口；缺口按保障能力逐一列出。\"\n        if status == \"GAPS\"\n        else f\"保险审计状态未知（{status}），按复核处理。\"\n    )\n    detail = {\n        \"status\": status,\n        \"coverage_score\": insurance.get(\"coverage_score\"),\n        \"premium_to_income\": insurance.get(\"premium_to_income\"),\n        \"premium_burden_status\": burden,\n        \"capability_count\": len(order),\n    }\n    return _domain(\"insurance\", domain_status, finding, actions, detail)\n\n\ndef _build_assets(profile, safety, layers, allocation):\n    total = _number(safety.get(\"total_assets\")) if isinstance(safety, dict) else None\n    untouchable = _number(safety.get(\"untouchable_assets\")) if isinstance(safety, dict) else None\n    growth = _number(layers.get(\"growth_fraction\")) if isinstance(layers, dict) else None\n    drawdown = _number(allocation.get(\"simulated_max_drawdown\")) if isinstance(allocation, dict) else None\n    loss = _number(profile.get(\"max_tolerable_loss_pct\"))\n    if total is None:\n        return _domain(\"assets\", \"ABSTAIN\", \"资产结构证据不足，无法评估。\")\n    concentration = (untouchable or 0.0) / total if total > 0 else 0.0\n    actions = []\n    status = \"SECURED\"\n    if concentration > UNTOUCHABLE_CONCENTRATION_LIMIT:\n        status = \"REVIEW\"\n        actions.append(\n            _action(\n                \"P1\", \"assets\",\n                \"降低不可动用资产占比\",\n                f\"不可动用资产占 {concentration:.0%}，超过 {UNTOUCHABLE_CONCENTRATION_LIMIT:.0%} 参考上限；危机中可用资源太少。\",\n            )\n        )\n    if growth is not None and growth < UNDERINVESTED_GROWTH_FRACTION:\n        status = \"REVIEW\"\n        actions.append(\n            _action(\n                \"P1\", \"assets\",\n                \"逐步提高长期增长配置\",\n                \"增长份额低于参考下限，长期目标可能缺少增长引擎；按政策配置逐步再平衡。\",\n            )\n        )\n    if drawdown is not None and loss is not None and abs(drawdown) > loss:\n        status = \"REVIEW\"\n        actions.append(\n            _action(\n                \"P2\", \"assets\",\n                \"重新校准亏损预算或资产配置\",\n                f\"模拟最大回撤 {abs(drawdown):.0%} 超过家庭可承受亏损 {loss:.0%}；需要更保守的组合或更现实的预算。\",\n            )\n        )\n    finding = (\n        \"资产结构在参考范围内，无集中度或回撤预警。\"\n        if status == \"SECURED\"\n        else \"资产结构存在复核项；详见行动列表。\"\n    )\n    detail = {\n        \"untouchable_assets\": untouchable,\n        \"total_assets\": total,\n        \"untouchable_concentration\": round(concentration, 4),\n        \"growth_fraction\": growth,\n        \"simulated_max_drawdown\": drawdown,\n        \"max_tolerable_loss_pct\": loss,\n    }\n    return _domain(\"assets\", status, finding, actions, detail)\n\n\ndef _build_debt(safety):\n    ratio = _number(safety.get(\"debt_pressure_ratio\")) if isinstance(safety, dict) else None\n    detail = {\"debt_pressure_ratio\": ratio, \"review_threshold\": REVIEW_DEBT_PRESSURE}\n    if ratio is None:\n        return _domain(\"debt\", \"ABSTAIN\", \"债务压力证据不足，无法评估。\", detail=detail)\n    if ratio > REVIEW_DEBT_PRESSURE:\n        return _domain(\n            \"debt\", \"GAP\",\n            f\"强制性债务偿付占收入 {ratio:.1%}，超过 {REVIEW_DEBT_PRESSURE:.0%} 复核阈值。\",\n            [_action(\"P0\", \"debt\", \"降低强制性债务偿付占比\", \"债务偿付挤占生存与保护资源；优先重组或提前偿还高成本债务。\")],\n            detail,\n        )\n    return _domain(\n        \"debt\", \"SECURED\",\n        f\"强制性债务偿付占收入 {ratio:.1%}，低于 {REVIEW_DEBT_PRESSURE:.0%} 参考线。\",\n        detail=detail,\n    )\n\n\ndef _normalize_records(records, kinds):\n    \"\"\"Return {kind: recorded} plus the raw note, or None when the format is unusable.\"\"\"\n    if isinstance(records, dict):\n        out = {}\n        for kind, _label in kinds:\n            item = records.get(kind)\n            if isinstance(item, dict):\n                out[kind] = bool(item.get(\"recorded\"))\n            elif isinstance(item, bool):\n                out[kind] = item\n            else:\n                out[kind] = False\n        return out\n    if isinstance(records, list):\n        out = {kind: False for kind, _label in kinds}\n        for item in records:\n            if not isinstance(item, dict):\n                continue\n            kind = item.get(\"kind\")\n            if kind in out:\n                out[kind] = bool(item.get(\"recorded\"))\n        return out\n    return None\n\n\ndef _build_records(domain, profile, key, kinds, label_cn):\n    records = profile.get(key)\n    raw = _normalize_records(records, kinds)\n    if records is None:\n        return _domain(\n            domain, \"NOT_RECORDED\",\n            f\"未记录任何{label_cn}安排；{label_cn}状态无法评估（证据不足，不作假设）。\",\n            [_action(\"P2\", domain, f\"记录{label_cn}安排并纳入家庭档案\", \"缺失记录不等于没有问题；补齐后才能评估该领域。\")],\n            {\"recorded_count\": 0, \"total\": len(kinds)},\n        )\n    if raw is None:\n        return _domain(domain, \"ABSTAIN\", f\"{label_cn}记录格式无法识别，无法评估。\")\n    missing = [label for kind, label in kinds if not raw.get(kind)]\n    recorded_count = sum(1 for kind, _label in kinds if raw.get(kind))\n    detail = {\n        \"recorded_count\": recorded_count,\n        \"total\": len(kinds),\n        \"kinds\": {kind: {\"label_cn\": label, \"recorded\": bool(raw.get(kind))} for kind, label in kinds},\n    }\n    if not missing:\n        return _domain(\n            domain, \"SECURED\",\n            f\"{label_cn}记录完整（{recorded_count}/{len(kinds)}），无需补录。\",\n            detail=detail,\n        )\n    actions = [\n        _action(\n            \"P1\" if recorded_count > 0 else \"P2\", domain,\n            f\"补齐{label_cn}记录：{'、'.join(missing)}\",\n            f\"已记录 {recorded_count}/{len(kinds)} 项，仍有 {len(missing)} 项缺失；补齐后才能确认该领域安全。\",\n        )\n    ]\n    return _domain(\n        domain, \"GAP\",\n        f\"{label_cn}记录不完整（{recorded_count}/{len(kinds)}）：{'、'.join(missing)}。\",\n        actions,\n        detail,\n    )\n\n\ndef _overall_status(domains):\n    statuses = [dom.get(\"status\") for dom in domains.values()]\n    if \"ABSTAIN\" in statuses:\n        return \"ABSTAIN\", \"部分保护领域证据不足，方案整体弃权：不假设、不猜测。\"\n    if \"GAP\" in statuses:\n        return \"GAPS\", \"综合保护方案存在缺口；按优先级行动，先解决生存相关缺口。\"\n    if \"NOT_RECORDED\" in statuses:\n        return \"NOT_RECORDED\", \"部分保护领域尚未记录；补齐记录后可给出全面评估。\"\n    if \"REVIEW\" in statuses:\n        return \"REVIEW\", \"综合保护方案无硬缺口，但存在需复核的项目；见各领域行动。\"\n    return \"SECURED\", \"六个保护领域均已得到记录或覆盖。\"\n\n\ndef build_protection_plan(profile, *, safety=None, insurance=None, layers=None, allocation=None):\n    \"\"\"Build the integrated six-domain protection plan.\n\n    Fail-closed: never raises. When required engine output is missing the whole\n    plan reports ``ABSTAIN`` and individual domains explain why.\n    \"\"\"\n    profile = profile if isinstance(profile, dict) else {}\n    safety = safety if isinstance(safety, dict) else {}\n    insurance = insurance if isinstance(insurance, dict) else {}\n    layers = layers if isinstance(layers, dict) else {}\n    allocation = allocation if isinstance(allocation, dict) else {}\n\n    evidence = {\n        \"algorithm_version\": ALGORITHM_VERSION,\n        \"method\": (\n            \"Integrated six-domain protection plan: cash buffer from the safety engine, \"\n            \"insurance audit against documented needs, asset structure and loss budget, \"\n            \"mandatory debt service pressure, and recorded legal and social-security \"\n            \"arrangements. Missing records are reported as NOT_RECORDED, never assumed. \"\n            \"No insurer, policy, product, lawyer or advisor is named or recommended.\"\n        ),\n        \"assumptions\": [\n            \"Cash domain uses the safety engine's liquidity and survival-floor arithmetic.\",\n            \"Insurance domain mirrors the insurance-audit gaps (10x income, 0.5x income, medical event, liability).\",\n            \"Assets domain flags untouchable concentration above 60% and growth fraction below the frozen reference.\",\n            \"Debt domain flags mandatory debt service above the frozen 35% review threshold.\",\n            \"Legal and social domains only reflect what the family records; absence is NOT_RECORDED, not zero risk.\",\n            \"Priorities are P0 (survival/life-critical) > P1 (important) > P2 (planned); the plan lists at most \"\n            f\"{PLAN_ACTION_LIMIT} actions per run.\",\n        ],\n        \"sources\": [\"docs/INTERFACE_FREEZE_V0_1.md\", \"data/synthetic/households.json\"],\n        \"computed_at_utc\": None,\n    }\n\n    try:\n        domains = {\n            \"cash\": _build_cash(safety),\n            \"insurance\": _build_insurance(insurance),\n            \"assets\": _build_assets(profile, safety, layers, allocation),\n            \"debt\": _build_debt(safety),\n            \"legal\": _build_records(\"legal\", profile, \"legal_affairs\", LEGAL_KINDS, \"法律\"),\n            \"social\": _build_records(\"social\", profile, \"social_protection\", SOCIAL_KINDS, \"社会保障\"),\n        }\n    except Exception:  # noqa: BLE001 - fail closed, never raise\n        return _abstain(\"Integrated protection plan could not interpret the household evidence.\")\n\n    status, status_reason = _overall_status(domains)\n\n    actions = []\n    for domain_name in DOMAIN_ORDER:\n        for action in domains[domain_name].get(\"actions\") or []:\n            actions.append(action)\n    actions.sort(key=lambda action: (PRIORITY_ORDER.index(action.get(\"priority\", \"P2\")),\n                                     DOMAIN_ORDER.index(action.get(\"domain\", \"cash\"))))\n    actions = actions[:PLAN_ACTION_LIMIT]\n\n    return {\n        \"status\": status,\n        \"status_reason\": status_reason,\n        \"domains\": domains,\n        \"domain_order\": list(DOMAIN_ORDER),\n        \"priority_actions\": actions,\n        \"notice\": (\n            \"综合保护方案横跨现金、保险、资产、债务、法律与社会保障六个领域；\"\n            \"系统不推荐任何具体产品、机构或律师，只报告被记录的事实、缺口与先后顺序。\"\n        ),\n        \"evidence\": evidence,\n    }\n", "report.py": "\"\"\"Family wealth diagnosis report renderer (家庭财务体检报告 · HTML 自包含)。\n\nThis module is the *single* implementation of the Chinese diagnosis report.\nIt lives in ``engine/`` so the exact same code that prints the offline/shareable\nreport also runs:\n\n  * on the backend (``scripts/generate_diagnosis_report.py`` batch mode), and\n  * inside the browser (``web/zh.js`` runs ``engine.report`` through Pyodide),\n\nso a report exported from the console is byte-for-byte the same document the\nengine's own tooling would render for the same result payload. The page makes no\nnetwork requests and carries the explicit safety banner; it is only a decision\nsupport artifact, never an advice or trade execution document.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport html\nfrom datetime import datetime, timezone\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    PRODUCTION_AUTHORITY,\n    RELEASE_GATE,\n    RIGID_CAPITAL_WINDOW_YEARS,\n)\nfrom engine.evidence import verify_audit_chain\nfrom engine.zh_i18n import (\n    evidence_item_cn,\n    feasibility_reason_cn,\n    insurance_warning_cn,\n    protection_reason_cn,\n    risk_notice_cn,\n    risk_ranking_cn,\n    safety_risk_cn,\n    status_reason_cn,\n    today_reason_cn,\n    verdict_meaning_cn,\n)\n\n\ndef audit_ok_for(result) -> bool:\n    \"\"\"Fail-closed audit-chain check for a single engine result payload.\"\"\"\n    try:\n        record = result.get(\"audit\")\n        if not isinstance(record, dict):\n            return False\n        return bool(verify_audit_chain([record])[0])\n    except Exception:  # noqa: BLE001 - display-oriented, fail closed\n        return False\n\n\ndef report_html(result) -> str:\n    \"\"\"Render the full self-contained HTML report for one engine result.\"\"\"\n    return render_report(result, audit_ok_for(result))\n\n\nVERDICT_CN = {\n    \"PASS\": \"通过\",\n    \"REVIEW\": \"复核\",\n    \"REFUSE\": \"拒绝\",\n    \"ABSTAIN\": \"弃权\",\n}\n\nLAYER_CN = [\n    (\"survival\", \"生存底线\"),\n    (\"near_term_duty\", \"近期责任\"),\n    (\"protection\", \"风险保护\"),\n    (\"long_term_growth\", \"长期增长\"),\n    (\"high_risk_opportunity\", \"高风险机会\"),\n]\n\nFUNDING_CN = {\"FUNDED\": \"资金充足\", \"DEFICIT\": \"资金缺口\", \"PARTIAL\": \"部分覆盖\"}\n\nSCENARIO_CN = {\n    \"income_interruption\": \"收入中断\",\n    \"equity_crash\": \"股市急跌\",\n    \"rate_change\": \"利率变动\",\n    \"medical_shock\": \"重大医疗冲击\",\n    \"fx_change\": \"汇率冲击\",\n    \"inflation_spiral\": \"通胀螺旋（成本上涨＋债务重定价）\",\n    \"income_concentration\": \"单一收入来源中断 12 个月\",\n    \"combined_multi_risk\": \"多重风险叠加\",\n}\n\nSEVERITY_CN = {\"low\": \"低\", \"medium\": \"中\", \"high\": \"高\", \"critical\": \"严重\"}\n\nRISK_CN = {\"low\": \"低\", \"medium\": \"中\", \"high\": \"高\", \"critical\": \"严重\"}\n\nASSET_CN = {\n    \"cash\": \"现金\",\n    \"bond\": \"债券\",\n    \"global_index\": \"全球指数\",\n    \"equity\": \"股票\",\n    \"gold\": \"黄金\",\n    \"option_protection\": \"期权保护\",\n    \"property\": \"房产\",\n    \"insurance\": \"保险\",\n    \"other\": \"其他\",\n}\n\n\ndef esc(value):\n    return html.escape(str(value))\n\n\ndef money(value):\n    if value is None:\n        return \"—\"\n    return f\"{value:,.0f}\"\n\n\ndef pct(value, digits=1):\n    if value is None:\n        return \"—\"\n    return f\"{value * 100:.{digits}f}%\"\n\n\ndef bar(fraction, css_class):\n    width = max(0.0, min(1.0, fraction or 0.0)) * 100\n    return f'<div class=\"bar\"><i class=\"{css_class}\" style=\"width:{width:.2f}%\"></i></div>'\n\n\nCSS = \"\"\"\n:root{--bg:#f6f5f1;--card:#ffffff;--ink:#1f2430;--muted:#67707f;--line:#e7e4dc;\n--ok:#1e7d4b;--warn:#b26a00;--bad:#b3261e;--info:#3556b3}\n*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);\nfont-family:-apple-system,\"PingFang SC\",\"Microsoft YaHei\",\"Noto Sans CJK SC\",sans-serif;line-height:1.65}\n.wrap{max-width:900px;margin:0 auto;padding:28px 18px 60px}\n.banner{background:#10243e;color:#fff;padding:14px 18px;border-radius:8px;margin-bottom:22px;font-size:13px}\n.banner b{display:inline-block;background:#c9a227;color:#10243e;border-radius:4px;padding:1px 8px;margin-right:6px}\nh1{font-size:24px;margin:4px 0 4px}h2{font-size:17px;margin:0 0 12px;color:#10243e}\nh3{font-size:14px;margin:12px 0 6px;color:#10243e}.sub{color:var(--muted);font-size:13px;margin-bottom:14px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:20px 22px;margin-bottom:16px}\n.verdict{display:inline-block;font-weight:700;padding:6px 16px;border-radius:18px;font-size:15px}\n.v-PASS{background:#e3f2e8;color:var(--ok)}.v-REVIEW{background:#fff3df;color:var(--warn)}\n.v-REFUSE{background:#fde7e5;color:var(--bad)}.v-ABSTAIN{background:#e8ebf2;color:var(--info)}\n.pill{display:inline-block;background:#eef0f4;color:#3b4356;border-radius:20px;padding:2px 10px;font-size:12px;margin:2px 4px 2px 0}\n.pill.ok{background:#e3f2e8;color:var(--ok)}.pill.bad{background:#fde7e5;color:var(--bad)}\n.grid{display:grid;gap:10px}.c3{grid-template-columns:repeat(3,1fr)}.c2{grid-template-columns:repeat(2,1fr)}\n.metric{background:#faf9f6;border:1px solid var(--line);border-radius:8px;padding:10px 12px}\n.metric .k{font-size:12px;color:var(--muted)}.metric .v{font-size:19px;font-weight:700;margin:2px 0}\n.metric .v.neg{color:var(--bad)}.metric .v.pos{color:var(--ok)}.metric .h{font-size:11px;color:var(--muted)}\ntable{width:100%;border-collapse:collapse;font-size:13px;margin-top:8px}\nth,td{text-align:left;padding:7px 10px;border-bottom:1px solid var(--line)}\nth{color:var(--muted);font-weight:600;font-size:12px}\ntd.num,th.num{text-align:right;font-variant-numeric:tabular-nums}\n.bar{background:#eceef2;border-radius:4px;height:8px;overflow:hidden;min-width:60px}\n.bar i{display:block;height:100%;border-radius:4px}\n.bar i.survival{background:#1e7d4b}.bar i.duty{background:#3556b3}.bar i.prot{background:#b26a00}\n.bar i.index{background:#8a6bbd}.bar i.equity{background:#b3261e}\n.sev-high,.sev-critical{color:var(--bad);font-weight:600}.sev-medium{color:var(--warn)}\n.layer-row{display:grid;grid-template-columns:150px 1fr 190px;gap:12px;align-items:center;padding:7px 0;font-size:13px}\n.note{background:#f4f1ea;border-left:3px solid #c9a227;padding:10px 14px;border-radius:0 6px 6px 0;font-size:13px;color:#5c5340;margin-top:14px}\n.foot{color:var(--muted);font-size:12px;text-align:center;margin-top:26px}\nul{margin:6px 0;padding-left:20px;font-size:13px;color:#3b4356}\n.mono{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:12px}\na{color:var(--info)}\n@media(max-width:640px){.c3,.c2{grid-template-columns:1fr}.layer-row{grid-template-columns:1fr}}\n\"\"\"\n\n\ndef _days_cell(value):\n    \"\"\"未计算的读数显示为「—」，绝不把缺失当成 0 天（T-E0-045 / M-03）。\"\"\"\n    if value is None:\n        return \"—\"\n    try:\n        return f\"{float(value):,.1f}\"\n    except (TypeError, ValueError):\n        return \"—\"\n\n\ndef render_report(result, audit_ok):\n    profile_id = result.get(\"profile_id\", \"unknown\")\n    verdict = result.get(\"verdict\", \"ABSTAIN\")\n    today = result.get(\"today\", {}) or {}\n    layers = result.get(\"layers\", {}) or {}\n    safety = result.get(\"safety\", {}) or {}\n    feasibility = result.get(\"feasibility\", {}) or {}\n    allocation = result.get(\"allocation\", {}) or {}\n    stress = result.get(\"stress\", {}) or {}\n    evidence = result.get(\"evidence\", {}) or {}\n    risk_notice = result.get(\"risk_notice\", \"\")\n\n    parts = []\n    parts.append('<!DOCTYPE html><html lang=\"zh-CN\"><head><meta charset=\"utf-8\">')\n    parts.append('<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">')\n    parts.append(\n        '<meta http-equiv=\"Content-Security-Policy\" '\n        \"content=\\\"object-src 'none'; base-uri 'self'; form-action 'self'\\\">\"\n    )\n    parts.append(f\"<title>家庭财富诊断报告 · {esc(profile_id)}</title>\")\n    parts.append(f\"<style>{CSS}</style></head><body><div class=\\\"wrap\\\">\")\n\n    # Safety banner\n    parts.append(\n        '<div class=\"banner\"><b>NO PRODUCTION AUTHORITY</b>'\n        \"本报告仅供决策支持，不构成投资、法律、税务或保险建议；\"\n        \"不使用真实客户数据；不推荐任何具体金融产品；不承诺任何收益；不执行任何交易。</div>\"\n    )\n\n    # Header\n    parts.append(f'<h1>家庭财富诊断报告</h1>')\n    parts.append(\n        '<div class=\"sub\">家庭档案 <span class=\"mono\">' + esc(profile_id) + \"</span>\"\n        \" · 运行号 <span class=\\\"mono\\\">\" + esc(result.get(\"run_id\", \"\")) + \"</span>\"\n        f\" · 算法版本 {esc(result.get('algorithm_version', ALGORITHM_VERSION))}\"\n        \" · 权威状态 \" + esc(PRODUCTION_AUTHORITY) + \" · 发布闸门 \" + esc(RELEASE_GATE) + \"</div>\"\n    )\n    verdict_meaning = verdict_meaning_cn(verdict) or feasibility.get(\"verdict_meaning\", \"\")\n    parts.append(\n        f'<div class=\"card\"><div class=\"sub\">总体判断</div>'\n        f'<span class=\"verdict v-{esc(verdict)}\">{esc(VERDICT_CN.get(verdict, verdict))}（{esc(verdict)}）</span>'\n        f'<div class=\"note\" style=\"margin-top:12px\">{esc(verdict_meaning)}</div>'\n        f'<div class=\"sub mono\" style=\"margin-top:6px\">机器码 {esc(today.get(\"action\", \"ABSTAIN\"))}'\n        + (\" · \" + esc(\" · \".join(feasibility.get(\"reason_codes\") or [])) if feasibility.get(\"reason_codes\") else \"\")\n        + \" · 英文原句保留于结果 JSON 与审计记录</div></div>\"\n    )\n\n    # Today\n    parts.append('<div class=\"card\"><h2>今日行动</h2>')\n    parts.append(f'<div class=\"sub\">Verity 每天只给出一个最值得先做的动作；证据不足时选择弃权。</div>')\n    today_meaning_cn, today_reason_cn_text = today_reason_cn(result)\n    parts.append(\n        f'<div style=\"font-size:16px;font-weight:700;margin-bottom:6px\">{esc(today.get(\"action\", \"—\"))}</div>'\n        f'<div class=\"sub\">{esc(today_meaning_cn)}</div>'\n        f'<div class=\"note\">{esc(today_reason_cn_text)}</div>'\n    )\n    parts.append('<div class=\"grid c3\" style=\"margin-top:12px\">')\n    parts.append('<div class=\"metric\"><div class=\"k\">财富总额</div><div class=\"v\">' + money(today.get(\"wealth_value\")) + '</div><div class=\"h\">记录的资产合计</div></div>')\n    parts.append('<div class=\"metric\"><div class=\"k\">安全天数</div><div class=\"v\">' + _days_cell(today.get(\"safety_days\")) + '</div><div class=\"h\">收入停止后可支撑的天数</div></div>')\n    parts.append('<div class=\"metric\"><div class=\"k\">目标达成概率</div><div class=\"v\">' + pct(today.get(\"goal_probability\"), 0) + '</div><div class=\"h\">情景推演值，不是预测</div></div>')\n    parts.append(\"</div></div>\")\n\n    # Layering\n    parts.append('<div class=\"card\"><h2>家庭财富五层结构</h2>')\n    parts.append(\n        '<div class=\"sub\">先保住生存底线，再满足近期责任与保护，最后才轮到长期增长和高风险机会。</div>'\n    )\n    status = layers.get(\"funding_status\", \"UNKNOWN\")\n    parts.append(\n        f'<span class=\"pill {\"ok\" if status == \"FUNDED\" else \"bad\" if status == \"DEFICIT\" else \"\"}\">'\n        f'资金状态：{esc(FUNDING_CN.get(status, status))}</span> '\n        f'<span class=\"pill\">总资产 {money(layers.get(\"total_assets\"))}</span> '\n        f'<span class=\"pill\">增长占比 {pct(layers.get(\"growth_fraction\"))}</span>'\n    )\n    for key, label in LAYER_CN:\n        parts.append(\n            '<div class=\"layer-row\"><div>' + esc(label) + '</div>'\n            + bar(layers.get(\"fractions\", {}).get(key), key)\n            + '<div class=\"num\">' + money(layers.get(\"layers\", {}).get(key))\n            + \" · \" + pct(layers.get(\"fractions\", {}).get(key)) + \"</div></div>\"\n        )\n    parts.append(\"</div>\")\n\n    # Safety\n    parts.append('<div class=\"card\"><h2>生存安全与债务压力</h2>')\n    parts.append('<div class=\"grid c3\">')\n    parts.append('<div class=\"metric\"><div class=\"k\">安全天数</div><div class=\"v\">' + _days_cell(safety.get(\"safety_days\")) + '</div><div class=\"h\">流动资产 / 每日生存支出</div></div>')\n    gap_css = \"neg\" if (safety.get(\"cash_gap\") or 0) > 0 else \"pos\"\n    parts.append('<div class=\"metric\"><div class=\"k\">现金缺口</div><div class=\"v ' + gap_css + '\">' + money(safety.get(\"cash_gap\")) + '</div><div class=\"h\">与应急金目标之间的短欠</div></div>')\n    debt = safety.get(\"debt_pressure_ratio\")\n    debt_txt = \"无法判断\" if debt is None else pct(debt)\n    parts.append('<div class=\"metric\"><div class=\"k\">债务压力</div><div class=\"v\">' + debt_txt + '</div><div class=\"h\">刚性债务 / 收入</div></div>')\n    parts.append(\"</div><div class=\\\"sub\\\" style=\\\"margin-top:10px\\\">不可动用资产：\" + money(safety.get(\"untouchable_assets\")) + \"</div>\")\n    risks = safety.get(\"major_risks\") or []\n    if risks:\n        parts.append('<table><thead><tr><th>风险</th><th>严重度</th><th>说明</th><th>风险码</th></tr></thead><tbody>')\n        for risk in risks:\n            sev = risk.get(\"severity\", \"low\")\n            label_cn, detail_cn = safety_risk_cn(risk)\n            parts.append(\n                f'<tr><td>{esc(label_cn)}</td>'\n                f'<td class=\"sev-{esc(sev)}\">{esc(RISK_CN.get(sev, sev))}</td>'\n                f'<td>{esc(detail_cn)}</td>'\n                f'<td><span class=\"mono\">{esc(risk.get(\"risk_id\", \"\"))}</span></td></tr>'\n            )\n        parts.append(\"</tbody></table>\")\n    else:\n        parts.append('<div class=\"note\">未发现重大风险信号。</div>')\n    parts.append(\"</div>\")\n\n    # Feasibility\n    parts.append('<div class=\"card\"><h2>目标可行性</h2>')\n    parts.append('<div class=\"sub\">系统只给出四种答案：通过、复核、拒绝、弃权。证据不足时拒绝下判断。</div>')\n    parts.append(f'<span class=\"verdict v-{esc(verdict)}\">{esc(VERDICT_CN.get(verdict, verdict))}（{esc(verdict)}）</span>')\n    parts.append('<div style=\"margin:10px 0\">')\n    for code in feasibility.get(\"reason_codes\") or []:\n        parts.append(f'<span class=\"pill\">{esc(code)}</span> ')\n    parts.append(\"</div><ul>\")\n    reason_codes = feasibility.get(\"reason_codes\") or []\n    reasons = feasibility.get(\"reasons\") or []\n    for index, reason in enumerate(reasons):\n        code = reason_codes[index] if index < len(reason_codes) else None\n        matched, reason_cn = feasibility_reason_cn(code, reason)\n        parts.append(f\"<li>{esc(reason_cn if matched else reason)}</li>\")\n    parts.append(\"</ul></div>\")\n\n    # Breadwinner & protection gap (T-E0-043)\n    breadwinner = result.get(\"breadwinner\") or {}\n    if breadwinner:\n        parts.append('<div class=\"card\"><h2>顶梁柱与保护缺口</h2>')\n        parts.append(\n            '<div class=\"sub\">谁在扛这个家庭；如果这个人身故、失能或长期失业，'\n            '家里还能撑多久，孩子的教育会不会被挤占。保险只是这里的一个模块。</div>'\n        )\n        if breadwinner.get(\"status\") != \"ABSTAIN\":\n            gap = breadwinner.get(\"protection_gap\") or {}\n            needs = breadwinner.get(\"needs\") or {}\n            edu = breadwinner.get(\"education\") or {}\n            gap_cn = {\"COVERED\": \"已覆盖\", \"PARTIAL\": \"部分覆盖\", \"OPEN\": \"存在缺口\"}.get(\n                gap.get(\"status\"), \"无法判断\"\n            )\n            parts.append(\n                '<div class=\"grid c3\" style=\"margin-bottom:10px\">'\n                + '<div class=\"metric\"><div class=\"k\">顶梁柱</div><div class=\"v mono\">'\n                + esc(breadwinner.get(\"primary_breadwinner_id\") or \"—\")\n                + '</div><div class=\"h\">最高收入占比 ' + pct(breadwinner.get(\"top_income_share\")) + '</div></div>'\n                + '<div class=\"metric\"><div class=\"k\">保护缺口（身故口径）</div><div class=\"v '\n                + (\"pos\" if (gap.get(\"gap_after_insurance\") or 0) <= 0 else \"neg\") + '\">'\n                + money(gap.get(\"gap_after_insurance\"))\n                + '</div><div class=\"h\">' + esc(gap_cn) + '</div></div>'\n                + '<div class=\"metric\"><div class=\"k\">刚性需求合计</div><div class=\"v\">'\n                + money(needs.get(\"need_total\"))\n                + '</div><div class=\"h\">应急金目标 ' + money(needs.get(\"survival_floor_value\"))\n                + ' + 教育 ' + money(needs.get(\"education_need\")) + '</div></div>'\n                + \"</div>\"\n            )\n            parts.append(\n                \"<table><thead><tr><th>意外情景</th><th class=\\\"num\\\">损失收入</th>\"\n                \"<th class=\\\"num\\\">可确认赔付</th><th class=\\\"num\\\">可动用资源</th>\"\n                \"<th class=\\\"num\\\">保护缺口</th><th class=\\\"num\\\">可支撑月数</th>\"\n                \"<th>教育连续性</th><th>结论</th></tr></thead><tbody>\"\n            )\n            scenario_cn = {\"SURVIVES\": \"可以撑住\", \"STRESSED\": \"被压到临界\", \"COLLAPSES\": \"会击穿底线\"}\n            for row in breadwinner.get(\"scenarios\") or []:\n                months = row.get(\"survival_months\")\n                months_text = \"剩余收入可覆盖\" if months is None else f\"{months:,.1f} 个月\"\n                parts.append(\n                    \"<tr><td>\" + esc(row.get(\"label_cn\") or row.get(\"event\") or \"\")\n                    + '</td><td class=\"num\">' + money(row.get(\"lost_income_annual\"))\n                    + '</td><td class=\"num\">' + money(row.get(\"payout_recorded\"))\n                    + '</td><td class=\"num\">' + money(row.get(\"resources_after_insurance\"))\n                    + '</td><td class=\"num ' + (\"pos\" if (row.get(\"gap_after_insurance\") or 0) <= 0 else \"neg\") + '\">'\n                    + money(row.get(\"gap_after_insurance\"))\n                    + '</td><td class=\"num\">' + esc(months_text)\n                    + \"</td><td>\"\n                    + (\"可隔离\" if row.get(\"education_funded\") else \"会被挤占\")\n                    + '</td><td>' + esc(scenario_cn.get(row.get(\"status\"), \"\"))\n                    + ' <span class=\"mono\">' + esc(row.get(\"status\") or \"\") + \"</span></td></tr>\"\n                )\n            parts.append(\"</tbody></table>\")\n            parts.append(\n                '<div class=\"note\">子女教育连续性：'\n                + esc({\"PROTECTED\": \"已隔离\", \"AT_RISK\": \"部分情景受挤占\", \"UNFUNDED\": \"无法隔离\",\n                       \"NOT_RECORDED\": \"未记录\"}.get(edu.get(\"status\"), \"无法判断\"))\n                + \" —— \" + esc(edu.get(\"finding_cn\") or \"\") + \"</div>\"\n            )\n            actions = breadwinner.get(\"actions\") or []\n            parts.append(\"<h3 style=\\\"margin:14px 0 6px;font-size:14px\\\">这一节给出的优先动作</h3>\")\n            if actions:\n                parts.append(\"<ul>\")\n                for action in actions:\n                    cost = action.get(\"cost_estimate\")\n                    parts.append(\n                        \"<li><b>\" + esc(action.get(\"priority\") or \"\") + \"</b> \"\n                        + esc(action.get(\"action_cn\") or \"\")\n                        + (f\"（涉及资金 ≈{money(cost)}）\" if cost else \"\")\n                        + '<div class=\"sub\">' + esc(action.get(\"rationale\") or \"\") + \"</div></li>\"\n                    )\n                parts.append(\"</ul>\")\n            else:\n                parts.append('<div class=\"note\">三种情景下都不存在缺口，没有新增动作。</div>')\n            parts.append('<div class=\"note\">缺口口径：' + esc(gap.get(\"formula_cn\") or \"\") + \"</div>\")\n        else:\n            parts.append(\n                '<div class=\"note\">引擎已弃权（ABSTAIN）：'\n                + esc(\n                    status_reason_cn(\n                        \"breadwinner_abstain\",\n                        breadwinner.get(\"status_reason\") or \"\",\n                    )\n                    or \"证据不足，本节不做任何缺口推算。\"\n                )\n                + \"</div>\"\n            )\n        parts.append(\"</div>\")\n\n    # Annual goal progress and take-profit state (T-E0-044)\n    annual_goal = result.get(\"annual_goal\") or {}\n    if annual_goal:\n        parts.append('<div class=\"card\"><h2>年度目标与止盈状态</h2>')\n        parts.append(\n            '<div class=\"sub\">长期资金 = （隔离应急金目标、'\n            + f\"{RIGID_CAPITAL_WINDOW_YEARS:g}\"\n            + ' 年内到期的刚性支出与一年保障保费之后的剩余资本）× '\n            + '长期增值袖套占比（不是家庭总资产，也没有把教育等刚性资金全部隔离：'\n            '只有窗口内到期的部分被隔离）；窗口外到期的刚性支出由这笔长期资金承担，'\n            '并按到期月份在月度投影中扣除。这笔长期资金今年要赚多少才算达标；'\n            '什么时候该停止新增风险、把已经拿到的收益从风险里拿出来。目标收益率来自家庭自己的记录，'\n            '已实现收益也只按记录读取，Verity 不推算、不假设任何收益。</div>'\n        )\n        if annual_goal.get(\"status\") != \"ABSTAIN\":\n            basis = annual_goal.get(\"basis\") or {}\n            progress = annual_goal.get(\"progress\") or {}\n            guardrails = annual_goal.get(\"guardrails\") or {}\n            state = annual_goal.get(\"state\")\n            state_cn = annual_goal.get(\"state_label_cn\") or state or \"无法判断\"\n            state_cls = {\n                \"STOP_ADDING_RISK\": \"ok\",\n                \"LOCK_PARTIAL\": \"warn\",\n                \"PROTECTION_FIRST\": \"bad\",\n                \"REDUCE_RISK_FIRST\": \"bad\",\n            }.get(state, \"info\")\n            parts.append(\n                '<div class=\"grid c3\" style=\"margin-bottom:10px\">'\n                + '<div class=\"metric\"><div class=\"k\">年度目标金额</div><div class=\"v\">'\n                + money(basis.get(\"target_amount\"))\n                + '</div><div class=\"h\">长期资金 ' + money(basis.get(\"long_term_growth\"))\n                + ' × 目标年化回报 ' + pct(basis.get(\"target_annual_return\"), 2) + '</div></div>'\n                + '<div class=\"metric\"><div class=\"k\">本月目标</div><div class=\"v\">'\n                + money(basis.get(\"monthly_target\"))\n                + '</div><div class=\"h\">按 12 个月均分，不是承诺</div></div>'\n                + '<div class=\"metric\"><div class=\"k\">止盈状态</div><div class=\"v ' \n                + (\"pos\" if state == \"STOP_ADDING_RISK\" else \"\")\n                + '\">' + esc(state_cn) + '</div><div class=\"h mono\">' + esc(state or \"\") + \"</div></div>\"\n                + \"</div>\"\n            )\n            parts.append(\n                '<div>本年进度 <span class=\"pill ' + (\"ok\" if progress.get(\"status\") == \"ACHIEVED\" else \"warn\" if progress.get(\"status\") == \"APPROACHING\" else \"info\")\n                + '\">' + esc(progress.get(\"status_label_cn\") or \"—\") + \"</span>\"\n                + \" 已记录净收益 \" + money(progress.get(\"recorded_net_gain\"))\n                + \" · 进度 \" + pct(progress.get(\"progress_ratio\"))\n                + \" · 距目标还差 \" + money(progress.get(\"remaining_amount\"))\n                + \" · 已锁定 \" + money(progress.get(\"locked_profit\"))\n                + ((\" · 记录日期 \" + esc(progress.get(\"recorded_as_of\"))) if progress.get(\"recorded_as_of\") else \"\")\n                + \"</div>\"\n            )\n            parts.append(\n                \"<table><thead><tr><th>目标刻度</th><th class=\\\"num\\\">对应金额</th>\"\n                \"<th class=\\\"num\\\">距 100% 还差</th></tr></thead><tbody>\"\n            )\n            for milestone in annual_goal.get(\"milestones\") or []:\n                parts.append(\n                    \"<tr><td>\" + esc(milestone.get(\"label_cn\") or \"\") + \"</td>\"\n                    + '<td class=\"num\">' + money(milestone.get(\"amount\")) + \"</td>\"\n                    + '<td class=\"num\">' + money(milestone.get(\"remaining\")) + \"</td></tr>\"\n                )\n            parts.append(\"</tbody></table>\")\n            parts.append(\n                '<div class=\"note\">风险闸门：可承受最大损失 '\n                + pct(guardrails.get(\"max_tolerable_loss_pct\"))\n                + \" · 模拟最大回撤 \" + pct(guardrails.get(\"simulated_max_drawdown\"))\n                + (\"（在预算内）\" if guardrails.get(\"drawdown_within_budget\") else \"（超出预算）\" if guardrails.get(\"drawdown_within_budget\") is False else \"（未记录）\")\n                + \" · 生存底线 \" + (f'{guardrails.get(\"safety_days\"):,.0f} 天' if guardrails.get(\"safety_days\") is not None else \"未记录\")\n                + \" · 顶梁柱保护缺口 \" + money(guardrails.get(\"protection_gap\"))\n                + \"</div>\"\n            )\n            actions = annual_goal.get(\"actions\") or []\n            parts.append('<h3>这一节给出的优先动作</h3>')\n            if actions:\n                parts.append(\"<ul>\")\n                for action in actions:\n                    amount = action.get(\"amount\")\n                    parts.append(\n                        \"<li><b>\" + esc(action.get(\"priority\") or \"\") + \"</b> \"\n                        + esc(action.get(\"action_cn\") or \"\")\n                        + (f\"（涉及资金 ≈{money(amount)}）\" if amount else \"\")\n                        + '<div class=\"sub\">' + esc(action.get(\"rationale\") or \"\") + \"</div></li>\"\n                    )\n                parts.append(\"</ul>\")\n            else:\n                parts.append('<div class=\"note\">本节没有新增动作。</div>')\n            parts.append(\n                '<div class=\"note\">' + esc(annual_goal.get(\"formula_cn\") or \"\")\n                + \" 锁定利润条件：\" + esc(annual_goal.get(\"lock_profit_condition_cn\") or \"\")\n                + \" 停止新增风险条件：\" + esc(annual_goal.get(\"stop_risk_condition_cn\") or \"\")\n                + \"</div>\"\n            )\n        else:\n            parts.append(\n                '<div class=\"note\">引擎已弃权（ABSTAIN）：'\n                + esc(\n                    status_reason_cn(\n                        \"annual_goal_abstain\",\n                        annual_goal.get(\"status_reason\") or \"\",\n                    )\n                    or \"证据不足，本节不计算任何年度目标。\"\n                )\n                + \"</div>\"\n            )\n        parts.append(\"</div>\")\n\n    # Insurance audit\n    insurance = result.get(\"insurance\") or {}\n    if insurance.get(\"status\") != \"ABSTAIN\":\n        parts.append('<div class=\"card\"><h2>保险责任审计</h2>')\n        parts.append(\n            '<div class=\"sub\">保险只是方案的一个模块：它覆盖被记录的家庭保障缺口，'\n            '不代表建议任何保险人、保单或产品。</div>'\n        )\n        caps = insurance.get(\"capabilities\") or {}\n        score = insurance.get(\"coverage_score\")\n        burden = insurance.get(\"premium_burden_status\")\n        burden_cn = {\"LOW\": \"低\", \"MEDIUM\": \"中\", \"HIGH\": \"高\"}.get(burden, burden or \"—\")\n        parts.append(\n            f'<span class=\"pill {\"ok\" if insurance.get(\"status\") == \"OK\" else \"bad\"}\">'\n            f'审计状态：{\"充足\" if insurance.get(\"status\") == \"OK\" else \"存在缺口\"}</span> '\n            f'<span class=\"pill\">覆盖得分 {score if score is not None else \"—\"}</span> '\n            f'<span class=\"pill\">保费负担：{burden_cn}'\n            + (f'（{insurance.get(\"premium_to_income\"):.1%}）' if insurance.get(\"premium_to_income\") is not None else \"\")\n            + '</span>'\n        )\n        parts.append('<table><thead><tr><th>保障能力</th><th class=\"num\">测算需求</th>'\n                     '<th class=\"num\">记录保额</th><th class=\"num\">缺口</th><th>状态</th></tr></thead><tbody>')\n        for capability in insurance.get(\"capability_order\") or []:\n            cap = caps.get(capability) or {}\n            status = cap.get(\"status\", \"GAP\")\n            status_cn = {\"COVERED\": \"已覆盖\", \"PARTIAL\": \"部分覆盖\",\n                         \"GAP\": \"缺口\", \"NOT_APPLICABLE\": \"不适用\"}.get(status, status)\n            css = \"ok\" if status in (\"COVERED\", \"NOT_APPLICABLE\") else (\"warn\" if status == \"PARTIAL\" else \"bad\")\n            gap_css = \"bad\" if (cap.get(\"gap\") or 0) > 0 else \"ok\"\n            parts.append(\n                f'<tr><td>{esc(cap.get(\"label_cn\", capability))}</td>'\n                f'<td class=\"num\">{money(cap.get(\"need\"))}</td>'\n                f'<td class=\"num\">{money(cap.get(\"coverage\"))}</td>'\n                f'<td class=\"num\" style=\"color:var(--{gap_css})\">'\n                f'{money(cap.get(\"gap\"))}</td>'\n                f'<td><span class=\"pill {css}\">{esc(status_cn)}</span></td></tr>'\n            )\n        parts.append(\"</tbody></table>\")\n        for warning in insurance.get(\"warnings\") or []:\n            parts.append(f'<div class=\"note\">{esc(insurance_warning_cn(warning))}</div>')\n        parts.append(\"</div>\")\n\n    # Allocation\n    parts.append('<div class=\"card\"><h2>多资产情景模拟</h2>')\n    parts.append('<div class=\"sub\">纯模拟：不执行任何交易，不点名任何证券，不承诺任何回报。</div>')\n    parts.append(\n        f'<span class=\"pill {\"ok\" if allocation.get(\"executed\") else \"bad\"}\">'\n        f'{\"增长计划允许\" if allocation.get(\"executed\") else \"仅防御性配置\"}</span> '\n        f'<span class=\"pill {\"ok\" if allocation.get(\"risk_budget_fit\") else \"bad\"}\">'\n        f'亏损预算适配：{\"是\" if allocation.get(\"risk_budget_fit\") else \"否\"}</span> '\n        f'<span class=\"pill\">模拟最大回撤 {pct(allocation.get(\"modelled_crash_drawdown\"), 0)}</span>'\n    )\n    parts.append('<table><thead><tr><th>资产类别</th><th class=\"num\">金额</th><th class=\"num\">占比</th></tr></thead><tbody>')\n    weights = allocation.get(\"allocation_weights\") or {}\n    amounts = allocation.get(\"allocation\") or {}\n    for name in weights:\n        parts.append(\n            f'<tr><td>{esc(ASSET_CN.get(name, name))}</td><td class=\"num\">{money(amounts.get(name))}</td>'\n            f'<td class=\"num\">{pct(weights.get(name))}</td></tr>'\n        )\n    parts.append(\"</tbody></table>\")\n\n    # Integrated protection plan\n    protection = result.get(\"protection\") or {}\n    plan_status = protection.get(\"status\", \"ABSTAIN\")\n    plan_status_cn = {\n        \"SECURED\": \"已覆盖\", \"GAPS\": \"存在缺口\", \"NOT_RECORDED\": \"未记录\",\n        \"REVIEW\": \"需复核\", \"ABSTAIN\": \"弃权\",\n    }.get(plan_status, plan_status)\n    parts.append('<div class=\"card\"><h2>综合保护方案</h2>')\n    parts.append(\n        '<div class=\"sub\">横跨现金、保险、资产、债务、法律与社会保障六个领域；'\n        '未记录的情况按“未记录”处理，不作假设；不推荐任何具体产品、机构或律师。</div>'\n    )\n    plan_css = {\"SECURED\": \"ok\", \"GAPS\": \"bad\", \"NOT_RECORDED\": \"warn\", \"REVIEW\": \"warn\", \"ABSTAIN\": \"\"}.get(\n        plan_status, \"\")\n    parts.append(\n        f'<span class=\"pill {plan_css}\">方案状态：{esc(plan_status_cn)}（{esc(plan_status)}）</span> '\n        f'<span class=\"pill info\">{esc(protection_reason_cn(protection.get(\"status_reason\", \"\")))}</span>'\n    )\n    parts.append('<table><thead><tr><th>领域</th><th>状态</th><th>结论</th></tr></thead><tbody>')\n    for domain in protection.get(\"domain_order\") or []:\n        dom = protection.get(\"domains\", {}).get(domain) or {}\n        dom_status = dom.get(\"status\", \"ABSTAIN\")\n        dom_cn = {\"SECURED\": \"已覆盖\", \"GAP\": \"缺口\", \"NOT_RECORDED\": \"未记录\",\n                  \"REVIEW\": \"需复核\", \"ABSTAIN\": \"弃权\"}.get(dom_status, dom_status)\n        dom_css = {\"SECURED\": \"ok\", \"GAP\": \"bad\", \"NOT_RECORDED\": \"warn\", \"REVIEW\": \"warn\"}.get(dom_status, \"\")\n        action_text = \"；\".join(\n            f'{esc(a.get(\"priority\"))} {esc(a.get(\"action_cn\"))}'\n            + (f'（约 {money(a.get(\"cost_estimate\"))}）' if a.get(\"cost_estimate\") else \"\")\n            for a in (dom.get(\"actions\") or [])\n        )\n        parts.append(\n            f'<tr><td>{esc(dom.get(\"label_cn\", domain))}</td>'\n            f'<td><span class=\"pill {dom_css}\">{esc(dom_cn)}</span></td>'\n            f'<td>{esc(dom.get(\"finding\", \"\"))}'\n            + (f'<div class=\"note\" style=\"margin-top:6px\">{action_text}</div>' if action_text else \"\")\n            + '</td></tr>'\n        )\n    parts.append(\"</tbody></table>\")\n    parts.append('<h3 style=\"margin-top:14px\">优先级行动清单</h3>')\n    parts.append('<table><thead><tr><th>优先级</th><th>领域</th><th>行动</th><th>理由</th>'\n                 '<th class=\"num\">成本估算</th></tr></thead><tbody>')\n    for action in protection.get(\"priority_actions\") or []:\n        prio_cn = {\"P0\": \"紧急\", \"P1\": \"重要\", \"P2\": \"按计划\"}.get(action.get(\"priority\", \"\"), action.get(\"priority\", \"\"))\n        parts.append(\n            f'<tr><td><span class=\"pill\">{esc(prio_cn)}</span></td>'\n            f'<td>{esc(action.get(\"domain_label\", \"\"))}</td>'\n            f'<td>{esc(action.get(\"action_cn\", \"\"))}</td>'\n            f'<td>{esc(action.get(\"rationale\", \"\"))}</td>'\n            f'<td class=\"num\">{money(action.get(\"cost_estimate\"))}</td></tr>'\n        )\n    parts.append(\"</tbody></table>\")\n    parts.append(f'<div class=\"note\">{esc(protection_reason_cn(protection.get(\"notice\", \"\")))}</div>')\n    parts.append(\"</div>\")\n\n    # Risk ranking\n    ranking = result.get(\"risk_ranking\") or {}\n    rank_level = ranking.get(\"overall_risk_level\", \"ABSTAIN\")\n    rank_cn = {\"CRITICAL\": \"严重\", \"ELEVATED\": \"偏高\", \"MODERATE\": \"中等\",\n               \"RESILIENT\": \"稳健\", \"ABSTAIN\": \"弃权\"}.get(rank_level, rank_level)\n    rank_css = {\"CRITICAL\": \"bad\", \"ELEVATED\": \"bad\", \"MODERATE\": \"warn\",\n                \"RESILIENT\": \"ok\", \"ABSTAIN\": \"\"}.get(rank_level, \"\")\n    parts.append('<div class=\"card\"><h2>家庭风险排序</h2>')\n    parts.append(\n        '<div class=\"sub\">按严重度×概率对引擎真实输出的风险排序；概率是文档化启发式估计，'\n        '不是预测。每条风险都指向产生它的引擎模块。</div>'\n    )\n    parts.append(\n        f'<span class=\"pill {rank_css}\">整体风险等级：{esc(rank_cn)}（{esc(rank_level)}）</span> '\n        f'<span class=\"pill info\">风险数 {ranking.get(\"risk_count\", 0)} · 需要行动 {ranking.get(\"active_count\", 0)}</span> '\n        f'<span class=\"pill\">首要风险：{esc(ranking.get(\"top_risk_id\") or \"—\")}</span>'\n    )\n    parts.append('<table><thead><tr><th class=\"num\">#</th><th>风险</th><th>类别</th><th>严重度</th>'\n                 '<th class=\"num\">概率</th><th class=\"num\">得分</th><th>状态</th><th>依据与应对</th></tr></thead><tbody>')\n    ranking_method_cn, ranking_notice_cn = risk_ranking_cn(ranking)\n    for index, risk in enumerate(ranking.get(\"ranked_risks\") or [], start=1):\n        sev = risk.get(\"severity\", \"low\")\n        status_pill = \"bad\" if risk.get(\"status\") == \"ACTIVE\" else \"info\"\n        prob_txt = \"—\" if risk.get(\"probability\") is None else f'{risk.get(\"probability\") * 100:.0f}%'\n        ranked_risk = dict(risk)\n        ranked_risk[\"detail\"] = risk.get(\"detail_cn\") or risk.get(\"detail\") or \"\"\n        label_cn, ranked_detail = safety_risk_cn(ranked_risk)\n        ranked_name = risk.get(\"label_cn\") or label_cn or risk.get(\"risk_id\", \"\")\n        parts.append(\n            f'<tr><td class=\"num\">{index}</td>'\n            f'<td>{esc(ranked_name)}<div class=\"note\" style=\"margin-top:3px\"><span class=\"mono\">{esc(risk.get(\"risk_id\", \"\"))}</span></div></td>'\n            f'<td>{esc(risk.get(\"category\", \"\"))}</td>'\n            f'<td class=\"sev-{esc(sev)}\">{esc(RISK_CN.get(sev, sev))}</td>'\n            f'<td class=\"num\">{prob_txt}</td>'\n            f'<td class=\"num\">{risk.get(\"score\", 0):,.2f}</td>'\n            f'<td><span class=\"pill {status_pill}\">{esc(risk.get(\"status\", \"\"))}</span></td>'\n            f'<td>{esc(ranked_detail)}'\n            f'<div class=\"note\" style=\"margin-top:3px\">{esc(risk.get(\"response_cn\", \"\"))}</div></td></tr>'\n        )\n    if not ranking.get(\"ranked_risks\"):\n        parts.append('<tr><td colspan=\"8\" class=\"note\">该家庭没有需要排序的风险，或证据不足已弃权。</td></tr>')\n    parts.append(\"</tbody></table>\")\n    parts.append(f'<div class=\"note\">{esc(ranking_method_cn)} {esc(ranking_notice_cn)}</div>')\n    parts.append(\"</div>\")\n\n    # Stress\n    parts.append('<h2 style=\"margin-top:20px\">压力情景</h2>')\n    scenario_count = len(stress.get(\"scenarios\") or [])\n    parts.append(\n        f'<div class=\"sub\">{scenario_count} 类压力逐一检验“生存底线是否被击穿”，并写出每个情景为什么咬人、'\n        f'或者为什么无效。多重风险叠加是其中最严苛的场景。</div>'\n    )\n    parts.append(\n        f'<span class=\"pill {\"bad\" if stress.get(\"survival_breach\") else \"ok\"}\">'\n        f'生存底线被击穿：{\"是\" if stress.get(\"survival_breach\") else \"否\"}</span> '\n        f'<span class=\"pill\">击穿场景数 {stress.get(\"breach_count\", 0)} / {scenario_count}</span>'\n    )\n    parts.append('<table><thead><tr><th>场景</th><th class=\"num\">组合损失</th>'\n                 '<th class=\"num\">未覆盖／额外支出</th><th class=\"num\">冲击后安全天数</th>'\n                 '<th>击穿底线</th><th>严重度</th><th>说明</th></tr></thead><tbody>')\n    total_assets = safety.get(\"total_assets\") or 0\n    for scenario in stress.get(\"scenarios\") or []:\n        sev = scenario.get(\"severity\", \"low\")\n        loss = scenario.get(\"portfolio_loss\") or 0\n        loss_share = (\n            f'<div class=\"sub\">占家庭资产 {pct(loss / total_assets)}</div>'\n            if total_assets else \"\"\n        )\n        parts.append(\n            f'<tr><td>{esc(SCENARIO_CN.get(scenario.get(\"scenario_id\"), scenario.get(\"label\", \"\")))}</td>'\n            f'<td class=\"num\">{money(loss)}{loss_share}</td>'\n            f'<td class=\"num\">{scenario.get(\"cash_outflow\", 0):,.0f}</td>'\n            f'<td class=\"num\">{scenario.get(\"survival_days_after\", 0):,.1f}</td>'\n            f'<td>{\"是\" if scenario.get(\"breaches_floor\") else \"否\"}</td>'\n            f'<td class=\"sev-{esc(sev)}\">{esc(SEVERITY_CN.get(sev, sev))}</td>'\n            f'<td>{esc(scenario.get(\"notes_cn\") or scenario.get(\"notes\", \"\"))}</td></tr>'\n        )\n    parts.append(\"</tbody></table>\")\n    parts.append(\"</div>\")\n\n    # 危险时间轴 (T-E0-034)\n    timeline = result.get(\"timeline\") or {}\n    tl_rows = timeline.get(\"rows\") or []\n    parts.append('<h2 style=\"margin-top:20px\">危险时间轴：第几个月进入危险区</h2>')\n    if timeline.get(\"status\") != \"OK\" or not tl_rows:\n        parts.append(\n            '<div class=\"note\">'\n            + esc(status_reason_cn(\"timeline_abstain\", timeline.get(\"status_reason\", \"危险时间轴按失败关闭：无法判断这个家庭第几个月进入危险区。\")))\n            + \"</div>\"\n        )\n    else:\n        tl_summary = timeline.get(\"summary\") or {}\n        earliest = tl_summary.get(\"earliest_breach_month\")\n        parts.append(\n            f'<span class=\"pill {\"bad\" if earliest else \"ok\"}\">12 个月内最早进入危险区：'\n            f'第 {earliest or \"—\"} 个月</span> '\n            f'<span class=\"pill {\"bad\" if tl_summary.get(\"breach_count_within_horizon\") else \"ok\"}\">'\n            f'12 个月内击穿情景 {tl_summary.get(\"breach_count_within_horizon\", 0)} / {len(tl_rows)}</span> '\n            f'<span class=\"pill info\">{(timeline.get(\"horizon_months\") or 12)} 个月关口 · '\n            f'{(timeline.get(\"long_horizon_months\") or 60)} 个月投影 · 不假设投资收益</span>'\n        )\n        parts.append(\n            '<table><thead><tr><th>场景</th><th class=\"num\">击穿月份</th><th>12 个月关口</th>'\n            '<th class=\"num\">组合损失</th><th class=\"num\">未覆盖／额外支出</th>'\n            '<th class=\"num\">收入损失</th><th>说明</th></tr></thead><tbody>'\n        )\n        for row in tl_rows:\n            if row.get(\"status\") != \"OK\":\n                month_txt = \"ABSTAIN\"\n                gate_txt = \"无法判定\"\n            elif row.get(\"breach_in_months\"):\n                month_txt = f\"第 {row['breach_in_months']} 个月\"\n                gate_txt = \"月内击穿\"\n            elif row.get(\"beyond_horizon_breach_month\"):\n                month_txt = \"12 个月内安全\"\n                gate_txt = f\"预计第 {row['beyond_horizon_breach_month']} 个月\"\n            else:\n                month_txt = \"未见击穿\"\n                gate_txt = \"安全\"\n            detail = row.get(\"notes_cn\") or row.get(\"status_reason\") or \"\"\n            parts.append(\n                f'<tr><td>{esc(SCENARIO_CN.get(row.get(\"scenario_id\"), row.get(\"label\", \"\")))}</td>'\n                f'<td class=\"num\">{month_txt}</td><td>{gate_txt}</td>'\n                f'<td class=\"num\">{money(row.get(\"portfolio_loss\") or 0)}</td>'\n                f'<td class=\"num\">{money(row.get(\"cash_outflow\") or 0)}</td>'\n                f'<td class=\"num\">{money(row.get(\"income_loss\") or 0)}</td>'\n                f'<td>{esc(detail)}</td></tr>'\n            )\n        parts.append(\"</tbody></table>\")\n\n    # Evidence\n    parts.append('<div class=\"card\"><h2>证据与审计</h2>')\n    parts.append(\n        f'<span class=\"pill {\"ok\" if evidence.get(\"evidence_status\") == \"VERIFIED\" else \"bad\"}\">'\n        f'证据状态：{esc(evidence.get(\"evidence_status\", \"NOT_VERIFIED\"))}</span> '\n        f'<span class=\"pill {\"ok\" if audit_ok else \"bad\"}\">审计链校验：{\"通过\" if audit_ok else \"失败\"}</span> '\n        f'<span class=\"pill mono\">记录哈希 {esc(str(evidence.get(\"record_hash\", \"\"))[:16])}…</span>'\n    )\n    parts.append('<div class=\"grid c2\" style=\"margin-top:12px\"><div>')\n    parts.append('<h3>数据来源</h3><ul>')\n    for source in evidence.get(\"sources\") or []:\n        parts.append(f\"<li><span class=\\\"mono\\\">{esc(source)}</span></li>\")\n    parts.append(\"</ul></div><div>\")\n    parts.append('<h3>已知限制</h3><ul>')\n    for limit in evidence.get(\"limits\") or []:\n        parts.append(f\"<li>{esc(evidence_item_cn(limit, 'limits'))}</li>\")\n    parts.append(\"</ul></div></div>\")\n    assumptions = evidence.get(\"assumptions\") or []\n    if assumptions:\n        parts.append('<div class=\"sub\" style=\"margin-top:10px\"><b>计算假设</b></div><ul>')\n        for assumption in assumptions:\n            parts.append(f\"<li>{esc(evidence_item_cn(assumption, 'assumptions'))}</li>\")\n        parts.append(\"</ul>\")\n    parts.append(\"</div>\")\n\n    # Risk notice\n    parts.append(f'<div class=\"note\">{esc(risk_notice_cn(risk_notice))}</div>')\n    parts.append(\n        '<div class=\"foot\">由 Verity E0 引擎生成 · 仅用于研究与演示 · '\n        f'生成时间 {esc(datetime.now(timezone.utc).replace(microsecond=0).isoformat())} UTC</div>'\n    )\n    parts.append(\"</div></body></html>\")\n    return \"\\n\".join(parts)\n", "risk_ranking.py": "\"\"\"Household risk ranking module (家庭风险排序).\n\nAnswers one question: which risks threaten this family first?\n\nThe module does not invent new risk measurements. It re-ranks signals the E0\nengine already computes elsewhere (safety, stress, insurance audit, integrated\nprotection plan and layering) into one list sorted by severity * probability.\n\nRules:\n  * every ranked item points back at the engine block that produced its signal;\n  * probability is a documented, deterministic heuristic (not a forecast);\n  * missing blocks refuse with ABSTAIN (fail-closed), never a silent default;\n  * the list is sorted deterministically; ties break on severity then risk_id.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    REFUSE_MIN_SURVIVAL_DAYS,\n    REVIEW_DEBT_PRESSURE,\n    REVIEW_SURVIVAL_DAYS,\n)\n\n#: Ordered severity scale used to compute scores.\nSEVERITY_WEIGHTS = {\"critical\": 4.0, \"high\": 3.0, \"medium\": 2.0, \"low\": 1.0}\nSEVERITY_ORDER = (\"critical\", \"high\", \"medium\", \"low\")\n\n#: A ranked item is ACTIVE when it needs attention now.\nACTIVE_MIN_PROBABILITY = 0.5\n\n#: How many ranked risks the API returns. The full count is still reported.\nMAX_LISTED_RISKS = 12\n\nOVERALL_LEVELS = (\"CRITICAL\", \"ELEVATED\", \"MODERATE\", \"RESILIENT\", \"ABSTAIN\")\n\nRISK_META = {\n    \"liquidity_shortfall\": {\n        \"category\": \"liquidity\",\n        \"label_cn\": \"流动资产缓冲不足\",\n        \"label_en\": \"Liquid buffer below review threshold\",\n    },\n    \"cash_gap\": {\n        \"category\": \"liquidity\",\n        \"label_cn\": \"应急金目标现金缺口\",\n        \"label_en\": \"Survival-floor cash gap\",\n    },\n    \"debt_pressure\": {\n        \"category\": \"debt\",\n        \"label_cn\": \"刚性债务压力过高\",\n        \"label_en\": \"Mandatory debt service pressure\",\n    },\n    \"illiquidity_concentration\": {\n        \"category\": \"assets\",\n        \"label_cn\": \"资产不可动用比例过高\",\n        \"label_en\": \"Untouchable-asset concentration\",\n    },\n    \"life_coverage_gap\": {\n        \"category\": \"insurance\",\n        \"label_cn\": \"寿险保障缺口\",\n        \"label_en\": \"Life cover below household income need\",\n    },\n    \"currency_exposure\": {\n        \"category\": \"assets\",\n        \"label_cn\": \"外币计价资产集中\",\n        \"label_en\": \"Foreign-currency exposure\",\n    },\n    \"no_growth_capacity\": {\n        \"category\": \"assets\",\n        \"label_cn\": \"无长期增长资本\",\n        \"label_en\": \"No residual capital for long-term growth\",\n    },\n    \"stress_floor_breach\": {\n        \"category\": \"stress\",\n        \"label_cn\": \"压力情景击穿生存底线\",\n        \"label_en\": \"Stress scenarios breach the survival floor\",\n    },\n    \"insurance_premium_burden\": {\n        \"category\": \"insurance\",\n        \"label_cn\": \"保费负担过高\",\n        \"label_en\": \"Insurance premium burden is high\",\n    },\n    \"legal_not_recorded\": {\n        \"category\": \"legal\",\n        \"label_cn\": \"法律安排证据缺失\",\n        \"label_en\": \"Legal arrangements not recorded\",\n    },\n    \"social_not_recorded\": {\n        \"category\": \"social\",\n        \"label_cn\": \"社会保障记录缺失\",\n        \"label_en\": \"Social security records missing\",\n    },\n    \"insurance_gap\": {\n        \"category\": \"insurance\",\n        \"label_cn\": \"被记录保障存在缺口\",\n        \"label_en\": \"Recorded protection below computed need\",\n    },\n}\n\nRESPONSES = {\n    \"liquidity_shortfall\": \"优先补足流动资产至应急金目标，再考虑任何长期配置。\",\n    \"cash_gap\": \"立即把现金缺口列入 P0：补足应急金目标所需流动现金。\",\n    \"debt_pressure\": \"先降低刚性债务服务占比或延长还款期限，再做其他规划。\",\n    \"illiquidity_concentration\": \"提高可动用资产占比，避免危机时无钱可用。\",\n    \"life_coverage_gap\": \"以家庭收入为基准核验寿险缺口，缺口部分列入 P0/P1。\",\n    \"currency_exposure\": \"评估汇率风险敞口是否需要与本币现金缓冲对冲。\",\n    \"no_growth_capacity\": \"先解决生存与刚性责任，增长只能在剩余资本之上展开。\",\n    \"stress_floor_breach\": \"压力测试击穿底线：任何计划都必须先修复承受冲击的能力。\",\n    \"insurance_premium_burden\": \"平衡保障缺口与保费负担，避免以负担换覆盖。\",\n    \"legal_not_recorded\": \"补录遗嘱、受益人指定、监护与授权委托等法律安排。\",\n    \"social_not_recorded\": \"补录社保、医保、基本养老金与就业援助记录。\",\n    \"insurance_gap\": \"按保险审计缺口清单优先补齐关键保障能力。\",\n}\n\n\ndef _number(value, default=None):\n    if isinstance(value, bool) or value is None:\n        return default\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return default\n    if number != number or number in (float(\"inf\"), float(\"-inf\")):\n        return default\n    return number\n\n\ndef _severity_weight(severity):\n    return SEVERITY_WEIGHTS.get(severity, 1.0)\n\n\ndef _income_stability_probability(profile):\n    \"\"\"Documented heuristic: member income stability drives interruption odds.\"\"\"\n    probabilities = {\"high\": 0.25, \"medium\": 0.5, \"low\": 0.8}\n    members = profile.get(\"members\") if isinstance(profile, dict) else None\n    if not members:\n        return 0.5\n    worst = 0.5\n    found = False\n    for member in members:\n        if not isinstance(member, dict):\n            continue\n        stability = member.get(\"income_stability\")\n        if stability in probabilities:\n            worst = max(worst, probabilities[stability])\n            found = True\n    return worst if found else 0.5\n\n\ndef _item(risk_id, severity, probability, block, detail_cn=None):\n    meta = RISK_META.get(risk_id, {\"category\": \"other\", \"label_cn\": risk_id, \"label_en\": risk_id})\n    score = round(_severity_weight(severity) * probability, 3)\n    status = \"ACTIVE\" if severity in (\"critical\", \"high\") or probability >= ACTIVE_MIN_PROBABILITY else \"MONITOR\"\n    return {\n        \"risk_id\": risk_id,\n        \"category\": meta[\"category\"],\n        \"label_cn\": meta[\"label_cn\"],\n        \"label_en\": meta[\"label_en\"],\n        \"severity\": severity,\n        \"probability\": round(probability, 3),\n        \"score\": score,\n        \"status\": status,\n        \"block\": block,\n        \"detail_cn\": detail_cn or \"\",\n        \"response_cn\": RESPONSES.get(risk_id, \"按保护方案优先级行动。\"),\n    }\n\n\ndef _abstain(reason):\n    return {\n        \"status\": \"ABSTAIN\",\n        \"status_reason\": reason,\n        \"overall_risk_level\": \"ABSTAIN\",\n        \"risk_count\": 0,\n        \"active_count\": 0,\n        \"top_risk_id\": None,\n        \"ranked_risks\": [],\n        \"ranking_method\": (\n            \"Risk ranking abstained without sufficient household evidence; \"\n            \"Verity never assumes what the family has not recorded.\"\n        ),\n        \"notice\": (\n            \"Risk ranking refused to judge: evidence is insufficient. \"\n            \"No risk is ranked on assumed data.\"\n        ),\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": \"Risk ranking abstained without sufficient household evidence.\",\n            \"assumptions\": [],\n            \"sources\": [],\n            \"computed_at_utc\": None,\n        },\n    }\n\n\ndef _overall_level(ranked):\n    if not ranked:\n        return \"RESILIENT\"\n    worst = ranked[0]\n    if worst[\"severity\"] == \"critical\" and worst[\"score\"] >= 2.0:\n        return \"CRITICAL\"\n    active = [r for r in ranked if r[\"status\"] == \"ACTIVE\"]\n    if worst[\"severity\"] in (\"critical\", \"high\") or len(active) >= 3:\n        return \"ELEVATED\"\n    return \"MODERATE\"\n\n\ndef build_risk_ranking(profile, *, safety=None, stress=None, insurance=None,\n                       protection=None, layers=None, allocation=None):\n    \"\"\"Rank household risks using signals the engine already computed.\n\n    ``safety`` is required; the other blocks are optional but make the ranking\n    strictly sharper. Blocks are never silently assumed.\n    \"\"\"\n    profile = profile if isinstance(profile, dict) else {}\n    if not isinstance(safety, dict) or \"major_risks\" not in safety:\n        return _abstain(\"Safety computation is unavailable; Verity refuses to rank without it.\")\n\n    ranked = []\n\n    # -- liquidity / cash ----------------------------------------------------\n    major_risks = safety.get(\"major_risks\") or []\n    stability_prob = _income_stability_probability(profile)\n    for major in major_risks:\n        risk_id = major.get(\"risk_id\")\n        if risk_id not in RISK_META:\n            continue\n        severity = major.get(\"severity\", \"medium\")\n        if risk_id == \"liquidity_shortfall\":\n            probability = stability_prob if severity != \"critical\" else max(stability_prob, 0.7)\n        elif risk_id == \"debt_pressure\":\n            probability = 0.8 if severity == \"critical\" else 0.55\n        elif risk_id == \"life_coverage_gap\":\n            probability = 0.7 if severity == \"high\" else 0.45\n        elif risk_id in (\"illiquidity_concentration\", \"currency_exposure\", \"no_growth_capacity\"):\n            probability = {\"illiquidity_concentration\": 0.4,\n                           \"currency_exposure\": 0.3,\n                           \"no_growth_capacity\": 0.35}.get(risk_id, 0.4)\n        else:\n            probability = 0.5\n        ranked.append(_item(risk_id, severity, probability, \"safety\",\n                            detail_cn=major.get(\"detail\", \"\")))\n\n    cash_gap = _number(safety.get(\"cash_gap\"), 0.0)\n    if cash_gap and cash_gap > 0 and \"cash_gap\" not in [r[\"risk_id\"] for r in ranked]:\n        ranked.append(_item(\n            \"cash_gap\", \"critical\" if cash_gap > 0 else \"high\",\n            max(stability_prob, 0.6), \"safety\",\n            detail_cn=f\"现金缺口 {cash_gap:,.0f}，应急金目标未完全覆盖。\",\n        ))\n\n    # -- stress ----------------------------------------------------------------\n    if isinstance(stress, dict):\n        scenarios = stress.get(\"scenarios\") or []\n        breached = [s for s in scenarios if s.get(\"breaches_floor\")]\n        if breached:\n            probability = max(0.5, min(0.9, len(breached) / max(1, len(scenarios))))\n            ranked.append(_item(\n                \"stress_floor_breach\", \"critical\", probability, \"stress\",\n                detail_cn=f\"{len(breached)} 个压力情景击穿 {REFUSE_MIN_SURVIVAL_DAYS} 天生存底线。\",\n            ))\n\n    # -- insurance ----------------------------------------------------------------\n    if isinstance(insurance, dict):\n        burden = insurance.get(\"premium_burden_status\")\n        if burden == \"HIGH\":\n            ranked.append(_item(\n                \"insurance_premium_burden\", \"medium\", 0.5, \"insurance\",\n                detail_cn=\"保费负担占收入比例处于高区间。\",\n            ))\n        caps = insurance.get(\"capabilities\") or {}\n        order = insurance.get(\"capability_order\") or []\n        gaps = []\n        for capability in order:\n            cap = caps.get(capability) or {}\n            gap = _number(cap.get(\"gap\"), 0.0)\n            if gap and gap > 0 and cap.get(\"status\") in (\"GAP\", \"PARTIAL\", None):\n                gaps.append((capability, gap))\n        if gaps and not any(r[\"risk_id\"] == \"life_coverage_gap\" for r in ranked):\n            max_gap_capability, max_gap = max(gaps, key=lambda pair: pair[1])\n            severity = \"critical\" if max_gap_capability in (\"life\", \"disability\") else \"high\"\n            ranked.append(_item(\n                \"insurance_gap\", severity, 0.7 if severity == \"critical\" else 0.5,\n                \"insurance\",\n                detail_cn=f\"保障缺口合计 {sum(g for _, g in gaps):,.0f}，最大缺口来自 {max_gap_capability}。\",\n            ))\n\n    # -- legal / social from the integrated protection plan -------------------------\n    if isinstance(protection, dict):\n        domains = protection.get(\"domains\") or {}\n        for domain, risk_id in ((\"legal\", \"legal_not_recorded\"), (\"social\", \"social_not_recorded\")):\n            dom = domains.get(domain) or {}\n            status = dom.get(\"status\")\n            if status == \"NOT_RECORDED\":\n                ranked.append(_item(\n                    risk_id, \"medium\", 0.35, \"protection\",\n                    detail_cn=dom.get(\"finding\", \"该领域没有任何已记录证据。\"),\n                ))\n\n    # -- final ranking ----------------------------------------------------------------\n    seen = {}\n    unique = []\n    for item in ranked:\n        if item[\"risk_id\"] in seen:\n            continue\n        seen[item[\"risk_id\"]] = True\n        unique.append(item)\n    unique.sort(\n        key=lambda r: (-r[\"score\"], -_severity_weight(r[\"severity\"]), r[\"risk_id\"])\n    )\n\n    top_risk_id = unique[0][\"risk_id\"] if unique else None\n    return {\n        \"status\": \"RANKED\",\n        \"status_reason\": (\n            \"Risks are ranked from safety, stress, insurance-audit and protection-plan \"\n            \"signals actually computed for this household.\"\n        ),\n        \"overall_risk_level\": _overall_level(unique),\n        \"risk_count\": len(unique),\n        \"active_count\": len([r for r in unique if r[\"status\"] == \"ACTIVE\"]),\n        \"top_risk_id\": top_risk_id,\n        \"ranked_risks\": unique[:MAX_LISTED_RISKS],\n        \"ranking_method\": (\n            \"score = severity_weight * probability, where probability is a documented \"\n            \"deterministic heuristic (never a forecast); sorted by score descending.\"\n        ),\n        \"notice\": (\n            \"Risk ranking is decision support, not a prediction. Probability is an \"\n            \"evidence-based heuristic, not a statistical forecast.\"\n        ),\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": (\n                \"Re-rank safety major_risks, cash gap, stress-floor breaches, insurance gaps, \"\n                \"premium burden and unrecorded legal/social domains by severity*probability.\"\n            ),\n            \"assumptions\": [\n                \"Probability priors: income_stability high=0.25, medium=0.5, low=0.8; \"\n                \"debt critical=0.8/high=0.55; stress breach=breach_count/scenario_count \"\n                \"(clamped 0.5-0.9); P0 insurance gap=0.7; legal/social missing=0.35.\",\n                \"Scores rank attention, they are not calibrated probabilities of loss.\",\n            ],\n            \"sources\": [\n                \"engine/risk_ranking.py\",\n                \"engine/safety.py:major_risks\",\n                \"engine/stress.py:scenarios\",\n                \"engine/insurance.py:capabilities\",\n                \"engine/protection.py:domains\",\n            ],\n            \"computed_at_utc\": None,\n        },\n    }\n", "safety.py": "\"\"\"Household safety computation.\n\nAnswers one question first: how long can this family survive if income stops and\nnothing else changes? Everything else in the engine is subordinate to that number.\n\nConventions:\n  * ``liabilities[].mandatory_payment`` is ANNUAL debt service.\n  * ``liquid_immediate_assets`` counts assets callable inside the survival horizon\n    (liquidity ``immediate`` or ``near``, or any asset of kind ``cash``).\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom engine.layering import survival_buffer_days\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    DEFAULT_SURVIVAL_TARGET_DAYS,\n    LIQUIDITY_CANNOT_TOUCH,\n    REVIEW_DEBT_PRESSURE,\n    REVIEW_SURVIVAL_DAYS,\n    MATERIALITY,\n)\n\n\ndef _number(value, default=None):\n    if isinstance(value, bool) or value is None:\n        return default\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return default\n    if number != number or number in (float(\"inf\"), float(\"-inf\")):\n        return default\n    return number\n\n\ndef _total_assets(profile):\n    total = 0.0\n    for asset in profile.get(\"assets\") or []:\n        if isinstance(asset, dict):\n            value = _number(asset.get(\"value\"), 0.0)\n            if value > 0:\n                total += value\n    return total\n\n\ndef _liquid_assets(profile):\n    liquid = 0.0\n    for asset in profile.get(\"assets\") or []:\n        if not isinstance(asset, dict):\n            continue\n        value = _number(asset.get(\"value\"), 0.0)\n        if value <= 0:\n            continue\n        liquidity = asset.get(\"liquidity\")\n        kind = asset.get(\"kind\")\n        if kind == \"cash\":\n            liquid += value\n        elif liquidity in (\"immediate\", \"near\"):\n            liquid += value\n    return liquid\n\n\ndef _untouchable_assets(profile):\n    untouchable = 0.0\n    for asset in profile.get(\"assets\") or []:\n        if not isinstance(asset, dict):\n            continue\n        value = _number(asset.get(\"value\"), 0.0)\n        if value <= 0:\n            continue\n        if asset.get(\"liquidity\") == LIQUIDITY_CANNOT_TOUCH or asset.get(\"kind\") == \"illiquid\":\n            untouchable += value\n    return untouchable\n\n\ndef _gross_income(profile):\n    total = 0.0\n    for member in profile.get(\"members\") or []:\n        if isinstance(member, dict):\n            total += max(0.0, _number(member.get(\"annual_income\"), 0.0))\n    return total\n\n\ndef _mandatory_debt_service(profile):\n    total = 0.0\n    for liability in profile.get(\"liabilities\") or []:\n        if isinstance(liability, dict):\n            total += max(0.0, _number(liability.get(\"mandatory_payment\"), 0.0))\n    return total\n\n\ndef _life_coverage(profile):\n    total = 0.0\n    for policy in profile.get(\"protection\") or []:\n        if isinstance(policy, dict) and policy.get(\"kind\") == \"life\":\n            total += max(0.0, _number(policy.get(\"coverage\"), 0.0))\n    return total\n\n\ndef _currency_exposure(profile):\n    \"\"\"Share of assets denominated outside the household's reporting currency.\"\"\"\n    base = profile.get(\"currency\")\n    total = _total_assets(profile)\n    if total <= MATERIALITY:\n        return 0.0\n    foreign = 0.0\n    for asset in profile.get(\"assets\") or []:\n        if not isinstance(asset, dict):\n            continue\n        currency = asset.get(\"currency\")\n        if currency and base and currency != base:\n            foreign += max(0.0, _number(asset.get(\"value\"), 0.0))\n    return foreign / total\n\n\ndef _major_risks(profile, *, safety_days, debt_pressure, untouchable, total_assets, funded_growth):\n    risks = []\n    essential = max(0.0, _number(profile.get(\"annual_expenses_essential\"), 0.0))\n\n    if safety_days < REVIEW_SURVIVAL_DAYS:\n        risks.append(\n            {\n                \"risk_id\": \"liquidity_shortfall\",\n                \"label\": \"Liquid buffer below the review threshold\",\n                \"severity\": \"critical\" if safety_days < 90 else \"high\",\n                \"detail\": f\"Safety days {safety_days:.1f} is below {REVIEW_SURVIVAL_DAYS}.\",\n            }\n        )\n\n    if debt_pressure is None:\n        risks.append(\n            {\n                \"risk_id\": \"debt_service_undeterminable\",\n                \"label\": \"Debt pressure cannot be computed\",\n                \"severity\": \"medium\",\n                \"detail\": \"No gross income is recorded while debt service exists.\",\n            }\n        )\n    elif debt_pressure > REVIEW_DEBT_PRESSURE:\n        risks.append(\n            {\n                \"risk_id\": \"debt_pressure\",\n                \"label\": \"Debt service consumes an unsafe share of income\",\n                \"severity\": \"critical\" if debt_pressure > 0.6 else \"high\",\n                \"detail\": f\"Debt pressure {debt_pressure:.2%} exceeds {REVIEW_DEBT_PRESSURE:.0%}.\",\n            }\n        )\n\n    if total_assets > MATERIALITY and untouchable / total_assets > 0.5:\n        risks.append(\n            {\n                \"risk_id\": \"illiquidity_concentration\",\n                \"label\": \"Most wealth cannot be touched in a crisis\",\n                \"severity\": \"high\",\n                \"detail\": f\"{untouchable / total_assets:.0%} of assets are untouchable.\",\n            }\n        )\n\n    coverage = _life_coverage(profile)\n    income = _gross_income(profile)\n    if income > MATERIALITY and coverage < income * 5:\n        risks.append(\n            {\n                \"risk_id\": \"life_coverage_gap\",\n                \"label\": \"Life cover is below five years of household income\",\n                \"severity\": \"high\" if coverage < income * 2 else \"medium\",\n                \"detail\": f\"Coverage {coverage:.0f} vs five-year income need {income * 5:.0f}.\",\n            }\n        )\n\n    fx_share = _currency_exposure(profile)\n    if fx_share > 0.3:\n        risks.append(\n            {\n                \"risk_id\": \"currency_exposure\",\n                \"label\": \"Large share of wealth is denominated in a foreign currency\",\n                \"severity\": \"medium\",\n                \"detail\": f\"{fx_share:.0%} of assets sit outside the reporting currency.\",\n            }\n        )\n\n    if essential > MATERIALITY and not funded_growth:\n        risks.append(\n            {\n                \"risk_id\": \"no_growth_capacity\",\n                \"label\": \"No residual capital available for long-term growth\",\n                \"severity\": \"medium\",\n                \"detail\": \"Survival, rigid duty and protection consume all recorded assets.\",\n            }\n        )\n\n    return risks\n\n\ndef compute_safety(profile, layers=None):\n    \"\"\"Compute safety days, cash gap, debt pressure, untouchable assets and major risks.\"\"\"\n    if not isinstance(profile, dict):\n        profile = {}\n\n    total_assets = _total_assets(profile)\n    liquid = _liquid_assets(profile)\n    untouchable = _untouchable_assets(profile)\n\n    essential = max(0.0, _number(profile.get(\"annual_expenses_essential\"), 0.0))\n    daily_burn = essential / 365.0\n\n    target_days = _number(profile.get(\"survival_target_days\"), DEFAULT_SURVIVAL_TARGET_DAYS)\n    if target_days is None or target_days <= 0:\n        target_days = DEFAULT_SURVIVAL_TARGET_DAYS\n\n    # 单一来源（T-E0-045 / H-05）：与 trend 的击穿判定用同一个函数、同一个量。\n    shared_days = survival_buffer_days(liquid, essential)\n    if daily_burn > MATERIALITY and shared_days is not None:\n        safety_days = shared_days\n    else:\n        safety_days = 0.0\n\n    survival_floor_value = daily_burn * target_days\n    cash_gap = max(0.0, survival_floor_value - liquid)\n\n    input_layer = None\n    for asset in profile.get(\"assets\") or []:\n        if not isinstance(asset, dict):\n            continue\n        if asset.get(\"kind\") == \"illiquid\":\n            continue\n        if _number(asset.get(\"value\"), 0.0) <= 0:\n            continue\n        liquidity = asset.get(\"liquidity\")\n        if liquidity is None or liquidity in (\"immediate\", \"near\"):\n            input_layer = asset.get(\"value\")\n            break\n\n    income = _gross_income(profile)\n    debt_service = _mandatory_debt_service(profile)\n    if income > MATERIALITY:\n        debt_pressure_ratio = debt_service / income\n    elif debt_service > MATERIALITY:\n        debt_pressure_ratio = None\n    else:\n        debt_pressure_ratio = 0.0\n\n    funded_growth = True\n    if isinstance(layers, dict) and \"growth_fraction\" in layers:\n        funded_growth = layers.get(\"growth_fraction\", 0.0) > 0\n\n    major_risks = _major_risks(\n        profile,\n        safety_days=safety_days,\n        debt_pressure=debt_pressure_ratio,\n        untouchable=untouchable,\n        total_assets=total_assets,\n        funded_growth=funded_growth,\n    )\n\n    return {\n        \"safety_days\": safety_days,\n        \"survival_burn_annual\": essential,\n        \"daily_burn\": daily_burn,\n        \"survival_target_days\": target_days,\n        \"survival_floor_value\": survival_floor_value,\n        \"liquid_assets\": liquid,\n        \"untouchable_assets\": untouchable,\n        \"total_assets\": total_assets,\n        \"cash_gap\": cash_gap,\n        \"debt_pressure_ratio\": debt_pressure_ratio,\n        \"gross_income\": income,\n        \"mandatory_debt_service_annual\": debt_service,\n        \"major_risks\": major_risks,\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": \"survival-first safety arithmetic on liquid assets, income and mandatory debt\",\n            \"assumptions\": [\n                \"safety_days = liquid assets / daily essential burn.\",\n                f\"Cash gap targets {target_days:.0f} days of essential spending.\",\n                \"mandatory_payment on each liability is treated as annual debt service.\",\n                \"Untouchable assets are excluded from every survival calculation.\",\n            ],\n            \"computed_at_utc\": None,\n            \"sources\": [\"docs/INTERFACE_FREEZE_V0_1.md\"],\n        },\n    }\n", "stress.py": "\"\"\"Stress testing.\n\nEight scenarios are mandatory in E0 and all eight are always reported:\n\n    income_interruption, equity_crash, rate_change, medical_shock, fx_change,\n    inflation_spiral, income_concentration, combined_multi_risk\n\ncombined_multi_risk exists because real families are not hit one risk at a time.\ninflation_spiral and income_concentration (T-E0-033) cover two failure paths a single-\nperiod balance sheet hides: costs that escalate faster than income, and a household\nwhose capacity depends on one income stream. A plan that survives only the isolated\nscenarios is not a plan.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    DAYS_PER_MONTH,\n    DEFAULT_SEED,\n    INCOME_CONCENTRATION_MONTHS,\n    INCOME_LOSS_MONTHS,\n    INCOME_RETENTION_SHARE,\n    INFLATION_SPIRAL_ESSENTIAL_ESCALATION,\n    INFLATION_SPIRAL_RATE_HIKE,\n    MATERIALITY,\n    MEDICAL_SHOCK_MINIMUM,\n    MEDICAL_SHOCK_MULTIPLE_OF_ESSENTIAL,\n    REFUSE_MIN_SURVIVAL_DAYS,\n    REVIEW_SURVIVAL_DAYS,\n)\n\nSCENARIO_ORDER = (\n    \"income_interruption\",\n    \"equity_crash\",\n    \"rate_change\",\n    \"medical_shock\",\n    \"fx_change\",\n    \"inflation_spiral\",\n    \"income_concentration\",\n    \"combined_multi_risk\",\n)\n\n#: Version of the mandatory scenario set itself. It moves when scenarios are added or\n#: removed, so a reader can tell which set produced a stored result.\nSCENARIO_SET_VERSION = \"e0.2.0\"\n\nSCENARIO_LABELS = {\n    \"income_interruption\": \"Income stops for six months\",\n    \"equity_crash\": \"Equity markets fall sharply\",\n    \"rate_change\": \"Interest rates move against the portfolio\",\n    \"medical_shock\": \"A major uninsured medical event\",\n    \"fx_change\": \"Reporting-currency strength hits foreign assets\",\n    \"inflation_spiral\": \"Costs spiral while a rate hike reprices debt\",\n    \"income_concentration\": \"The largest income stream stops for a year\",\n    \"combined_multi_risk\": \"Crash, rate move, medical shock and income stop together\",\n}\n\nSCENARIO_LABELS_CN = {\n    \"income_interruption\": \"收入中断 3 个月\",\n    \"equity_crash\": \"权益市场大幅下跌\",\n    \"rate_change\": \"利率向不利方向变动\",\n    \"medical_shock\": \"大额未覆盖医疗事件\",\n    \"fx_change\": \"记账币种走强削弱外币资产\",\n    \"inflation_spiral\": \"通胀螺旋：生活成本上涨＋利率上调重定价债务\",\n    \"income_concentration\": \"单一收入依赖加深：最大收入来源中断 12 个月\",\n    \"combined_multi_risk\": \"暴跌＋利率＋医疗＋收入中断同时发生\",\n}\n\n#: Per-scenario shocks expressed as return deltas on each asset class.\nSCENARIO_SHOCKS = {\n    \"income_interruption\": {},\n    \"equity_crash\": {\n        \"cash\": 0.0, \"bond\": 0.02, \"global_index\": -0.25,\n        \"equity\": -0.35, \"gold\": 0.08, \"option_protection\": 0.30,\n    },\n    \"rate_change\": {\n        \"cash\": 0.005, \"bond\": -0.12, \"global_index\": -0.08,\n        \"equity\": -0.10, \"gold\": -0.06, \"option_protection\": 0.05,\n    },\n    \"medical_shock\": {},\n    \"fx_change\": {},\n    # A rate hike in an inflation spiral reprices bonds and long-duration growth assets\n    # rather than the flat \"rate_change\" shock; cash keeps its nominal value but loses\n    # purchasing power, which is captured by the escalating essential outflow instead.\n    \"inflation_spiral\": {\n        \"cash\": 0.0, \"bond\": -0.10, \"global_index\": -0.12,\n        \"equity\": -0.15, \"gold\": 0.05, \"option_protection\": 0.0,\n    },\n    \"income_concentration\": {},\n    \"combined_multi_risk\": {\n        \"cash\": 0.0, \"bond\": -0.10, \"global_index\": -0.30,\n        \"equity\": -0.42, \"gold\": 0.02, \"option_protection\": 0.28,\n    },\n}\n\n#: Scenarios in which the household loses its income stream.\nINCOME_LOSS_SCENARIOS = (\"income_interruption\", \"combined_multi_risk\")\n\n\ndef _number(value, default=0.0):\n    if isinstance(value, bool) or value is None:\n        return default\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return default\n    if number != number or number in (float(\"inf\"), float(\"-inf\")):\n        return default\n    return number\n\n\ndef _severity(breaches_floor, survival_days_after):\n    if breaches_floor:\n        return \"critical\"\n    if survival_days_after < REVIEW_SURVIVAL_DAYS:\n        return \"high\"\n    if survival_days_after < 365:\n        return \"medium\"\n    return \"low\"\n\n\ndef _currency_exposure(profile):\n    base = profile.get(\"currency\")\n    total = 0.0\n    foreign = 0.0\n    for asset in profile.get(\"assets\") or []:\n        if not isinstance(asset, dict):\n            continue\n        value = max(0.0, _number(asset.get(\"value\"), 0.0))\n        total += value\n        currency = asset.get(\"currency\")\n        if currency and base and currency != base:\n            foreign += value\n    if total <= MATERIALITY:\n        return 0.0\n    return foreign / total\n\n\ndef _income_concentration(profile):\n    \"\"\"Return ``(largest_stream, total_income, share)`` from the recorded members.\n\n    The largest recorded income stream (the member flagged ``primary_earner`` when the\n    profile says so, otherwise the biggest annual income) is what a household depends\n    on. Nothing is inferred: a profile without recorded income returns zeros.\n    \"\"\"\n    members = profile.get(\"members\")\n    if not isinstance(members, list):\n        return 0.0, 0.0, 0.0\n    largest = 0.0\n    total = 0.0\n    flagged = 0.0\n    for member in members:\n        if not isinstance(member, dict):\n            continue\n        income = max(0.0, _number(member.get(\"annual_income\"), 0.0))\n        total += income\n        largest = max(largest, income)\n        if member.get(\"role\") == \"primary_earner\":\n            flagged = max(flagged, income)\n    stream = flagged if flagged > 0 else largest\n    if largest > 0 and flagged > 0:\n        stream = max(flagged, largest)\n    share = stream / total if total > MATERIALITY else 0.0\n    return stream, total, share\n\n\ndef _debt_repricing(profile):\n    \"\"\"Annual extra debt service caused by a rate hike on recorded debt balances.\"\"\"\n    principal = 0.0\n    liability_rows = profile.get(\"liabilities\")\n    if isinstance(liability_rows, list):\n        for liability in liability_rows:\n            if isinstance(liability, dict):\n                principal += max(0.0, _number(liability.get(\"balance\"), 0.0))\n    return round(principal * INFLATION_SPIRAL_RATE_HIKE, 2)\n\n\ndef run_stress_tests(profile, allocation, safety, seed=DEFAULT_SEED):\n    \"\"\"Run the six mandatory stress scenarios against a simulated allocation.\"\"\"\n    profile = profile if isinstance(profile, dict) else {}\n    allocation = allocation if isinstance(allocation, dict) else {}\n    safety = safety if isinstance(safety, dict) else {}\n\n    weights = allocation.get(\"allocation_weights\") or {}\n    if not weights:\n        weights = {name: 0.0 for name in SCENARIO_SHOCKS[\"equity_crash\"]}\n\n    portfolio_value = _number(safety.get(\"total_assets\"), 0.0)\n    liquid = _number(safety.get(\"liquid_assets\"), 0.0)\n    daily_burn = _number(safety.get(\"daily_burn\"), 0.0)\n    essential = _number(safety.get(\"survival_burn_annual\"), 0.0)\n    debt_service = _number(safety.get(\"mandatory_debt_service_annual\"), 0.0)\n\n    fx_share = _currency_exposure(profile)\n    medical_gross = max(MEDICAL_SHOCK_MINIMUM, essential * MEDICAL_SHOCK_MULTIPLE_OF_ESSENTIAL)\n    health_coverage = 0.0\n    for item in profile.get(\"protection\") or []:\n        if isinstance(item, dict) and item.get(\"kind\") == \"health\":\n            health_coverage += max(0.0, _number(item.get(\"coverage\"), 0.0))\n    # Only the uncovered part of a medical event can actually break the household.\n    medical_amount = max(0.0, medical_gross - health_coverage)\n\n    household_debt_repricing = _debt_repricing(profile)\n    primary_income, total_income, income_share = _income_concentration(profile)\n    annual_essential_escalation = round(essential * INFLATION_SPIRAL_ESSENTIAL_ESCALATION, 2)\n\n    scenarios = []\n\n    for scenario_id in SCENARIO_ORDER:\n        shocks = SCENARIO_SHOCKS[scenario_id]\n\n        portfolio_loss = 0.0\n        for class_name, shock in shocks.items():\n            portfolio_loss += _number(weights.get(class_name), 0.0) * shock * portfolio_value\n        portfolio_loss = -abs(portfolio_loss) if portfolio_loss < 0 else 0.0\n        portfolio_loss = round(portfolio_loss, 2)\n\n        uncovered_medical = 0.0\n        essential_escalation = 0.0\n        debt_repricing = 0.0\n        if scenario_id in (\"medical_shock\", \"combined_multi_risk\"):\n            uncovered_medical = medical_amount\n        elif scenario_id == \"inflation_spiral\":\n            essential_escalation = annual_essential_escalation\n            debt_repricing = household_debt_repricing\n        cash_outflow = round(uncovered_medical + essential_escalation + debt_repricing, 2)\n\n        if scenario_id == \"fx_change\":\n            portfolio_loss = round(\n                -abs(portfolio_value * fx_share * 0.10) if fx_share > 0 else 0.0, 2\n            )\n\n        months_without_income = INCOME_LOSS_MONTHS if scenario_id in INCOME_LOSS_SCENARIOS else 0.0\n        income_loss = 0.0\n        if months_without_income:\n            gross_income_loss = daily_burn * months_without_income * DAYS_PER_MONTH\n            income_loss = gross_income_loss * (1.0 - INCOME_RETENTION_SHARE)\n        elif scenario_id == \"income_concentration\":\n            # The lost stream is recorded income, not a burn-rate proxy: the household\n            # keeps the other streams, so only the largest stream stops.\n            income_loss = round(primary_income * (INCOME_CONCENTRATION_MONTHS / 12.0), 2)\n\n        available = liquid + portfolio_loss - cash_outflow - income_loss\n        if daily_burn > MATERIALITY:\n            survival_days_after = max(0.0, available / daily_burn)\n        else:\n            survival_days_after = 0.0\n\n        breaches_floor = survival_days_after < REFUSE_MIN_SURVIVAL_DAYS\n        debt_covered = available >= debt_service\n\n        notes = []\n        notes_cn = []\n        if months_without_income:\n            notes.append(\n                f\"Income stops for {months_without_income:.0f} months; \"\n                f\"{INCOME_RETENTION_SHARE:.0%} is assumed to be absorbed by other sources.\"\n            )\n            notes_cn.append(\n                f\"收入中断 {months_without_income:.0f} 个月；其中 {INCOME_RETENTION_SHARE:.0%} \"\n                f\"由其他来源吸收。\"\n            )\n        if scenario_id in (\"medical_shock\", \"combined_multi_risk\"):\n            if uncovered_medical:\n                notes.append(f\"Uncovered medical cash outflow of {uncovered_medical:,.0f}.\")\n                notes_cn.append(f\"未覆盖医疗支出 {uncovered_medical:,.0f}。\")\n            else:\n                notes.append(\n                    f\"Medical event of {medical_gross:,.0f} is fully covered by recorded health protection.\"\n                )\n                notes_cn.append(\n                    f\"医疗事件 {medical_gross:,.0f} 已被记录的健康保障完全覆盖。\"\n                )\n        if scenario_id == \"fx_change\":\n            if fx_share > 0:\n                notes.append(f\"{fx_share:.0%} of assets are foreign-currency denominated.\")\n                notes_cn.append(f\"外币资产占全部资产 {fx_share:.0%}。\")\n            else:\n                notes.append(\"No foreign-currency exposure was recorded; the scenario is inert.\")\n                notes_cn.append(\"未记录任何外币敞口，本情景无效。\")\n        if scenario_id == \"inflation_spiral\":\n            notes.append(\n                f\"Essential costs escalate by {INFLATION_SPIRAL_ESSENTIAL_ESCALATION:.0%} \"\n                f\"({essential_escalation:,.0f}) and a {INFLATION_SPIRAL_RATE_HIKE * 100:.1f}pp rate hike \"\n                f\"adds {debt_repricing:,.0f} of debt service.\"\n            )\n            notes_cn.append(\n                f\"必要支出上涨 {INFLATION_SPIRAL_ESSENTIAL_ESCALATION:.0%}（{essential_escalation:,.0f}），\"\n                f\"利率上调 {INFLATION_SPIRAL_RATE_HIKE * 100:.1f} 个百分点使债务成本每年增加 \"\n                f\"{debt_repricing:,.0f}。\"\n            )\n            if not debt_repricing:\n                notes.append(\"No debt balance was recorded, so the repricing leg is inert.\")\n                notes_cn.append(\"未记录任何债务余额，重定价部分无效。\")\n        if scenario_id == \"income_concentration\":\n            if total_income > MATERIALITY:\n                notes.append(\n                    f\"The largest income stream provides {income_share:.0%} of household income \"\n                    f\"({primary_income:,.0f}) and stops for {INCOME_CONCENTRATION_MONTHS:.0f} months.\"\n                )\n                notes_cn.append(\n                    f\"最大收入来源占家庭收入的 {income_share:.0%}（{primary_income:,.0f}），\"\n                    f\"中断 {INCOME_CONCENTRATION_MONTHS:.0f} 个月。\"\n                )\n            else:\n                notes.append(\n                    \"No household income was recorded, so concentration cannot be measured and the \"\n                    \"scenario only reflects the cash buffer.\"\n                )\n                notes_cn.append(\n                    \"未记录家庭收入，无法测算收入集中度，本情景只反映现有现金缓冲。\"\n                )\n        if portfolio_loss:\n            notes.append(f\"Portfolio loss of {abs(portfolio_loss):,.0f}.\")\n            notes_cn.append(f\"组合名义损失 {abs(portfolio_loss):,.0f}。\")\n        if not debt_covered:\n            notes.append(\"Mandatory debt service could not be covered.\")\n            notes_cn.append(\"强制债务还款无法覆盖。\")\n        if not notes:\n            notes.append(\"No material balance-sheet impact under this scenario.\")\n            notes_cn.append(\"本情景对资产负债表没有实质影响。\")\n\n        scenarios.append(\n            {\n                \"scenario_id\": scenario_id,\n                \"label\": SCENARIO_LABELS[scenario_id],\n                \"label_cn\": SCENARIO_LABELS_CN[scenario_id],\n                \"portfolio_loss\": portfolio_loss,\n                \"cash_outflow\": round(cash_outflow, 2),\n                \"cash_outflow_breakdown\": {\n                    \"uncovered_medical\": round(uncovered_medical, 2),\n                    \"essential_cost_escalation\": round(essential_escalation, 2),\n                    \"debt_repricing\": round(debt_repricing, 2),\n                },\n                \"income_loss\": round(income_loss, 2),\n                \"survival_days_after\": round(survival_days_after, 2),\n                \"breaches_floor\": breaches_floor,\n                \"debt_service_covered\": debt_covered,\n                \"severity\": _severity(breaches_floor, survival_days_after),\n                \"notes\": \" \".join(notes),\n                \"notes_cn\": \" \".join(notes_cn),\n            }\n        )\n\n    def sort_key(scenario):\n        return (\n            0 if scenario[\"breaches_floor\"] else 1,\n            scenario[\"survival_days_after\"],\n            scenario[\"portfolio_loss\"],\n        )\n\n    worst = min(scenarios, key=sort_key)\n    survival_breach = any(scenario[\"breaches_floor\"] for scenario in scenarios)\n\n    return {\n        \"scenarios\": scenarios,\n        \"scenario_count\": len(scenarios),\n        \"scenario_set_version\": SCENARIO_SET_VERSION,\n        \"worst_scenario_id\": worst[\"scenario_id\"],\n        \"worst_scenario\": worst,\n        \"survival_breach\": survival_breach,\n        \"breach_count\": sum(1 for scenario in scenarios if scenario[\"breaches_floor\"]),\n        \"seed\": seed,\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": f\"deterministic shock application across {len(scenarios)} mandatory scenarios\",\n            \"assumptions\": [\n                \"Shocks are applied to the simulated allocation, not to real holdings.\",\n                \"Medical shock uses the larger of the fixed floor and 1.5x essential annual spending, reduced by recorded health coverage.\",\n                f\"Income interruption assumes {INCOME_LOSS_MONTHS:.0f} months without income with {INCOME_RETENTION_SHARE:.0%} absorbed by other sources.\",\n                \"combined_multi_risk applies crash, rate move, medical and income shocks together.\",\n                f\"inflation_spiral escalates recorded essential spending by {INFLATION_SPIRAL_ESSENTIAL_ESCALATION:.0%} over the horizon and reprices recorded debt balances by {INFLATION_SPIRAL_RATE_HIKE * 100:.1f}pp; the rate hike leg is inert when no debt balance is recorded.\",\n                f\"income_concentration stops the largest recorded income stream for {INCOME_CONCENTRATION_MONTHS:.0f} months; without recorded income the concentration cannot be measured and the scenario states that instead of inventing a share.\",\n                \"Both new scenarios are fail-closed: missing records are reported as unmeasurable, never replaced by an assumption presented as data.\",\n                \"These are scenarios under a fixed model, not forecasts and not real performance.\",\n            ],\n            \"computed_at_utc\": None,\n            \"sources\": [\"docs/INTERFACE_FREEZE_V0_1.md\"],\n        },\n    }\n", "timeline.py": "\"\"\"Verity 危险时间轴 (T-E0-034): 第几个月进入危险区。\n\n把八个强制压力情景与月度现金流趋势合并成一条时间轴，回答唯一的问题：\n「按家庭自己记录的现状，第几个月会进入危险区——即累计可动用现金第一次转负？」\n\n方法不是新建第二套模型：每个情景先构造一个「受压档案变体」（资产冲击、一次性\n未覆盖支出、收入中断、成本与债务重定价都作用在记录值上），然后完全复用\n``engine.trend.compute_monthly_trend`` 做与月度趋势相同的逐月投影（不假设投资\n收益、先息后本、可选支出可压缩），取累计现金第一次为负的月份作为击穿月份。\n\n可追溯性：每个情景写出的组合损失 / 未覆盖支出 / 收入损失与压力快照\n``engine.stress.run_stress_tests`` 用同一公式算出，逐项可比；时间轴还同时给出\n12 个月关口（默认）与 60 个月（上限）投影，回答「12 个月内安全」之后「预计第\n几个月进入危险区」。\n\n失败关闭与既有模块同门：缺收入、缺支出基线、档案损坏一律 ABSTAIN，绝不臆造月份。\n\"\"\"\n\nfrom __future__ import annotations\n\nimport copy\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    SURVIVAL_BREACH_DAYS,\n    DAYS_PER_MONTH,\n    INCOME_CONCENTRATION_MONTHS,\n    INCOME_LOSS_MONTHS,\n    INCOME_RETENTION_SHARE,\n    INFLATION_SPIRAL_ESSENTIAL_ESCALATION,\n    INFLATION_SPIRAL_RATE_HIKE,\n    MATERIALITY,\n    MEDICAL_SHOCK_MINIMUM,\n    MEDICAL_SHOCK_MULTIPLE_OF_ESSENTIAL,\n)\nfrom engine.stress import (\n    INCOME_LOSS_SCENARIOS,\n    SCENARIO_LABELS,\n    SCENARIO_LABELS_CN,\n    SCENARIO_ORDER,\n    SCENARIO_SET_VERSION,\n    SCENARIO_SHOCKS,\n    _currency_exposure,\n    _debt_repricing,\n    _income_concentration,\n)\nfrom engine.trend import (\n    DEFAULT_HORIZON_MONTHS,\n    MAX_HORIZON_MONTHS,\n    MIN_HORIZON_MONTHS,\n    compute_monthly_trend,\n)\n\nLONG_HORIZON_MONTHS = MAX_HORIZON_MONTHS\n\n\ndef _number(value, default=0.0):\n    if isinstance(value, bool) or value is None:\n        return default\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return default\n    if number != number or number in (float(\"inf\"), float(\"-inf\")):\n        return default\n    return number\n\n\ndef _resolve_horizon(horizon_months):\n    months = _number(horizon_months, DEFAULT_HORIZON_MONTHS)\n    months = int(months)\n    return max(MIN_HORIZON_MONTHS, min(MAX_HORIZON_MONTHS, months))\n\n\ndef _scenario_amounts(profile, safety, weights):\n    \"\"\"Actual per-scenario money impact, identical to ``engine.stress`` formulas.\"\"\"\n    portfolio_value = _number(safety.get(\"total_assets\"), 0.0)\n    liquid = _number(safety.get(\"liquid_assets\"), 0.0)\n    daily_burn = _number(safety.get(\"daily_burn\"), 0.0)\n    essential = _number(safety.get(\"survival_burn_annual\"), 0.0)\n\n    fx_share = _currency_exposure(profile)\n    medical_gross = max(\n        MEDICAL_SHOCK_MINIMUM, essential * MEDICAL_SHOCK_MULTIPLE_OF_ESSENTIAL\n    )\n    health_coverage = 0.0\n    for item in profile.get(\"protection\") or []:\n        if isinstance(item, dict) and item.get(\"kind\") == \"health\":\n            health_coverage += max(0.0, _number(item.get(\"coverage\"), 0.0))\n    medical_amount = max(0.0, medical_gross - health_coverage)\n\n    household_debt_repricing = _debt_repricing(profile)\n    primary_income, total_income, income_share = _income_concentration(profile)\n    annual_essential_escalation = round(\n        essential * INFLATION_SPIRAL_ESSENTIAL_ESCALATION, 2\n    )\n\n    amounts = {}\n    for scenario_id in SCENARIO_ORDER:\n        shocks = SCENARIO_SHOCKS[scenario_id]\n        portfolio_loss = 0.0\n        for class_name, shock in shocks.items():\n            portfolio_loss += _number(weights.get(class_name), 0.0) * shock * portfolio_value\n        portfolio_loss = -abs(portfolio_loss) if portfolio_loss < 0 else 0.0\n        portfolio_loss = round(portfolio_loss, 2)\n\n        uncovered_medical = 0.0\n        essential_escalation = 0.0\n        debt_repricing = 0.0\n        if scenario_id in (\"medical_shock\", \"combined_multi_risk\"):\n            uncovered_medical = medical_amount\n        elif scenario_id == \"inflation_spiral\":\n            essential_escalation = annual_essential_escalation\n            debt_repricing = household_debt_repricing\n        cash_outflow = round(uncovered_medical + essential_escalation + debt_repricing, 2)\n\n        if scenario_id == \"fx_change\":\n            portfolio_loss = round(\n                -abs(portfolio_value * fx_share * 0.10) if fx_share > 0 else 0.0, 2\n            )\n\n        months_without_income = (\n            INCOME_LOSS_MONTHS if scenario_id in INCOME_LOSS_SCENARIOS else 0.0\n        )\n        income_loss = 0.0\n        if months_without_income:\n            gross_income_loss = daily_burn * months_without_income * DAYS_PER_MONTH\n            income_loss = gross_income_loss * (1.0 - INCOME_RETENTION_SHARE)\n        elif scenario_id == \"income_concentration\":\n            income_loss = round(\n                primary_income * (INCOME_CONCENTRATION_MONTHS / 12.0), 2\n            )\n\n        amounts[scenario_id] = {\n            \"portfolio_loss\": portfolio_loss,\n            \"cash_outflow\": cash_outflow,\n            \"income_loss\": round(income_loss, 2),\n            \"medical_amount\": uncovered_medical,\n            \"essential_escalation\": essential_escalation,\n            \"debt_repricing\": debt_repricing,\n            \"primary_income\": primary_income,\n            \"total_income\": total_income,\n            \"income_share\": income_share,\n            \"months_without_income\": months_without_income,\n        }\n    return amounts\n\n\ndef _drop_liquid(assets, amount):\n    \"\"\"Reduce the recorded liquid pool (cash / immediate / near) by ``amount``.\"\"\"\n    if amount <= 0 or not isinstance(assets, list):\n        return\n    liquid_rows = [\n        row\n        for row in assets\n        if isinstance(row, dict)\n        and _number(row.get(\"value\"), 0.0) > 0\n        and (\n            row.get(\"kind\") == \"cash\"\n            or row.get(\"liquidity\") in (\"immediate\", \"near\")\n        )\n    ]\n    total = sum(_number(row.get(\"value\"), 0.0) for row in liquid_rows)\n    if total <= MATERIALITY:\n        return\n    remaining = amount\n    for row in liquid_rows:\n        value = _number(row.get(\"value\"), 0.0)\n        cut = min(value, value * remaining / total)\n        row[\"value\"] = round(max(0.0, value - cut), 2)\n        remaining -= cut\n\n\ndef _income_profile_for(months, scenario_id, amounts):\n    \"\"\"Monthly income multipliers for income-loss scenarios (months are 1-based).\"\"\"\n    profile = [1.0] * months\n    if scenario_id not in INCOME_LOSS_SCENARIOS:\n        return profile\n    affected = int(round(amounts[scenario_id][\"months_without_income\"]))\n    for month in range(1, affected + 1):\n        if month <= months:\n            profile[month - 1] = INCOME_RETENTION_SHARE\n    return profile\n\n\ndef _stressed_profile(profile, scenario_id, weights, safety):\n    \"\"\"A deep copy of the profile with one scenario's shocks applied to records.\"\"\"\n    amounts = _scenario_amounts(profile, safety, weights)\n    scenario = amounts[scenario_id]\n    modified = copy.deepcopy(profile if isinstance(profile, dict) else {})\n\n    one_time_drop = abs(scenario[\"portfolio_loss\"])\n    if scenario_id in (\"medical_shock\", \"combined_multi_risk\"):\n        one_time_drop += scenario[\"medical_amount\"]\n    if one_time_drop > 0 and isinstance(modified.get(\"assets\"), list):\n        _drop_liquid(modified[\"assets\"], one_time_drop)\n\n    if scenario_id == \"income_concentration\":\n        members = modified.get(\"members\")\n        if isinstance(members, list):\n            flagged_income = 0.0\n            for member in members:\n                if isinstance(member, dict) and member.get(\"role\") == \"primary_earner\":\n                    flagged_income = max(\n                        flagged_income, _number(member.get(\"annual_income\"), 0.0)\n                    )\n            largest = 0.0\n            for member in members:\n                if isinstance(member, dict):\n                    largest = max(largest, _number(member.get(\"annual_income\"), 0.0))\n            zero_target = max(flagged_income, largest)\n            if zero_target > 0:\n                for member in members:\n                    if (\n                        isinstance(member, dict)\n                        and _number(member.get(\"annual_income\"), 0.0) >= zero_target\n                    ):\n                        member[\"annual_income\"] = 0.0\n\n    if scenario_id == \"inflation_spiral\":\n        essential = _number(modified.get(\"annual_expenses_essential\"), 0.0)\n        if essential > 0:\n            modified[\"annual_expenses_essential\"] = round(\n                essential * (1.0 + INFLATION_SPIRAL_ESSENTIAL_ESCALATION), 2\n            )\n        for liability in modified.get(\"liabilities\") or []:\n            if isinstance(liability, dict) and _number(\n                liability.get(\"balance\"), 0.0\n            ) > 0:\n                liability[\"annual_rate\"] = round(\n                    _number(liability.get(\"annual_rate\"), 0.0)\n                    + INFLATION_SPIRAL_RATE_HIKE,\n                    6,\n                )\n    return modified\n\n\ndef _row_for(scenario_id, trend_result, amounts, horizon):\n    \"\"\"Build one timeline row from a stress-tuned monthly trend projection.\"\"\"\n    scenario = amounts[scenario_id]\n    row = {\n        \"scenario_id\": scenario_id,\n        \"label\": SCENARIO_LABELS[scenario_id],\n        \"label_cn\": SCENARIO_LABELS_CN[scenario_id],\n        \"portfolio_loss\": scenario[\"portfolio_loss\"],\n        \"cash_outflow\": scenario[\"cash_outflow\"],\n        \"income_loss\": scenario[\"income_loss\"],\n        \"status\": \"OK\",\n        \"status_reason\": \"\",\n        \"reason_codes\": [],\n        \"breach_in_months\": None,\n        \"within_horizon\": False,\n        \"beyond_horizon_breach_month\": None,\n        \"end_runway_days\": None,\n        \"end_buffer_days_no_income\": None,\n        \"breach_buffer_days_no_income\": None,\n        \"notes_cn\": \"\",\n    }\n\n    if trend_result.get(\"status\") != \"OK\":\n        row[\"status\"] = \"ABSTAIN\"\n        row[\"status_reason\"] = trend_result.get(\"status_reason\", \"按失败关闭。\")\n        row[\"reason_codes\"] = list(trend_result.get(\"reason_codes\") or [])\n        row[\"notes_cn\"] = row[\"status_reason\"]\n        return row\n\n    monthly = trend_result.get(\"monthly\") or []\n    summary = trend_result.get(\"summary\") or {}\n    # 单一来源击穿判定（T-E0-045 / H-05）：与生存底线同一条尺子。trend 内部使用\n    # engine.layering.is_survival_breach，这里只消费它算出的月份，不再自建「现金转负」口径。\n    breach = summary.get(\"first_breach_month\")\n    if breach is None:\n        breach = summary.get(\"first_negative_cash_month\")\n    if breach is not None:\n        breach = int(breach)\n    row[\"breach_in_months\"] = breach\n    row[\"within_horizon\"] = breach is not None and breach <= horizon\n    runway = monthly[-1].get(\"runway_days\") if monthly else None\n    row[\"end_runway_days\"] = None if runway is None else round(runway, 2)\n    # 只有这个量参与击穿判定（与 safety.safety_days 同源同义）。\n    end_buffer = monthly[-1].get(\"buffer_days_no_income\") if monthly else None\n    row[\"end_buffer_days_no_income\"] = None if end_buffer is None else round(end_buffer, 2)\n    if breach is not None and 1 <= breach <= len(monthly):\n        at_breach = monthly[breach - 1].get(\"buffer_days_no_income\")\n        row[\"breach_buffer_days_no_income\"] = None if at_breach is None else round(at_breach, 2)\n\n    notes = []\n    if row[\"portfolio_loss\"]:\n        notes.append(f\"组合损失 {abs(row['portfolio_loss']):,.0f}\")\n    if row[\"cash_outflow\"]:\n        notes.append(f\"未覆盖／额外支出 {row['cash_outflow']:,.0f}\")\n    if row[\"income_loss\"]:\n        notes.append(f\"收入损失 {row['income_loss']:,.0f}\")\n    if scenario[\"income_share\"] > 0 and scenario_id == \"income_concentration\":\n        notes.append(\n            f\"最大收入来源占家庭收入 {scenario['income_share']:.0%}\"\n            f\"（{scenario['primary_income']:,.0f}）\"\n        )\n\n    if breach is not None:\n        at_breach = row[\"breach_buffer_days_no_income\"]\n        notes.append(\n            f\"第 {breach} 个月击穿生存底线\"\n            f\"（该月期初可动用现金覆盖天数 {at_breach:,.1f} 天，不含未来收入；生存底线 {SURVIVAL_BREACH_DAYS:,.0f} 天）\"\n            if at_breach is not None\n            else f\"第 {breach} 个月击穿生存底线\"\n        )\n    else:\n        notes.append(\n            f\"{horizon} 个月内未击穿生存底线\"\n            f\"（每月期初可动用现金覆盖天数都不低于生存底线 {SURVIVAL_BREACH_DAYS:,.0f} 天；\"\n            f\"期末 {row['end_buffer_days_no_income']:,.1f} 天，不含未来收入）\"\n            if row[\"end_buffer_days_no_income\"] is not None\n            else f\"{horizon} 个月内未击穿生存底线\"\n        )\n        if row[\"end_buffer_days_no_income\"] is not None and row[\"end_buffer_days_no_income\"] <= 0.5:\n            notes.append(\"期末可动用现金为零，无缓冲\")\n    row[\"notes_cn\"] = \"；\".join(notes) if notes else \"本情景对现金时间轴没有实质影响。\"\n    return row\n\n\ndef compute_stress_timeline(profile, safety, allocation, horizon_months=DEFAULT_HORIZON_MONTHS):\n    \"\"\"Merge the eight stress scenarios with the monthly trend into a breach timeline.\n\n    Never raises and never guesses: missing evidence produces ABSTAIN rows and the\n    whole module abstains when no scenario can be projected.\n    \"\"\"\n    profile = profile if isinstance(profile, dict) else {}\n    safety = safety if isinstance(safety, dict) else {}\n    allocation = allocation if isinstance(allocation, dict) else {}\n    horizon = _resolve_horizon(horizon_months)\n\n    weights = allocation.get(\"allocation_weights\") or {}\n    if not weights:\n        weights = {name: 0.0 for name in SCENARIO_SHOCKS[\"equity_crash\"]}\n\n    amounts = _scenario_amounts(profile, safety, weights)\n    # 与 safety.safety_days 同源同量、同量测点的「基准轨」月份：不施加任何情景冲击时，\n    # 第几个月开始击穿。情景轨可以更早（冲击本身就会击穿），两者不得互相冒充。\n    base_summary = compute_monthly_trend(profile, horizon).get(\"summary\") or {}\n    base_breach_month = base_summary.get(\"first_breach_month\")\n\n    rows = []\n    for scenario_id in SCENARIO_ORDER:\n        stressed = _stressed_profile(profile, scenario_id, weights, safety)\n        income_profile = None\n        if scenario_id in INCOME_LOSS_SCENARIOS:\n            income_profile = _income_profile_for(horizon, scenario_id, amounts)\n\n        trend_result = compute_monthly_trend(\n            stressed,\n            horizon,\n            income_profile=income_profile,\n        )\n        row = _row_for(scenario_id, trend_result, amounts, horizon)\n\n        if row[\"status\"] == \"OK\" and row[\"breach_in_months\"] is None:\n            long_profile = None\n            if scenario_id in INCOME_LOSS_SCENARIOS:\n                long_profile = _income_profile_for(\n                    LONG_HORIZON_MONTHS, scenario_id, amounts\n                )\n            long_trend = compute_monthly_trend(\n                stressed,\n                LONG_HORIZON_MONTHS,\n                income_profile=long_profile,\n            )\n            if long_trend.get(\"status\") == \"OK\":\n                beyond = long_trend.get(\"summary\", {}).get(\"first_breach_month\")\n                if beyond is None:\n                    beyond = long_trend.get(\"summary\", {}).get(\"first_negative_cash_month\")\n                if beyond is not None:\n                    beyond = int(beyond)\n                    if beyond > horizon:\n                        row[\"beyond_horizon_breach_month\"] = beyond\n                    elif beyond <= horizon:\n                        row[\"breach_in_months\"] = beyond\n                        row[\"within_horizon\"] = True\n                        row[\"notes_cn\"] = f\"第 {beyond} 个月击穿现金底线\"\n\n        rows.append(row)\n\n    okay_rows = [row for row in rows if row[\"status\"] == \"OK\"]\n    breach_rows = [row for row in rows if row.get(\"within_horizon\")]\n    earliest = (\n        min(breach_rows, key=lambda row: row[\"breach_in_months\"]) if breach_rows else None\n    )\n\n    total_status = \"OK\" if okay_rows else \"ABSTAIN\"\n    if total_status == \"ABSTAIN\":\n        reason = \"所有压力情景都无法投影（缺收入或缺少支出基线），危险时间轴按失败关闭。\"\n        codes = sorted({code for row in rows for code in row[\"reason_codes\"]})\n    else:\n        reason = (\n            f\"把家庭自己记录的收入与支出放入 {len(SCENARIO_ORDER)} 个压力情景，\"\n            f\"逐月投影 {LONG_HORIZON_MONTHS} 个月（不假设投资收益），\"\n            f\"给出每个情景第几个月击穿现金底线。\"\n        )\n        codes = []\n\n    return {\n        \"status\": total_status,\n        \"status_reason\": reason,\n        \"reason_codes\": codes,\n        \"horizon_months\": horizon,\n        \"long_horizon_months\": LONG_HORIZON_MONTHS,\n        \"return_assumption\": \"none\",\n        \"scenario_set_version\": SCENARIO_SET_VERSION,\n        \"rows\": rows,\n        \"summary\": {\n            \"earliest_breach_month\": earliest[\"breach_in_months\"] if earliest else None,\n            \"earliest_breach_scenario_id\": earliest[\"scenario_id\"] if earliest else None,\n            \"earliest_breach_scenario_label_cn\": earliest[\"label_cn\"] if earliest else None,\n            \"breach_count_within_horizon\": len(breach_rows),\n            \"base_breach_month\": base_breach_month,\n            \"base_breach_measured_on\": base_summary.get(\"breach_measured_on\"),\n            \"base_breach_buffer_days_no_income_opening_month_1\": base_summary.get(\n                \"buffer_days_no_income_start\"\n            ),\n            \"scenario_count\": len(rows),\n            \"horizon_months\": horizon,\n        },\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": (\n                \"Each of the eight mandatory scenarios builds a stressed copy of the \"\n                \"household profile, then the same monthly no-return trend projection \"\n                \"runs on it; the breach month is the first month cumulative cash goes \"\n                \"negative. Money impact per scenario uses the same formulas as the \"\n                \"stress snapshot.\"\n            ),\n            \"assumptions\": [\n                \"The timeline is a projection of recorded facts, not a forecast.\",\n                \"Breach is the single engine-wide ruler: the first month whose OPENING no-future-income \"\n                \"buffer days fall below SURVIVAL_BREACH_DAYS (engine.layering.survival_buffer_days + \"\n                \"is_survival_breach); month 1's opening buffer is bit-for-bit engine.safety:safety_days.\",\n                \"trend.monthly[].runway_days (cash plus projected income) is display only and is never \"\n                \"compared against the survival floor.\",\n                \"Recorded rigid future outflows are deducted in the month they fall due \"\n                \"(engine.layering.rigid_outflow_schedule); a rigid outflow without a recorded due year \"\n                \"is never guessed and marks the evidence NOT_VERIFIED.\",\n                \"No investment return is assumed anywhere; non-cash assets are carried at recorded value.\",\n                \"Income-loss scenarios shape monthly income for the affected months only (interruption: 3 months at the retention share; concentration: the largest stream stops for 12 months).\",\n                \"inflation_spiral escalates recorded essential spending and reprices recorded debt; both legs are inert when nothing is recorded.\",\n                \"A scenario whose one-time shock exceeds the recorded liquid pool breaches in month 1.\",\n                \"Missing evidence refuses with ABSTAIN instead of guessing a month.\",\n            ],\n            \"sources\": [\n                \"docs/INTERFACE_FREEZE_V0_1.md\",\n                \"engine/trend.py\",\n                \"engine/stress.py\",\n            ],\n        },\n    }\n", "today.py": "\"\"\"Verity Today.\n\nOne screen, one decision: what should this family do today? The answer is allowed to be\n\"HOLD\", and it is allowed to be \"ABSTAIN\". A product that always finds something to sell\nis not a wealth outcome system.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom engine.constants import (\n    ALGORITHM_VERSION,\n    ASSET_CLASSES,\n    BENCHMARK_60_40_RETURN,\n    REBALANCE_DRIFT_THRESHOLD,\n    REVIEW_SURVIVAL_DAYS,\n    UNDERINVESTED_GROWTH_FRACTION,\n)\n\nACTIONS = (\n    \"INCREASE_ALLOCATION\",\n    \"REDUCE_RISK\",\n    \"HEDGE\",\n    \"REBALANCE\",\n    \"HOLD\",\n    \"ABSTAIN\",\n)\n\nACTION_MEANING = {\n    \"INCREASE_ALLOCATION\": \"Put more of the balance sheet to work; the growth layer is starved.\",\n    \"REDUCE_RISK\": \"Cut risk until the survival buffer clears its threshold.\",\n    \"HEDGE\": \"Buy protection, because a stress scenario breaks the survival floor.\",\n    \"REBALANCE\": \"Realign holdings with the policy allocation; drift is material.\",\n    \"HOLD\": \"Do nothing today. The plan is already inside the family's constraints.\",\n    \"ABSTAIN\": \"No action is issued because Verity cannot stand behind a recommendation.\",\n}\n\n#: Maps a recorded asset kind onto an allocation class.\nKIND_TO_CLASS = {\n    \"cash\": \"cash\",\n    \"bond\": \"bond\",\n    \"global_index\": \"global_index\",\n    \"equity\": \"equity\",\n    \"gold\": \"gold\",\n    \"option_protection\": \"option_protection\",\n    \"insurance_linked\": \"bond\",\n    \"illiquid\": \"equity\",\n}\n\n\ndef _number(value, default=0.0):\n    if isinstance(value, bool) or value is None:\n        return default\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return default\n    if number != number or number in (float(\"inf\"), float(\"-inf\")):\n        return default\n    return number\n\n\ndef _clamp(value, low, high):\n    return max(low, min(high, value))\n\n\ndef _current_weights(profile):\n    \"\"\"Where the family's money actually sits today.\"\"\"\n    totals = {name: 0.0 for name in ASSET_CLASSES}\n    for asset in profile.get(\"assets\") or []:\n        if not isinstance(asset, dict):\n            continue\n        value = max(0.0, _number(asset.get(\"value\"), 0.0))\n        if value <= 0:\n            continue\n        target_class = KIND_TO_CLASS.get(asset.get(\"kind\"))\n        if target_class is None:\n            target_class = \"bond\" if asset.get(\"liquidity\") == \"near\" else \"cash\"\n        totals[target_class] += value\n    grand_total = sum(totals.values())\n    if grand_total <= 0:\n        return {name: 0.0 for name in ASSET_CLASSES}\n    return {name: totals[name] / grand_total for name in ASSET_CLASSES}\n\n\ndef build_today(profile, safety, feasibility, allocation, stress):\n    \"\"\"Produce the single daily decision for one household.\"\"\"\n    profile = profile if isinstance(profile, dict) else {}\n    safety = safety if isinstance(safety, dict) else {}\n    feasibility = feasibility if isinstance(feasibility, dict) else {}\n    allocation = allocation if isinstance(allocation, dict) else {}\n    stress = stress if isinstance(stress, dict) else {}\n\n    verdict = feasibility.get(\"verdict\", \"ABSTAIN\")\n    safety_days = _number(safety.get(\"safety_days\"), 0.0)\n    total_assets = _number(safety.get(\"total_assets\"), 0.0)\n    tolerance = _number(profile.get(\"max_tolerable_loss_pct\"), None)\n\n    simulated_return = allocation.get(\"simulated_annual_return\")\n    simulated_return = _number(simulated_return, None)\n    required_return = _number(feasibility.get(\"required_return_for_goal\"), None)\n\n    target_weights = allocation.get(\"allocation_weights\") or {}\n    if not target_weights:\n        target_weights = {name: 0.0 for name in ASSET_CLASSES}\n\n    # The growth pool is everything held in return-seeking assets. Option protection is a\n    # hedge, not growth, so it is excluded.\n    growth_fraction = sum(\n        _number(target_weights.get(name), 0.0)\n        for name in (\"global_index\", \"equity\", \"gold\")\n    )\n\n    current_weights = _current_weights(profile)\n    drift = max(\n        (abs(_number(target_weights.get(name), 0.0) - _number(current_weights.get(name), 0.0))\n         for name in ASSET_CLASSES),\n        default=0.0,\n    )\n\n    survival_breach = bool(stress.get(\"survival_breach\"))\n\n    # --- ordered action precedence (contract §3) ---\n    reason_parts = []\n    if verdict in (\"REFUSE\", \"ABSTAIN\"):\n        action = \"ABSTAIN\"\n        reason_parts.append(f\"Feasibility verdict is {verdict}, so no action is issued.\")\n        reasons = feasibility.get(\"reasons\") or []\n        if reasons:\n            reason_parts.append(reasons[0])\n    elif survival_breach:\n        action = \"HEDGE\"\n        worst = stress.get(\"worst_scenario\") or {}\n        reason_parts.append(\n            \"Stress scenario '{}' breaks the survival floor ({} days remaining).\".format(\n                stress.get(\"worst_scenario_id\"), _number(worst.get(\"survival_days_after\"), 0.0)\n            )\n        )\n    elif safety_days < REVIEW_SURVIVAL_DAYS:\n        action = \"REDUCE_RISK\"\n        reason_parts.append(\n            f\"Safety days {safety_days:.1f} are below the {REVIEW_SURVIVAL_DAYS}-day threshold.\"\n        )\n    elif growth_fraction < UNDERINVESTED_GROWTH_FRACTION:\n        action = \"INCREASE_ALLOCATION\"\n        reason_parts.append(\n            f\"Only {growth_fraction:.0%} of the balance sheet is working for long-term goals.\"\n        )\n    elif drift > REBALANCE_DRIFT_THRESHOLD:\n        action = \"REBALANCE\"\n        reason_parts.append(\n            f\"Holdings drift {drift:.1%} from the policy allocation, above the \"\n            f\"{REBALANCE_DRIFT_THRESHOLD:.0%} threshold.\"\n        )\n    else:\n        action = \"HOLD\"\n        reason_parts.append(\"Holdings sit inside the policy band; no action is warranted today.\")\n\n    # --- scenario-implied goal probability (explicitly not a forecast) ---\n    if simulated_return is None or required_return is None:\n        goal_probability = None\n    else:\n        gap = simulated_return - required_return\n        base = 0.5 + gap * 1.5\n        if survival_breach:\n            base *= 0.6\n        if safety_days < REVIEW_SURVIVAL_DAYS:\n            base *= 0.8\n        if verdict == \"REFUSE\":\n            base *= 0.5\n        goal_probability = round(_clamp(base, 0.02, 0.95), 4)\n\n    if total_assets <= 0:\n        wealth_change_pct = None\n    else:\n        wealth_change_pct = simulated_return\n\n    relative_to_benchmark = (\n        None if simulated_return is None else round(simulated_return - BENCHMARK_60_40_RETURN, 6)\n    )\n\n    return {\n        \"wealth_value\": round(total_assets, 2),\n        \"wealth_change_pct\": wealth_change_pct,\n        \"safety_days\": round(safety_days, 2),\n        \"goal_probability\": goal_probability,\n        \"benchmark_60_40_return\": BENCHMARK_60_40_RETURN,\n        \"relative_to_benchmark\": relative_to_benchmark,\n        \"drift\": round(drift, 6),\n        \"growth_fraction\": round(growth_fraction, 6),\n        \"action\": action,\n        \"action_meaning\": ACTION_MEANING[action],\n        \"action_reason\": \" \".join(reason_parts),\n        \"action_is_final\": action != \"ABSTAIN\",\n        \"evidence\": {\n            \"algorithm_version\": ALGORITHM_VERSION,\n            \"method\": \"ordered decision precedence over feasibility, stress, buffer and drift\",\n            \"assumptions\": [\n                \"goal_probability is scenario-implied, not a forecast and not a promise.\",\n                \"The 60/40 benchmark return is a fixed documented constant, not a live index.\",\n                \"Drift compares current holdings with the policy allocation.\",\n                \"ABSTAIN is a legitimate daily answer.\",\n            ],\n            \"computed_at_utc\": None,\n            \"sources\": [\"docs/INTERFACE_FREEZE_V0_1.md\"],\n        },\n    }\n", "trend.py": "\"\"\"Household monthly cash-flow and balance-sheet trend (现金流与资产负债多月度趋势).\n\nAnswers one question the single-period snapshot cannot: *is this family getting\nsafer or less safe as the months pass?*\n\nThe module is deliberately a **projection of recorded facts only**, never a\nforecast:\n\n  * no investment return is assumed anywhere — every non-cash asset is carried at\n    its recorded value for the whole horizon (``return_assumption: \"none\"``);\n  * income is the household's own recorded annual income spread evenly, not a\n    model of raises, bonuses or job loss;\n  * debt service is the recorded ``mandatory_payment`` (annual) split into\n    interest (balance x annual_rate / 12) and principal; when the recorded\n    payment cannot cover the interest the balance grows and the month is flagged\n    ``negative_amortization`` — the engine never silently \"fixes\" a family's debt;\n  * discretionary spending is compressible; it is only taken out of the month's\n    surplus, so a family in deficit sees the squeeze explicitly;\n  * the cash pool starts from the same liquid assets ``engine.safety`` counts.\n\nMissing evidence refuses with ABSTAIN (fail-closed) instead of guessing.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom engine.constants import ALGORITHM_VERSION, DAYS_PER_MONTH\nfrom engine.layering import (\n    SURVIVAL_BREACH_DAYS,\n    is_survival_breach,\n    survival_buffer_days,\n    rigid_outflow_due_by_month,\n    rigid_outflow_schedule,\n    rigid_outflow_split,\n)\n\n#: Horizon bounds. 12 months is the product default; 60 is the hard ceiling.\nDEFAULT_HORIZON_MONTHS = 12\nMIN_HORIZON_MONTHS = 1\nMAX_HORIZON_MONTHS = 60\n\n#: Emergency reserve target expressed in months of unavoidable outflow.\nEMERGENCY_RESERVE_MONTHS = 6.0\n\nTREND_IMPROVING = \"IMPROVING\"\nTREND_STABLE = \"STABLE\"\nTREND_DETERIORATING = \"DETERIORATING\"\nTREND_ABSTAIN = \"ABSTAIN\"\n\n#: A month-to-month net-worth drift below this share of annual income is \"flat\".\nSTABLE_DRIFT_SHARE_OF_INCOME = 0.01\nMATERIALITY = 1e-9\n\nASSUMPTIONS = [\n    \"Trend is a projection of recorded facts, not a forecast.\",\n    \"No investment return is assumed: non-cash assets are carried at recorded value.\",\n    \"Annual income is spread evenly across the horizon; no raise, bonus or income loss is modelled.\",\n    \"Debt service is the recorded annual mandatory_payment, split into interest then principal.\",\n    \"Discretionary spending is compressible and only taken from the month's surplus.\",\n    \"The breach ruler compares the no-future-income cash buffer days against the engine-wide \"\n    \"survival floor; the income-inclusive runway is display only and is never compared to it.\",\n    \"The no-future-income cash track assumes income stops today: it deducts essential spending, \"\n    \"mandatory debt service and recorded rigid outflows, and it is the only track compared to \"\n    \"the survival floor.\",\n    \"Recorded rigid future outflows (for example education) are unavoidable and are deducted \"\n    \"in the month they fall due, whatever their time to maturity.\",\n]\n\n\ndef _number(value, default=None):\n    if isinstance(value, bool) or value is None:\n        return default\n    try:\n        number = float(value)\n    except (TypeError, ValueError):\n        return default\n    if number != number or number in (float(\"inf\"), float(\"-inf\")):\n        return default\n    return number\n\n\ndef _money(value):\n    \"\"\"Round to cents so JSON output is stable and comparable.\"\"\"\n    return round(float(value) + 0.0, 2)\n\n\ndef _gross_annual_income(profile):\n    total = 0.0\n    for member in profile.get(\"members\") or []:\n        if isinstance(member, dict):\n            total += max(0.0, _number(member.get(\"annual_income\"), 0.0))\n    return total\n\n\ndef _liquid_cash(profile):\n    \"\"\"Liquid pool, defined exactly as ``engine.safety`` defines it.\"\"\"\n    liquid = 0.0\n    for asset in profile.get(\"assets\") or []:\n        if not isinstance(asset, dict):\n            continue\n        value = _number(asset.get(\"value\"), 0.0)\n        if value <= 0:\n            continue\n        if asset.get(\"kind\") == \"cash\" or asset.get(\"liquidity\") in (\"immediate\", \"near\"):\n            liquid += value\n    return liquid\n\n\ndef _total_assets(profile):\n    total = 0.0\n    for asset in profile.get(\"assets\") or []:\n        if isinstance(asset, dict):\n            total += max(0.0, _number(asset.get(\"value\"), 0.0))\n    return total\n\n\ndef _debts(profile):\n    debts = []\n    for liability in profile.get(\"liabilities\") or []:\n        if not isinstance(liability, dict):\n            continue\n        balance = max(0.0, _number(liability.get(\"balance\"), 0.0))\n        debts.append(\n            {\n                \"kind\": liability.get(\"kind\"),\n                \"balance\": balance,\n                \"annual_rate\": max(0.0, _number(liability.get(\"annual_rate\"), 0.0)),\n                \"annual_payment\": max(0.0, _number(liability.get(\"mandatory_payment\"), 0.0)),\n            }\n        )\n    return debts\n\n\ndef _evidence(extra=None):\n    block = {\n        \"algorithm_version\": ALGORITHM_VERSION,\n        \"sources\": [\"engine.safety:liquid_asset_definition\"],\n        \"assumptions\": list(ASSUMPTIONS),\n    }\n    if extra:\n        block.update(extra)\n    return block\n\n\ndef _abstain(reason_code, reason, *, horizon_months=DEFAULT_HORIZON_MONTHS):\n    return {\n        \"status\": TREND_ABSTAIN,\n        \"status_reason\": reason,\n        \"reason_codes\": [reason_code],\n        \"horizon_months\": horizon_months,\n        \"return_assumption\": \"none\",\n        \"assumptions\": list(ASSUMPTIONS),\n        \"monthly\": [],\n        \"summary\": {},\n        \"evidence\": _evidence({\"inputs_digest_pending\": True}),\n    }\n\n\ndef _resolve_horizon(horizon_months):\n    months = _number(horizon_months, DEFAULT_HORIZON_MONTHS)\n    months = int(months) if months is not None else DEFAULT_HORIZON_MONTHS\n    return max(MIN_HORIZON_MONTHS, min(MAX_HORIZON_MONTHS, months))\n\n\ndef _income_factor(income_profile, month):\n    \"\"\"Monthly income multiplier for income-shaping scenarios (1-based month).\"\"\"\n    if not isinstance(income_profile, (list, tuple)):\n        return 1.0\n    index = month - 1\n    if index < 0 or index >= len(income_profile):\n        return 1.0\n    value = _number(income_profile[index], 1.0)\n    if value <= 0:\n        return 0.0\n    return value\n\n\ndef _first_breach_month(months):\n    \"\"\"单一来源击穿判定：第一个「现金覆盖天数（不含未来收入）」跌破生存底线的月份。\n\n    T-E0-045 / H-05 复测退回项：被比较的量必须与 ``safety.safety_days`` 同源同义。\n    含未来收入的 ``runway_days`` 只能展示，绝不能作为击穿依据 —— 它会被还没到账的\n    收入抬高，掩盖真实的现金缺口。\n    \"\"\"\n    for row in months:\n        # 量测点对齐（T-E0-045 复测退回项 2）：只看每月**期初**缓冲，第 1 个月的期初\n        # 缓冲逐位等于 safety.safety_days；绝不能拿「扣掉当月支出之后的期末读数」判定。\n        if is_survival_breach(row.get(\"buffer_days_no_income\")):\n            return row[\"month\"]\n    return None\n\n\ndef compute_monthly_trend(\n    profile,\n    horizon_months=DEFAULT_HORIZON_MONTHS,\n    income_profile=None,\n):\n    \"\"\"Project recorded cash flow and the balance sheet month by month.\n\n    ``income_profile`` (optional) is a list of monthly income multipliers over the\n    horizon (month 1 first); scenario timelines use it to shape income for the\n    affected months only. Defaults to ``None`` (income spread evenly), so existing\n    callers and outputs are unchanged.\n\n    Returns a dict with ``status`` ``OK`` or ``ABSTAIN``. Never raises.\n    \"\"\"\n    if not isinstance(profile, dict):\n        return _abstain(\"PROFILE_NOT_A_MAPPING\", \"家庭档案格式不可用，趋势计算按失败关闭。\")\n\n    horizon = _resolve_horizon(horizon_months)\n\n    income_annual = _gross_annual_income(profile)\n    essential_annual = max(0.0, _number(profile.get(\"annual_expenses_essential\"), 0.0))\n    discretionary_annual = max(0.0, _number(profile.get(\"annual_expenses_discretionary\"), 0.0))\n    debts = _debts(profile)\n    debt_service_annual = sum(item[\"annual_payment\"] for item in debts)\n\n    monthly_income = income_annual / 12.0\n    monthly_essential = essential_annual / 12.0\n    monthly_discretionary = discretionary_annual / 12.0\n    monthly_debt_service = debt_service_annual / 12.0\n    monthly_unavoidable = monthly_essential + monthly_debt_service\n\n    if income_annual <= 0:\n        return _abstain(\n            \"NO_INCOME_RECORDED\",\n            \"没有记录任何家庭成员收入，无法判断家庭的现金流走向，Verity 拒绝给出趋势结论。\",\n            horizon_months=horizon,\n        )\n    if monthly_unavoidable <= 0:\n        return _abstain(\n            \"NO_OUTFLOW_BASELINE\",\n            \"既没有记录必要支出，也没有记录强制还款，没有可比较的支出基线，Verity 拒绝给出趋势结论。\",\n            horizon_months=horizon,\n        )\n\n    rigid_schedule = rigid_outflow_schedule(profile, horizon)\n    rigid_due_by_month = rigid_outflow_due_by_month(profile, horizon)\n    unscheduled_rigid = rigid_outflow_split(profile)[\"unscheduled\"]\n\n    liquid_start = _liquid_cash(profile)\n    other_assets = max(0.0, _total_assets(profile) - liquid_start)\n    debt_balances = [item[\"balance\"] for item in debts]\n    debt_start = sum(debt_balances)\n\n    emergency_target = monthly_unavoidable * EMERGENCY_RESERVE_MONTHS\n\n    months = []\n    cash = liquid_start\n    # 「不含未来收入」的独立现金轨：与 engine.safety.safety_days 同源同义 ——\n    # 假设收入从今天起停止，只扣必要支出、强制还款与已记录刚性支出（可选支出可压缩），\n    # 这条轨的读数才是可以与生存底线比较的量。\n    cash_no_income = liquid_start\n    months_to_reserve = None\n    months_to_debt_free = None\n    negative_amortization_months = []\n    deficit_months = []\n    first_negative_cash_month = None\n\n    for month in range(1, horizon + 1):\n        income_factor = _income_factor(income_profile, month)\n        monthly_income_row = monthly_income * income_factor\n        # --- debt: interest first, then principal; never assume recapitalisation\n        interest = 0.0\n        scheduled = 0.0\n        for index, item in enumerate(debts):\n            balance = debt_balances[index]\n            if balance <= MATERIALITY:\n                debt_balances[index] = 0.0\n                continue\n            month_interest = balance * item[\"annual_rate\"] / 12.0\n            payment = min(item[\"annual_payment\"] / 12.0, balance + month_interest)\n            interest += month_interest\n            scheduled += payment\n            debt_balances[index] = balance + month_interest - payment\n\n        total_debt = sum(debt_balances)\n        if scheduled + MATERIALITY < interest:\n            negative_amortization_months.append(month)\n\n        # --- cash flow: discretionary is compressible, essential and debt are not\n        surplus_before_discretionary = monthly_income_row - monthly_essential - scheduled\n        discretionary_actual = min(monthly_discretionary, max(0.0, surplus_before_discretionary))\n        rigid_outflow = rigid_due_by_month.get(month, 0.0)\n        net_cash_flow = surplus_before_discretionary - discretionary_actual - rigid_outflow\n        cash += net_cash_flow\n        if net_cash_flow < -MATERIALITY:\n            deficit_months.append(month)\n        if cash < -MATERIALITY and first_negative_cash_month is None:\n            first_negative_cash_month = month\n\n        total_assets = max(0.0, cash) + other_assets\n        net_worth = total_assets - total_debt\n        monthly_buffer_outflow = monthly_essential + scheduled + discretionary_actual\n        runway_days = (\n            (max(0.0, cash) / monthly_buffer_outflow) * DAYS_PER_MONTH\n            if monthly_buffer_outflow > MATERIALITY\n            else None\n        )\n        # 与 engine.safety.safety_days 同源同义、且量测点相同的量：本月的**期初**缓冲\n        # （收入停止后的现金覆盖天数）。第 1 个月的期初现金就是 safety 用的 liquid。\n        buffer_days_no_income = survival_buffer_days(cash_no_income, essential_annual)\n        cash_no_income -= monthly_essential + scheduled + rigid_outflow\n        closing_buffer_days_no_income = survival_buffer_days(cash_no_income, essential_annual)\n\n        if months_to_reserve is None and cash >= emergency_target:\n            months_to_reserve = month\n        if debt_start > MATERIALITY and months_to_debt_free is None and total_debt <= MATERIALITY:\n            months_to_debt_free = month\n\n        months.append(\n            {\n                \"month\": month,\n                \"income\": _money(monthly_income_row),\n                \"essential_outflow\": _money(monthly_essential),\n                \"debt_interest\": _money(interest),\n                \"debt_service\": _money(scheduled),\n                \"discretionary_planned\": _money(monthly_discretionary),\n                \"discretionary_actual\": _money(discretionary_actual),\n                \"rigid_outflow\": _money(rigid_outflow),\n                \"net_cash_flow\": _money(net_cash_flow),\n                \"cumulative_cash\": _money(cash),\n                \"total_assets\": _money(total_assets),\n                \"total_debt\": _money(total_debt),\n                \"net_worth\": _money(net_worth),\n                \"runway_days\": None if runway_days is None else round(runway_days, 2),\n                \"buffer_days_no_income\": (\n                    None if buffer_days_no_income is None else round(buffer_days_no_income, 2)\n                ),\n                \"closing_buffer_days_no_income\": (\n                    None\n                    if closing_buffer_days_no_income is None\n                    else round(closing_buffer_days_no_income, 2)\n                ),\n                \"cash_no_income\": _money(cash_no_income),\n                \"negative_amortization\": scheduled + MATERIALITY < interest,\n                \"deficit\": net_cash_flow < -MATERIALITY,\n            }\n        )\n\n    cash_end = cash\n    net_worth_start = liquid_start + other_assets - debt_start\n    net_worth_end = months[-1][\"net_worth\"]\n    net_worth_change = net_worth_end - net_worth_start\n\n    stable_band = max(MATERIALITY, abs(income_annual) * STABLE_DRIFT_SHARE_OF_INCOME)\n    if abs(net_worth_change) <= stable_band:\n        trend_status = TREND_STABLE\n    elif net_worth_change > 0:\n        trend_status = TREND_IMPROVING\n    else:\n        trend_status = TREND_DETERIORATING\n\n    return {\n        \"status\": \"OK\",\n        \"status_reason\": (\n            f\"按家庭自己记录的收入与支出展开 {horizon} 个月；不假设任何投资收益，\"\n            \"只用现金结余累积与债务摊还推动资产负债变化。\"\n            + (\"收入按情景形状逐月调整。\" if income_profile else \"\"),\n        ),\n        \"reason_codes\": [],\n        \"horizon_months\": horizon,\n        \"return_assumption\": \"none\",\n        \"assumptions\": list(ASSUMPTIONS),\n        \"income_profile_applied\": bool(income_profile),\n        \"monthly\": months,\n        \"summary\": {\n            \"currency\": profile.get(\"currency\"),\n            \"monthly_income\": _money(monthly_income),\n            \"monthly_essential_outflow\": _money(monthly_essential),\n            \"monthly_debt_service\": _money(monthly_debt_service),\n            \"monthly_discretionary_planned\": _money(monthly_discretionary),\n            \"monthly_unavoidable_outflow\": _money(monthly_unavoidable),\n            \"monthly_net_surplus\": _money(monthly_income - monthly_unavoidable),\n            \"cash_start\": _money(liquid_start),\n            \"cash_end\": _money(cash_end),\n            \"total_assets_start\": _money(liquid_start + other_assets),\n            \"total_assets_end\": _money(months[-1][\"total_assets\"]),\n            \"total_debt_start\": _money(debt_start),\n            \"total_debt_end\": _money(months[-1][\"total_debt\"]),\n            \"net_worth_start\": _money(net_worth_start),\n            \"net_worth_end\": _money(net_worth_end),\n            \"net_worth_change\": _money(net_worth_change),\n            \"emergency_reserve_target\": _money(emergency_target),\n            \"emergency_reserve_months\": EMERGENCY_RESERVE_MONTHS,\n            \"months_to_emergency_reserve\": months_to_reserve,\n            \"months_to_debt_free\": months_to_debt_free,\n            \"deficit_months\": deficit_months,\n            \"negative_amortization_months\": negative_amortization_months,\n            \"first_negative_cash_month\": first_negative_cash_month,\n            \"breach_definition\": \"survival_buffer_days_without_future_income_below_floor\",\n            \"breach_measured_on\": \"buffer_days_no_income\",\n            \"buffer_days_no_income_definition\": (\n                \"opening_cash_only_no_future_income_same_as_safety_days\"\n            ),\n            \"closing_buffer_days_no_income_definition\": \"closing_cash_only_no_future_income_display_only\",\n            \"breach_measurement_point\": \"opening_of_month\",\n            \"runway_days_definition\": \"cash_plus_projected_income_display_only\",\n            \"survival_breach_days\": SURVIVAL_BREACH_DAYS,\n            \"buffer_days_no_income_start\": (\n                None\n                if survival_buffer_days(liquid_start, essential_annual) is None\n                else round(survival_buffer_days(liquid_start, essential_annual), 2)\n            ),\n            \"buffer_days_no_income_month_1\": months[0][\"buffer_days_no_income\"],\n            \"buffer_days_no_income_end\": months[-1][\"buffer_days_no_income\"],\n            \"closing_buffer_days_no_income_end\": months[-1][\"closing_buffer_days_no_income\"],\n            \"first_breach_month\": _first_breach_month(months),\n            \"rigid_outflow_total_in_horizon\": _money(\n                sum(row[\"rigid_outflow\"] for row in months)\n            ),\n            \"rigid_outflow_schedule\": rigid_schedule,\n            \"unscheduled_rigid_outflows\": unscheduled_rigid,\n            \"runway_days_start\": months[0][\"runway_days\"],\n            \"runway_days_end\": months[-1][\"runway_days\"],\n            \"trend_status\": trend_status,\n            \"worsening\": trend_status == TREND_DETERIORATING,\n            \"reserve_reached\": months_to_reserve is not None,\n        },\n        \"evidence\": _evidence(\n            {\n                \"horizon_months\": horizon,\n                \"return_assumption\": \"none\",\n                \"rigid_outflow_schedule_source\": \"engine.layering:rigid_outflow_schedule\",\n                **(\n                    {\n                        \"evidence_status\": \"NOT_VERIFIED\",\n                        \"reason_codes\": [\"RIGID_OUTFLOW_SCHEDULE_UNKNOWN\"],\n                    }\n                    if unscheduled_rigid\n                    else {}\n                ),\n            }\n        ),\n    }\n", "zh_i18n.py": "\"\"\"中文 i18n 契约 · 报告渲染层消费端（T-E0-042）。\n\n翻译只作用于引擎报告的渲染层，不触碰引擎结果 JSON，因此快照哈希与审计链不变；\n机器码（risk_id / reason_code / 动作码）继续渲染可见——这是契约而不是残留。\n\n``_CONTRACT_TEXT`` 数据区由 ``scripts/sync_report_i18n.py`` 从 ``web/i18n_zh.json``\n重新生成（该文件才是翻译契约的唯一权威源）。请勿手改数据区；业务函数可手写。\n\n语义对齐对象：web/zh.js 的 ``zhSentence`` / ``zhFirstMatch`` / ``zhTranslateReason``\n（中文控制台与报告导出必须用同一份契约、同一套匹配规则）。\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport re\nfrom typing import Any\n\n# <CONTRACT_BEGIN>\n_CONTRACT_TEXT = r'''\n{\n  \"schema\": \"verity-i18n-zh-v1\",\n  \"note\": \"中文控制台的「中文优先 + 机器码保留」翻译契约。引擎输出英文原文是不可变审计证据（保留在结果 JSON 与 #r-raw 中）；本文件只用于把渲染到页面上的句子翻译成中文，机器码（risk_id/reason_code/run_id）保持原样可见。pattern 为 JavaScript RegExp 源串，cn 为含 {0}{1} 占位符的中文模板；pattern 缺省表示整句静态翻译。\",\n  \"meta\": {\n    \"refuse_max_loss_floor\": 0.15,\n    \"refuse_min_survival_days\": 90,\n    \"high_target_return\": 0.12,\n    \"high_target_max_loss_required\": 0.25,\n    \"review_survival_days\": 180,\n    \"review_debt_pressure\": 0.35,\n    \"underinvested_growth_fraction\": 0.2,\n    \"rebalance_drift_threshold\": 0.05\n  },\n  \"safety\": {\n    \"liquidity_shortfall\": {\n      \"label_cn\": \"流动性缓冲低于审查线\",\n      \"pattern\": \"^Safety days ([\\\\d.]+) is below (\\\\d+)\\\\.$\",\n      \"cn\": \"生存天数 {0} 天低于 {1} 天审查线。\"\n    },\n    \"debt_service_undeterminable\": {\n      \"label_cn\": \"无法计算债务压力\",\n      \"cn\": \"存在债务偿付，但未记录家庭收入，无法计算债务压力。\"\n    },\n    \"debt_pressure\": {\n      \"label_cn\": \"债务偿付占收入比例过高，不安全\",\n      \"pattern\": \"^Debt pressure ([\\\\d.]+)% exceeds (\\\\d+)%\\\\.$\",\n      \"cn\": \"债务偿付占收入的 {0}%，超过 {1}% 的审查线。\"\n    },\n    \"illiquidity_concentration\": {\n      \"label_cn\": \"大部分财富在危机中无法动用\",\n      \"pattern\": \"^(\\\\d+)% of assets are untouchable\\\\.$\",\n      \"cn\": \"有 {0}% 的资产在危机中无法动用。\"\n    },\n    \"life_coverage_gap\": {\n      \"label_cn\": \"寿险保额低于家庭五年收入\",\n      \"pattern\": \"^Coverage ([\\\\d.]+) vs five-year income need ([\\\\d.]+)\\\\.$\",\n      \"cn\": \"保额 {0}，低于五年收入需求 {1}。\"\n    },\n    \"currency_exposure\": {\n      \"label_cn\": \"较大比例财富以外币计价\",\n      \"pattern\": \"^(\\\\d+)% of assets sit outside the reporting currency\\\\.$\",\n      \"cn\": \"有 {0}% 的资产不在记账币种之内。\"\n    },\n    \"no_growth_capacity\": {\n      \"label_cn\": \"没有可投入长期增长的剩余资本\",\n      \"cn\": \"生存、刚性责任与保护需求消耗了全部已记录资产。\"\n    }\n  },\n  \"feasibility\": {\n    \"verdict_meaning\": {\n      \"PASS\": \"目标在家庭可承受的风险预算之内，可以继续进行模拟推演。\",\n      \"REVIEW\": \"目标可能可行，但缓冲偏窄或证据需要人工复核。\",\n      \"REFUSE\": \"目标与这个家庭能够承受的生存底线结构性冲突。\",\n      \"ABSTAIN\": \"证据不足或自相矛盾；Verity 拒绝下判断。\"\n    },\n    \"by_code\": {\n      \"PROFILE_VALIDATION_ERROR\": {\n        \"pattern\": \"^Profile validation failed: ([A-Za-z_]+): (.*)$\",\n        \"cn\": \"档案校验失败：{0}：{1}\"\n      },\n      \"MISSING_REQUIRED_INPUT\": {\n        \"cn\": \"目标年化回报或最大可承受损失无法读成有效数字。\"\n      },\n      \"LOSS_TOLERANCE_BELOW_FLOOR\": {\n        \"pattern\": \"^Maximum tolerable loss ([.\\\\d]+)% is below the ([.\\\\d]+)% floor needed to hold any growth asset through a normal cycle\\\\.$\",\n        \"cn\": \"最大可承受损失 {0}% 低于 {1}% 的底线——持有任何增长资产穿越正常周期都需要这条底线。\"\n      },\n      \"SURVIVAL_DAYS_BELOW_FLOOR\": {\n        \"pattern\": \"^Safety days ([\\\\d.]+) are below the (\\\\d+)-day floor; the household survival floor is not protected\\\\.$\",\n        \"cn\": \"生存天数 {0} 天低于 {1} 天底线，家庭生存底线没有得到保护。\"\n      },\n      \"GOAL_EXCEEDS_RISK_BUDGET\": {\n        \"pattern\": \"^A target of ([.\\\\d]+)% requires accepting a loss budget of at least ([.\\\\d]+)%; the family's stated tolerance is ([.\\\\d]+)%\\\\.$\",\n        \"cn\": \"目标 {0}% 需要至少接受 {1}% 的损失预算；家庭陈述的容忍度为 {2}%。\"\n      },\n      \"SURVIVAL_BUFFER_THIN\": {\n        \"pattern\": \"^Safety days ([\\\\d.]+) are below the (\\\\d+)-day review threshold\\\\.$\",\n        \"cn\": \"生存天数 {0} 天低于 {1} 天审查阈值。\"\n      },\n      \"DEBT_PRESSURE_UNDETERMINABLE\": {\n        \"cn\": \"存在债务偿付但未记录家庭收入，无法核实债务压力。\"\n      },\n      \"DEBT_PRESSURE_HIGH\": {\n        \"pattern\": \"^Debt service consumes ([.\\\\d]+)% of gross income, above the ([.\\\\d]+)% review threshold\\\\.$\",\n        \"cn\": \"债务偿付占毛收入的 {0}%，高于 {1}% 的审查阈值。\"\n      },\n      \"SURVIVAL_LAYER_UNFUNDED\": {\n        \"cn\": \"已记录资产不足以完全覆盖生存基石与刚性责任层。\"\n      },\n      \"GOAL_WITHIN_RISK_BUDGET\": {\n        \"pattern\": \"^Safety days ([\\\\d.]+) clear the (\\\\d+)-day threshold and the ([.\\\\d]+)% target sits inside a ([.\\\\d]+)% loss budget\\\\.$\",\n        \"cn\": \"生存天数 {0} 天高于 {1} 天审查阈值，{2}% 的目标落在 {3}% 的损失预算之内。\"\n      },\n      \"INCONSISTENT_INPUT\": {\n        \"pattern\": \"^The profile is internally contradictory: (.+)$\",\n        \"cn\": \"家庭档案内部互相矛盾：{0}\"\n      }\n    }\n  },\n  \"today\": {\n    \"meaning\": {\n      \"INCREASE_ALLOCATION\": \"让更多资产负债表投入长期目标：增长层过于干涸。\",\n      \"REDUCE_RISK\": \"在生存缓冲越过阈值之前，先降低风险。\",\n      \"HEDGE\": \"某个压力情景会击穿生存底线，先购买保护。\",\n      \"REBALANCE\": \"持仓偏离政策配置过多，重新对齐到政策配置。\",\n      \"HOLD\": \"今天不需要动作：方案已在家庭约束范围之内。\",\n      \"ABSTAIN\": \"Verity 无法为建议背书，因此不下达动作。\"\n    },\n    \"reason\": {\n      \"INCREASE_ALLOCATION\": {\n        \"pattern\": \"^Only ([.\\\\d]+)% of the balance sheet is working for long-term goals\\\\.$\",\n        \"cn\": \"只有 {0}% 的资产负债表在为长期目标工作。\"\n      },\n      \"REDUCE_RISK\": {\n        \"pattern\": \"^Safety days ([\\\\d.]+) are below the (\\\\d+)-day threshold\\\\.$\",\n        \"cn\": \"生存天数 {0} 天低于 {1} 天审查线。\"\n      },\n      \"HEDGE\": {\n        \"pattern\": \"^Stress scenario '([A-Za-z_]+)' breaks the survival floor \\\\(([\\\\d.]+) days remaining\\\\)\\\\.$\",\n        \"cn\": \"压力情景「{0}」击穿了生存底线（仅剩 {1} 天）。\"\n      },\n      \"REBALANCE\": {\n        \"pattern\": \"^Holdings drift ([.\\\\d]+)% from the policy allocation, above the ([.\\\\d]+)% threshold\\\\.$\",\n        \"cn\": \"实际持仓与政策配置偏离 {0}%，高于 {1}% 的再平衡阈值。\"\n      },\n      \"HOLD\": {\n        \"cn\": \"持仓在政策配置带之内；今天无需动作。\"\n      },\n      \"ABSTAIN_VERDICT\": {\n        \"pattern\": \"^Feasibility verdict is ([A-Z_]+), so no action is issued\\\\.$\",\n        \"cn\": \"可行性判定为 {0}，因此不下达动作。\"\n      }\n    }\n  },\n  \"risk_ranking\": {\n    \"ranking_methods\": [\n      {\n        \"pattern\": \"^score = severity_weight \\\\* probability, where probability is a documented deterministic heuristic \\\\(never a forecast\\\\); sorted by score descending\\\\.$\",\n        \"cn\": \"得分 = 严重度权重 × 概率。概率是文档化的确定性启发值，绝非预测；按得分从高到低排序。\"\n      },\n      {\n        \"pattern\": \"^Risk ranking abstained without sufficient household evidence; Verity never assumes what the family has not recorded\\\\.$\",\n        \"cn\": \"缺乏足够的家庭证据，风险排序不下结论；Verity 从不臆测家庭未记录的内容。\"\n      },\n      {\n        \"pattern\": \"^Risk ranking abstained without sufficient household evidence\\\\.$\",\n        \"cn\": \"缺乏足够的家庭证据，风险排序不下结论。\"\n      }\n    ],\n    \"notices\": [\n      {\n        \"pattern\": \"^Risk ranking is decision support, not a prediction\\\\. Probability is an evidence-based heuristic, not a statistical forecast\\\\.$\",\n        \"cn\": \"风险排序是决策支持，不是预测。概率是基于证据的启发值，不是统计预测。\"\n      },\n      {\n        \"pattern\": \"^Risk ranking refused to judge: evidence is insufficient\\\\. No risk is ranked on assumed data\\\\.$\",\n        \"cn\": \"风险排序拒绝下判断：证据不足。不会基于假设数据给任何风险排序。\"\n      },\n      {\n        \"pattern\": \"^Risk ranking refused to judge: evidence is insufficient and Verity never assumes what the family has not recorded\\\\.$\",\n        \"cn\": \"风险排序拒绝下判断：证据不足，Verity 从不臆测家庭未记录的内容。\"\n      }\n    ],\n    \"abstain_reason\": {\n      \"pattern\": \"^Safety computation is unavailable; Verity refuses to rank without it\\\\.$\",\n      \"cn\": \"无法获得安全计算，Verity 拒绝在缺少它的情况下排序。\"\n    }\n  },\n  \"insurance\": {\n    \"disclaimers\": [\n      {\n        \"pattern\": \"^Verity recommends no insurer, no policy and no product\\\\. This audit checks what the family already records; coverage sizing is a documented reference, not a policy quotation\\\\.$\",\n        \"cn\": \"Verity 不推荐任何保险公司、保险产品或商业机构。本审计只核对家庭已记录内容；保额测算是文档化参考，不是保单报价。\"\n      },\n      {\n        \"pattern\": \"^Verity recommends no insurer, no policy and no product\\\\. Any actual placement requires a licensed partner and remains outside E0\\\\.$\",\n        \"cn\": \"Verity 不推荐任何保险公司、保险产品或商业机构。任何实际投保都需要持牌合作伙伴完成，且属于 E0 之外的事项。\"\n      }\n    ],\n    \"warnings\": [\n      {\n        \"match\": \"Coverage gaps describe recorded protection only; Verity recommends no insurer and no product. Any actual placement requires a licensed partner.\",\n        \"cn\": \"保障缺口只描述已记录的保护；Verity 不推荐任何保险公司或产品。任何实际投保都需要持牌合作伙伴完成。\"\n      },\n      {\n        \"pattern\": \"^([一-鿿/]+) coverage gap of ([\\\\d,]+) \\\\(need ([\\\\d,]+), recorded ([\\\\d,]+)\\\\)\\\\.$\",\n        \"cn\": \"{0}缺口 {1}（需求 {2}，已记录 {3}）。\"\n      }\n    ]\n  },\n  \"evidence\": {\n    \"assumptions\": [\n      {\n        \"pattern\": \"^Synthetic data only; no real client records are processed in E0\\\\.$\",\n        \"cn\": \"仅使用合成数据；E0 不处理任何真实客户记录。\"\n      },\n      {\n        \"pattern\": \"^Rates are decimal fractions and money is in major currency units\\\\.$\",\n        \"cn\": \"利率为十进制小数，金额以主要币种单位计。\"\n      },\n      {\n        \"pattern\": \"^Costs, taxes and transaction frictions are simplified placeholders in E0\\\\.$\",\n        \"cn\": \"E0 中的成本、税费与交易摩擦为简化占位值。\"\n      },\n      {\n        \"pattern\": \"^Simulated returns are scenarios, not forecasts, and are not real performance\\\\.$\",\n        \"cn\": \"模拟收益是情景，不是预测，也不是真实业绩。\"\n      },\n      {\n        \"pattern\": \"^No specific security, fund, insurer or product is recommended by the engine\\\\.$\",\n        \"cn\": \"引擎不推荐任何具体证券、基金、保险公司或产品。\"\n    },\n    {\n      \"pattern\": \"^Amounts are read in the household's reporting currency; a per-item currency marks foreign-currency exposure and is never converted\\\\.$\",\n      \"cn\": \"金额按家庭记账币种的主单位读入；逐项币种只标记外币敞口，E0 不做任何汇率换算。\"\n      }\n    ],\n    \"limits\": [\n      {\n        \"match\": \"Synthetic data only; no real client data is used anywhere in E0.\",\n        \"cn\": \"仅使用合成数据；E0 不使用任何真实客户数据。\"\n      },\n      {\n        \"match\": \"Simulation output is not a forecast and is not real performance.\",\n        \"cn\": \"模拟输出不是预测，也不是真实业绩。\"\n      },\n      {\n        \"match\": \"No specific security, fund, insurer or product is recommended.\",\n        \"cn\": \"不推荐任何具体证券、基金、保险公司或产品。\"\n      },\n      {\n        \"match\": \"Missing source or run_id; this result is not independently verifiable.\",\n        \"cn\": \"缺少来源或运行号；该结果无法独立核验。\"\n      }\n    ]\n  },\n  \"risk_notice\": [\n    {\n      \"pattern\": \"^Decision support only\\\\. Not investment, legal, tax or insurance advice\\\\. No production authority; release gate is DENY\\\\.$\",\n      \"cn\": \"仅提供决策支持，不构成投资、法律、税务或保险建议；无生产权限，发布闸门保持 DENY。\"\n    }\n  ],\n  \"status_reason\": {\n    \"protection_abstain\": {\n      \"match\": \"Engine refused to judge; the protection plan follows the same gate.\",\n      \"cn\": \"引擎拒绝下判断，综合保护方案遵循同一闸门。\"\n    },\n    \"protection_abstain_long\": {\n      \"pattern\": \"^Integrated protection plan abstained because the engine refused to judge; evidence is insufficient and Verity never assumes what the family has not recorded\\\\.$\",\n      \"cn\": \"综合保护方案弃权：引擎拒绝下判断，证据不足，Verity 从不臆测家庭未记录的内容。\"\n    },\n    \"protection_abstain_short\": {\n      \"pattern\": \"^Integrated protection plan abstained: evidence is insufficient\\\\. Verity never assumes what the family has not recorded\\\\.$\",\n      \"cn\": \"综合保护方案弃权：证据不足，Verity 从不臆测家庭未记录的内容。\"\n    },\n    \"timeline_abstain\": {\n      \"match\": \"Engine refused to judge; the danger timeline follows the same gate.\",\n      \"cn\": \"引擎拒绝下判断，危险时间轴遵循同一闸门。\"\n    },\n    \"breadwinner_abstain\": {\n      \"match\": \"Engine refused to judge; breadwinner analysis follows the same gate.\",\n      \"cn\": \"引擎拒绝下判断，顶梁柱与保护缺口遵循同一闸门。\"\n    },\n    \"annual_goal_abstain\": {\n      \"match\": \"Engine refused to judge; the annual goal follows the same gate.\",\n      \"cn\": \"引擎拒绝下判断，年度目标与止盈状态遵循同一闸门。\"\n    }\n  },\n  \"validation\": [\n    {\n      \"pattern\": \"^members\\\\[(\\\\d+)\\\\] must be an object$\",\n      \"cn\": \"成员[{0}] 必须是对象\"\n    },\n    {\n      \"pattern\": \"^members\\\\[(\\\\d+)\\\\]\\\\.annual_income must be numeric$\",\n      \"cn\": \"成员[{0}].annual_income 必须是数字\"\n    },\n    {\n      \"pattern\": \"^members\\\\[(\\\\d+)\\\\]\\\\.annual_income must not be negative$\",\n      \"cn\": \"成员[{0}].annual_income 不能为负\"\n    },\n    {\n      \"pattern\": \"^assets\\\\[(\\\\d+)\\\\] must be an object$\",\n      \"cn\": \"资产[{0}] 必须是对象\"\n    },\n    {\n      \"pattern\": \"^assets\\\\[(\\\\d+)\\\\]\\\\.value must be numeric$\",\n      \"cn\": \"资产[{0}].value 必须是数字\"\n    },\n    {\n      \"pattern\": \"^assets\\\\[(\\\\d+)\\\\]\\\\.value must not be negative$\",\n      \"cn\": \"资产[{0}].value 不能为负\"\n    },\n    {\n      \"pattern\": \"^liabilities\\\\[(\\\\d+)\\\\] must be an object$\",\n      \"cn\": \"负债[{0}] 必须是对象\"\n    },\n    {\n      \"pattern\": \"^liabilities\\\\[(\\\\d+)\\\\]\\\\.balance must be numeric$\",\n      \"cn\": \"负债[{0}].balance 必须是数字\"\n    },\n    {\n      \"pattern\": \"^liabilities\\\\[(\\\\d+)\\\\]\\\\.balance must not be negative$\",\n      \"cn\": \"负债[{0}].balance 不能为负\"\n    },\n    {\n      \"pattern\": \"^liabilities\\\\[(\\\\d+)\\\\]\\\\.mandatory_payment must be numeric$\",\n      \"cn\": \"负债[{0}].mandatory_payment 必须是数字\"\n    },\n    {\n      \"pattern\": \"^protection\\\\[(\\\\d+)\\\\] must be an object$\",\n      \"cn\": \"保障[{0}] 必须是对象\"\n    },\n    {\n      \"pattern\": \"^protection\\\\[(\\\\d+)\\\\]\\\\.coverage must be a non-negative number$\",\n      \"cn\": \"保障[{0}].coverage 必须是非负数\"\n    },\n    {\n      \"pattern\": \"^protection\\\\[(\\\\d+)\\\\]\\\\.annual_premium must be a non-negative number$\",\n      \"cn\": \"保障[{0}].annual_premium 必须是非负数\"\n    },\n    {\n      \"pattern\": \"^future_rigid_outflows\\\\[(\\\\d+)\\\\] must be an object$\",\n      \"cn\": \"未来刚性支出[{0}] 必须是对象\"\n    },\n    {\n      \"pattern\": \"^future_rigid_outflows\\\\[(\\\\d+)\\\\]\\\\.amount must be non-negative$\",\n      \"cn\": \"未来刚性支出[{0}].amount 必须非负\"\n    },\n    {\n      \"pattern\": \"^future_rigid_outflows\\\\[(\\\\d+)\\\\]\\\\.years_until_due must be non-negative$\",\n      \"cn\": \"未来刚性支出[{0}].years_until_due 必须非负\"\n    },\n    {\n      \"match\": \"profile is not an object\",\n      \"cn\": \"档案（profile）不是对象\"\n    },\n    {\n      \"match\": \"members must be a non-empty list\",\n      \"cn\": \"成员（members）必须是非空列表\"\n    },\n    {\n      \"match\": \"annual_expenses_essential must be numeric\",\n      \"cn\": \"annual_expenses_essential 必须是数字\"\n    },\n    {\n      \"match\": \"annual_expenses_essential must be greater than zero\",\n      \"cn\": \"annual_expenses_essential 必须大于零\"\n    },\n    {\n      \"match\": \"annual_expenses_discretionary must be numeric\",\n      \"cn\": \"annual_expenses_discretionary 必须是数字\"\n    },\n    {\n      \"match\": \"annual_expenses_discretionary must not be negative\",\n      \"cn\": \"annual_expenses_discretionary 不能为负\"\n    },\n    {\n      \"match\": \"assets must be a list\",\n      \"cn\": \"assets 必须是列表\"\n    },\n    {\n      \"match\": \"liabilities must be a list\",\n      \"cn\": \"liabilities 必须是列表\"\n    },\n    {\n      \"match\": \"protection must be a list\",\n      \"cn\": \"protection 必须是列表\"\n    },\n    {\n      \"match\": \"future_rigid_outflows must be a list\",\n      \"cn\": \"future_rigid_outflows 必须是列表\"\n    },\n    {\n      \"match\": \"investment_horizon_years must be numeric\",\n      \"cn\": \"investment_horizon_years 必须是数字\"\n    },\n    {\n      \"match\": \"investment_horizon_years must be greater than zero\",\n      \"cn\": \"investment_horizon_years 必须大于零\"\n    },\n    {\n      \"match\": \"target_annual_return must be numeric\",\n      \"cn\": \"target_annual_return 必须是数字\"\n    },\n    {\n      \"match\": \"target_annual_return must not be negative\",\n      \"cn\": \"target_annual_return 不能为负\"\n    },\n    {\n      \"match\": \"target_annual_return above 100% per year is not a credible input\",\n      \"cn\": \"target_annual_return 每年超过 100% 不是可信输入\"\n    },\n    {\n      \"match\": \"max_tolerable_loss_pct must be numeric\",\n      \"cn\": \"max_tolerable_loss_pct 必须是数字\"\n    },\n    {\n      \"match\": \"max_tolerable_loss_pct must be a fraction between 0 and 1\",\n      \"cn\": \"max_tolerable_loss_pct 必须是 0 到 1 之间的小数\"\n    },\n    {\n      \"match\": \"profile is not an object\",\n      \"cn\": \"档案（profile）不是对象\"\n    },\n    {\n      \"pattern\": \"^total liabilities exceed total assets by more than (\\\\d+)x$\",\n      \"cn\": \"总负债超过总资产的 {0} 倍以上\"\n    },\n    {\n      \"match\": \"the profile is not internally coherent\",\n      \"cn\": \"档案内部不自洽\"\n    },\n    {\n      \"pattern\": \"^currency must be a three-letter code, for example CNY$\",\n      \"cn\": \"币种必须是三位字母代码，例如 CNY\"\n    },\n    {\n      \"pattern\": \"^([a-z_]+)\\\\[(\\\\d+)\\\\]\\\\.currency must be a three-letter code$\",\n      \"cn\": \"{0}[{1}].currency 必须是三位字母代码\"\n    },\n    {\n      \"pattern\": \"^recorded currency ([A-Z]{3}) \\\\((.*)\\\\) marks a foreign-currency exposure against reporting currency ([A-Z]{3}); E0 performs no FX conversion and reads the recorded amount in ([A-Z]{3}) major units$\",\n      \"cn\": \"外币计价标记 {0}（{1}）：E0 不做汇率换算，金额按记账币种 {2} 的主单位读入，该资产会计入汇率压力情景。\"\n    },\n    {\n      \"pattern\": \"^recorded items use several currencies \\\\((.*)\\\\); E0 has no FX model and will not add amounts across currencies$\",\n      \"cn\": \"记录的项目使用了多种币种（{0}）；E0 没有汇率模型，不会把不同币种的金额直接相加。\"\n    },\n    {\n      \"pattern\": \"^(.+) is at or above the E0 plausibility ceiling; the engine will not judge a household on a number it cannot stand behind$\",\n      \"cn\": \"{0} 达到或超过 E0 的可信上限；引擎不会用一个自己都无法负责的数字来判断一个家庭。\"\n    },\n    {\n      \"pattern\": \"^members\\\\[(\\\\d+)\\\\]\\\\.age must be between 0 and 130 years$\",\n      \"cn\": \"成员[{0}] 的年龄必须在 0 到 130 岁之间\"\n    },\n    {\n      \"pattern\": \"^investment_horizon_years above (\\\\d+) is outside the E0 contract$\",\n      \"cn\": \"investment_horizon_years 超过 {0} 年，超出 E0 契约范围\"\n    }\n  ]\n}\n'''\n\nCONTRACT: dict[str, Any] = json.loads(_CONTRACT_TEXT)\n\n\ndef zh_sentence(entry, sentence):\n    \"\"\"Mirror of web/zh.js::zhSentence. 返回 (matched, cn)。\"\"\"\n    if not entry:\n        return False, \"\"\n    template = entry.get(\"cn\", \"\")\n    if entry.get(\"match\") is not None and str(sentence or \"\") != str(entry[\"match\"]):\n        return False, \"\"\n    pattern = entry.get(\"pattern\")\n    if not pattern:\n        return True, template\n    m = re.search(pattern, str(sentence or \"\"))\n    if not m:\n        return False, \"\"\n    out = template\n    for i in range(1, len(m.groups()) + 1):\n        out = out.replace(\"{%d}\" % (i - 1), m.group(i) or \"\")\n    if re.search(r\"\\{\\d+\\}\", out):\n        return False, \"\"\n    return True, out\n\n\ndef zh_first_match(entries, sentence):\n    \"\"\"Mirror of web/zh.js::zhFirstMatch。命中返回中文；否则 None。\"\"\"\n    for entry in entries or []:\n        matched, cn = zh_sentence(entry, sentence)\n        if matched:\n            return cn\n    return None\n\n\ndef looks_english(text):\n    \"\"\"可见文本里是否存在「连续英文」片段（判断某字段是否需要转译）。\"\"\"\n    return bool(re.search(r\"[A-Za-z]{2,}[^\\u4e00-\\u9fff]{2,}[A-Za-z]{2,}\", str(text or \"\")))\n\n\ndef zh_or_fallback(sentence, cn):\n    \"\"\"命中返回中文；未命中且原文是英文整句时给中文占位（原文保留在结果 JSON\n    与审计记录里），未命中且原文不是英文时原样返回。\"\"\"\n    if cn:\n        return cn\n    if looks_english(sentence):\n        return \"（该条为英文原文，保留于结果 JSON 与审计记录）\"\n    return sentence or \"\"\n\n\ndef validation_fragment_cn(fragment):\n    \"\"\"档案校验片段翻译；英文且未命中时返回 None（调用方丢弃该片段）。\"\"\"\n    hit = zh_first_match(CONTRACT[\"validation\"], fragment)\n    if hit is not None:\n        return hit\n    return None if looks_english(fragment) else fragment\n\n\ndef feasibility_reason_cn(code, sentence):\n    \"\"\"Mirror of web/zh.js::zhTranslateReason。返回 (matched, cn)。\"\"\"\n    if code == \"INCONSISTENT_INPUT\":\n        m = re.match(r\"^The profile is internally contradictory: (.*)$\", str(sentence or \"\"), re.S)\n        if not m:\n            return False, \"\"\n        body = \"；\".join(\n            frag for frag in (validation_fragment_cn(f) for f in m.group(1).split(\"; \")) if frag\n        )\n        if not body:\n            return False, \"\"\n        return True, f\"家庭档案内部互相矛盾：{body}\"\n    if code == \"PROFILE_VALIDATION_ERROR\":\n        m = re.match(r\"^Profile validation failed: ([A-Za-z_]+): (.*)$\", str(sentence or \"\"), re.S)\n        if not m:\n            return False, \"\"\n        msg = validation_fragment_cn(m.group(2))\n        if not msg:\n            return False, \"\"\n        return True, f\"档案校验失败：{m.group(1)}：{msg}\"\n    by_code = (CONTRACT.get(\"feasibility\") or {}).get(\"by_code\") or {}\n    return zh_sentence(by_code.get(code), sentence)\n\n\ndef verdict_meaning_cn(verdict):\n    \"\"\"总体判断的引擎口径中文（feasibility.verdict_meaning）。\"\"\"\n    table = (CONTRACT.get(\"feasibility\") or {}).get(\"verdict_meaning\") or {}\n    if isinstance(table, dict):\n        return table.get(verdict)\n    return None\n\n\ndef today_reason_cn(result):\n    \"\"\"Mirror of web/zh.js::renderVerdict 的 reasonCn 逻辑。返回 (meaning_cn, reason_cn)。\"\"\"\n    today = result.get(\"today\") or {}\n    feasibility = result.get(\"feasibility\") or {}\n    verdict = result.get(\"verdict\") or \"ABSTAIN\"\n    action = today.get(\"action\") or \"ABSTAIN\"\n    meaning_cn = (CONTRACT.get(\"today\") or {}).get(\"meaning\") or {}\n    meaning_cn = meaning_cn.get(action) if isinstance(meaning_cn, dict) else \"\"\n    if verdict in (\"ABSTAIN\", \"REFUSE\"):\n        codes = feasibility.get(\"reason_codes\") or []\n        reasons = feasibility.get(\"reasons\") or []\n        matched = False\n        if codes and reasons:\n            matched, cn = feasibility_reason_cn(codes[0], reasons[0])\n        if matched:\n            return meaning_cn, f\"可行性判定为 {verdict}，因此不下达动作。{cn}\"\n        return meaning_cn, zh_or_fallback(today.get(\"action_reason\", \"\"), \"\")\n    reason_table = (CONTRACT.get(\"today\") or {}).get(\"reason\") or {}\n    entry = reason_table.get(action) if isinstance(reason_table, dict) else None\n    _matched, cn = zh_sentence(entry, today.get(\"action_reason\", \"\"))\n    return meaning_cn, zh_or_fallback(today.get(\"action_reason\", \"\"), cn)\n\n\ndef safety_risk_cn(risk):\n    \"\"\"安全风险 label / detail 的中文（safety[risk_id]）。\"\"\"\n    entry = (CONTRACT.get(\"safety\") or {}).get(risk.get(\"risk_id\") or \"\") or {}\n    if isinstance(entry, dict):\n        label_cn = entry.get(\"label_cn\") or risk.get(\"label\") or \"\"\n    else:\n        label_cn = risk.get(\"label\") or \"\"\n    _matched, detail_cn = zh_sentence(entry, risk.get(\"detail\") or \"\")\n    return label_cn, zh_or_fallback(risk.get(\"detail\") or \"\", detail_cn)\n\n\ndef risk_ranking_cn(ranking):\n    \"\"\"风险排序方法与免责说明的中文。\"\"\"\n    i18n = CONTRACT.get(\"risk_ranking\") or {}\n    method_cn = zh_first_match(i18n.get(\"ranking_methods\"), ranking.get(\"ranking_method\") or \"\")\n    notice_cn = zh_first_match(i18n.get(\"notices\"), ranking.get(\"notice\") or \"\")\n    return (\n        zh_or_fallback(ranking.get(\"ranking_method\") or \"\", method_cn),\n        zh_or_fallback(ranking.get(\"notice\") or \"\", notice_cn),\n    )\n\n\ndef insurance_warning_cn(warning):\n    \"\"\"保险审计 warning 的中文（insurance.warnings + disclaimers 兜底）。\"\"\"\n    i18n = CONTRACT.get(\"insurance\") or {}\n    entry = i18n.get(\"warnings\") or []\n    cn = zh_first_match(entry, warning)\n    if cn is None:\n        cn = zh_first_match(i18n.get(\"disclaimers\"), warning)\n    return zh_or_fallback(warning, cn)\n\n\ndef evidence_item_cn(item, kind):\n    \"\"\"证据假设 / 已知限制 的中文。kind ∈ {\\\"assumptions\\\", \\\"limits\\\"}。\"\"\"\n    entries = (CONTRACT.get(\"evidence\") or {}).get(kind) or []\n    cn = zh_first_match(entries, item)\n    return zh_or_fallback(item, cn)\n\n\ndef risk_notice_cn(sentence):\n    \"\"\"风险声明的中文（risk_notice 契约）。\"\"\"\n    cn = zh_first_match(CONTRACT.get(\"risk_notice\") or [], sentence)\n    return zh_or_fallback(sentence, cn)\n\n\ndef status_reason_cn(kind, sentence):\n    \"\"\"模块级默认原因（protection / timeline 等的 status_reason）中文。\"\"\"\n    table = CONTRACT.get(\"status_reason\") or {}\n    entry = table.get(kind) if isinstance(table, dict) else None\n    _matched, cn = zh_sentence(entry, sentence)\n    return zh_or_fallback(sentence, cn)\n\n\ndef protection_reason_cn(reason):\n    \"\"\"综合保护方案的状态原因 / 说明（status_reason / notice）中文。\"\"\"\n    table = CONTRACT.get(\"status_reason\") or {}\n    if isinstance(table, dict):\n        for key in (\"protection_abstain\", \"protection_abstain_long\", \"protection_abstain_short\"):\n            _matched, cn = zh_sentence(table.get(key), reason)\n            if cn:\n                return cn\n    return zh_or_fallback(reason, \"\")\n"};
